(window.__qhadithX=window.__qhadithX||{})[33]={"4":[{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3199","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3199","x":"Narrated Zuhair:\n\n\"Qabus bin Abi Zabyan narrated to us, that his father narrated to him, he said: 'We said to Ibn 'Abbas: \"What is the meaning of the saying of Allah the Mighty and Sublime: Allah has not made for any man two hears inside his body.? (33:4)\" He said: \"The Prophet of Allah (ﷺ) stood one day for Salat, then he was unsure (regarding how much he had prayed). The hypocrites who prayed with him said: 'Don't you see that he has two hearts, a heart with you and another with them?' So Allah revealed: 'Allah has not made for any man two hearts inside his body.'\"","ar":"حَدَّثَنَا عَبْدُ اللَّهِ بْنُ عَبْدِ الرَّحْمَنِ، أَخْبَرَنَا صَاعِدٌ الْحَرَّانِيُّ، حَدَّثَنَا زُهَيْرٌ، أَخْبَرَنَا قَابُوسُ بْنُ أَبِي ظَبْيَانَ، أَنَّ أَبَاهُ، حَدَّثَهُ قَالَ قُلْنَا لاِبْنِ عَبَّاسٍ أَرَأَيْتَ قَوْلَ اللَّهِ عَزَّ وَجَلَّ ‏:‏ ‏(‏ما جَعَلَ اللَّهُ لِرَجُلٍ مِنْ قَلْبَيْنِ فِي جَوْفِهِ ‏)‏ مَا عَنَى بِذَلِكَ قَالَ قَامَ نَبِيُّ اللَّهِ صلى الله عليه وسلم يَوْمًا يُصَلِّي فَخَطَرَ خَطْرَةً فَقَالَ الْمُنَافِقُونَ الَّذِينَ يُصَلُّونَ مَعَهُ أَلاَ تَرَى أَنَّ لَهُ قَلْبَيْنِ قَلْبًا مَعَكُمْ وَقَلْبًا مَعَهُمْ ‏.‏ فَأَنْزَلَ اللَّهُ ‏:‏ ‏(‏ما جَعَلَ اللَّهُ لِرَجُلٍ مِنْ قَلْبَيْنِ فِي جَوْفِهِ ‏)‏ ‏.‏ حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، حَدَّثَنِي أَحْمَدُ بْنُ يُونُسَ، حَدَّثَنَا زُهَيْرٌ، نَحْوَهُ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ ‏.‏","v":[]}],"5":[{"c":"Sahih Bukhari","r":"Hadith 4000","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4000","x":"Narrated `Aisha:\n\n(the wife of the Prophet) Abu Hudhaifa, one of those who fought the battle of Badr, with Allah's Apostle adopted Salim as his son and married his niece Hind bint Al-Wahd bin `Utba to him' and Salim was a freed slave of an Ansari woman. Allah's Messenger (ﷺ) also adopted Zaid as his son. In the Prelslamic period of ignorance the custom was that, if one adopted a son, the people would call him by the name of the adopted-father whom he would inherit as well, till Allah revealed: \"Call them (adopted sons) By (the names of) their fathers.\" (33.5)","ar":"حَدَّثَنَا يَحْيَى بْنُ بُكَيْرٍ، حَدَّثَنَا اللَّيْثُ، عَنْ عُقَيْلٍ، عَنِ ابْنِ شِهَابٍ، أَخْبَرَنِي عُرْوَةُ بْنُ الزُّبَيْرِ، عَنْ عَائِشَةَ ـ رضى الله عنها ـ زَوْجِ النَّبِيِّ صلى الله عليه وسلم أَنَّ أَبَا حُذَيْفَةَ وَكَانَ مِمَّنْ شَهِدَ بَدْرًا مَعَ رَسُولِ اللَّهِ صلى الله عليه وسلم تَبَنَّى سَالِمًا، وَأَنْكَحَهُ بِنْتَ أَخِيهِ هِنْدَ بِنْتَ الْوَلِيدِ بْنِ عُتْبَةَ ـ وَهْوَ مَوْلًى لاِمْرَأَةٍ مِنَ الأَنْصَارِ ـ كَمَا تَبَنَّى رَسُولُ اللَّهِ صلى الله عليه وسلم زَيْدًا، وَكَانَ مَنْ تَبَنَّى رَجُلاً فِي الْجَاهِلِيَّةِ دَعَاهُ النَّاسُ إِلَيْهِ، وَوَرِثَ مِنْ مِيرَاثِهِ حَتَّى أَنْزَلَ اللَّهُ تَعَالَى ‏{‏ادْعُوهُمْ لآبَائِهِمْ‏}‏ فَجَاءَتْ سَهْلَةُ النَّبِيَّ صلى الله عليه وسلم، فَذَكَرَ الْحَدِيثَ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4782","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4782","x":"Narrated `Abdullah bin `Umar:\n\nWe used not to call Zaid bin Haritha the freed slave of Allah's Messenger (ﷺ) except Zaid bin Muhammad till the Qu'anic Verse was revealed: \"Call them (adopted sons) by (the names of) their fathers. That is more than just in the Sight of Allah.\" (33.5)","ar":"حَدَّثَنَا مُعَلَّى بْنُ أَسَدٍ، حَدَّثَنَا عَبْدُ الْعَزِيزِ بْنُ الْمُخْتَارِ، حَدَّثَنَا مُوسَى بْنُ عُقْبَةَ، قَالَ حَدَّثَنِي سَالِمٌ، عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ ـ رضى الله عنهما ـ أَنَّ زَيْدَ بْنَ حَارِثَةَ، مَوْلَى رَسُولِ اللَّهِ صلى الله عليه وسلم مَا كُنَّا نَدْعُوهُ إِلاَّ زَيْدَ ابْنَ مُحَمَّدٍ حَتَّى نَزَلَ الْقُرْآنُ ‏{‏ادْعُوهُمْ لآبَائِهِمْ هُوَ أَقْسَطُ عِنْدَ اللَّهِ‏}‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 5088","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-5088","x":"Narrated `Aisha:\n\nAbu Hudhaifa bin `Utba bin Rabi`a bin `Abdi Shams who had witnessed the battle of Badr along with the Prophet (ﷺ) adopted Salim as his son, to whom he married his niece, Hind bint Al-Walid bin `Utba bin Rabi`a; and Salim was the freed slave of an Ansar woman, just as the Prophet (ﷺ) had adopted Zaid as his son. It was the custom in the Pre-lslamic Period that if somebody adopted a boy, the people would call him the son of the adoptive father and he would be the latter's heir. But when Allah revealed the Divine Verses: 'Call them by (the names of) their fathers... your freed-slaves,' (33.5) the adopted persons were called by their fathers' names. The one whose father was not known, would be regarded as a Maula and your brother in religion. Later on Sahla bint Suhail bin `Amr Al-Quraishi Al-`Amiri-- and she was the wife of Abu- Hudhaifa bin `Utba--came to the Prophet (ﷺ) and said, \"O Allah's Messenger (ﷺ)! We used to consider Salim as our (adopted) son, and now Allah has revealed what you know (regarding adopted sons).\" The sub-narrator then mentioned the rest of the narration.","ar":"حَدَّثَنَا أَبُو الْيَمَانِ، أَخْبَرَنَا شُعَيْبٌ، عَنِ الزُّهْرِيِّ، قَالَ أَخْبَرَنِي عُرْوَةُ بْنُ الزُّبَيْرِ، عَنْ عَائِشَةَ ـ رضى الله عنها ـ أَنَّ أَبَا حُذَيْفَةَ بْنَ عُتْبَةَ بْنِ رَبِيعَةَ بْنِ عَبْدِ شَمْسٍ،، وَكَانَ، مِمَّنْ شَهِدَ بَدْرًا مَعَ النَّبِيِّ صلى الله عليه وسلم تَبَنَّى سَالِمًا، وَأَنْكَحَهُ بِنْتَ أَخِيهِ هِنْدَ بِنْتَ الْوَلِيدِ بْنِ عُتْبَةَ بْنِ رَبِيعَةَ وَهْوَ مَوْلًى لاِمْرَأَةٍ مِنَ الأَنْصَارِ، كَمَا تَبَنَّى النَّبِيُّ صلى الله عليه وسلم زَيْدًا، وَكَانَ مَنْ تَبَنَّى رَجُلاً فِي الْجَاهِلِيَّةِ دَعَاهُ النَّاسُ إِلَيْهِ وَوَرِثَ مِنْ مِيرَاثِهِ حَتَّى أَنْزَلَ اللَّهُ ‏{‏ادْعُوهُمْ لآبَائِهِمْ‏}‏ إِلَى قَوْلِهِ ‏{‏وَمَوَالِيكُمْ‏}‏ فَرُدُّوا إِلَى آبَائِهِمْ، فَمَنْ لَمْ يُعْلَمْ لَهُ أَبٌ كَانَ مَوْلًى وَأَخًا فِي الدِّينِ، فَجَاءَتْ سَهْلَةُ بِنْتُ سُهَيْلِ بْنِ عَمْرٍو الْقُرَشِيِّ ثُمَّ الْعَامِرِيِّ ـ وَهْىَ امْرَأَةُ أَبِي حُذَيْفَةَ ـ النَّبِيَّ صلى الله عليه وسلم فَقَالَتْ يَا رَسُولَ اللَّهِ إِنَّا كُنَّا نَرَى سَالِمًا وَلَدًا وَقَدْ أَنْزَلَ اللَّهُ فِيهِ مَا قَدْ عَلِمْتَ فَذَكَرَ الْحَدِيثَ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 6663","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-6663","x":"Narrated `Aisha:\n\nregarding: 'Allah will not call you to account for that which is unintentional in your oaths...' (2.225) This Verse was revealed concerning such oath formulas as: 'No, by Allah!' and 'Yes, by Allah!' something against his oath due to forgetfulness should he make expiation?). And the Statement of Allah: 'And there is no blame on you if you make a mistake therein.' (33.5) And Allah said:-- '(Moses said to Khadir): Call me not to account for what I forgot.' (18.73)","ar":"حَدَّثَنِي مُحَمَّدُ بْنُ الْمُثَنَّى، حَدَّثَنَا يَحْيَى، عَنْ هِشَامٍ، قَالَ أَخْبَرَنِي أَبِي، عَنْ عَائِشَةَ ـ رضى الله عنها ‏{‏لاَ يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ‏}‏ قَالَ قَالَتْ أُنْزِلَتْ فِي قَوْلِهِ لاَ، وَاللَّهِ بَلَى وَاللَّهِ‏.‏","v":[]},{"c":"Muwatta Malik","r":"Book 30, Hadith 1287","u":"https://quranx.com/Hadith/Malik/In-Book/Book-30/Hadith-1287","x":"Yahya related to me from Malik from Ibn Shihab that he was asked about the suckling of an older person. He said, ''Urwa ibn az-Zubayr informed me that Abu Hudhayfa ibn Utba ibn Rabia, one of the companions of the Messenger of Allah, may Allah bless him and grant him peace, who was present at Badr, adopted Salim (who is called Salim, the mawla of Abu Hudhayfa) as the Messenger of Allah, may Allah bless him and grant him peace, adopted Zayd ibn Haritha. He thought of him as his son, and Abu Hudhayfa married him to his brother's sister, Fatima bint al-Walid ibn Utba ibn Rabia, who was at that time among the first emigrants. She was one of the best unmarried women of the Quraysh. When Allah the Exalted sent down in His Book what He sent down about Zayd ibn Haritha, 'Call them after their true fathers. That is more equitable in the sight of Allah. If you do not know who their fathers were then they are your brothers in the deen and your mawali,' (Sura 33 ayat 5) people in this position were traced back to their fathers. When the father was not known, they were traced to their mawla. \"Sahla bint Suhayl who was the wife of Abu Hudhayfa, and one of the tribe of Amr ibn Luayy, came to the Messenger of Allah, may Allah bless him and grant him peace, and said, 'Messenger of Allah! We think of Salim as a son and he comes in to see me while I am uncovered. We only have one room, so what do you think about the situation?' The Messenger of Allah, may Allah bless him and grant him peace, said, 'Give him five drinks of your milk and he will be mahram by it.' She then saw him as a foster son. A'isha umm al-muminin took that as a precedent for whatever men she wanted to be able to come to see her. She ordered her sister, Umm Kulthum bint Abi Bakr as-Siddiq and the daughters of her brother to give milk to whichever men she wanted to be able to come in to see her. The rest of the wives of the Prophet, may Allah bless him and grant him peace, refused to let anyone come in to them by such nursing. They said, 'No! By Allah! We think that what the Messenger of Allah, may Allah bless him and grant him peace, ordered Sahla bint Suhayl to do was only an indulgence concerning the nursing of Salim alone. No! By Allah! No one will come in upon us by such nursing!' \"This is what the wives of the Prophet, may Allah bless him and grant him peace, thought about the suckling of an older person.\"","ar":"حَدَّثَنِي يَحْيَى، عَنْ مَالِكٍ، عَنِ ابْنِ شِهَابٍ، أَنَّهُ سُئِلَ عَنْ رَضَاعَةِ الْكَبِيرِ، فَقَالَ أَخْبَرَنِي عُرْوَةُ بْنُ الزُّبَيْرِ، أَنَّ أَبَا حُذَيْفَةَ بْنَ عُتْبَةَ بْنِ رَبِيعَةَ، وَكَانَ، مِنْ أَصْحَابِ رَسُولِ اللَّهِ صلى الله عليه وسلم وَكَانَ قَدْ شَهِدَ بَدْرًا وَكَانَ تَبَنَّى سَالِمًا الَّذِي يُقَالُ لَهُ سَالِمٌ مَوْلَى أَبِي حُذَيْفَةَ كَمَا تَبَنَّى رَسُولُ اللَّهِ صلى الله عليه وسلم زَيْدَ بْنَ حَارِثَةَ وَأَنْكَحَ أَبُو حُذَيْفَةَ سَالِمًا وَهُوَ يَرَى أَنَّهُ ابْنُهُ أَنْكَحَهُ بِنْتَ أَخِيهِ فَاطِمَةَ بِنْتَ الْوَلِيدِ بْنِ عُتْبَةَ بْنِ رَبِيعَةَ وَهِيَ يَوْمَئِذٍ مِنَ الْمُهَاجِرَاتِ الأُوَلِ وَهِيَ مِنْ أَفْضَلِ أَيَامَى قُرَيْشٍ فَلَمَّا أَنْزَلَ اللَّهُ تَعَالَى فِي كِتَابِهِ فِي زَيْدِ بْنِ حَارِثَةَ مَا أَنْزَلَ فَقَالَ ‏{‏ادْعُوهُمْ لآبَائِهِمْ هُوَ أَقْسَطُ عِنْدَ اللَّهِ فَإِنْ لَمْ تَعْلَمُوا آبَاءَهُمْ فَإِخْوَانُكُمْ فِي الدِّينِ وَمَوَالِيكُمْ‏}‏ رُدَّ كُلُّ وَاحِدٍ مِنْ أُولَئِكَ إِلَى أَبِيهِ فَإِنْ لَمْ يُعْلَمْ أَبُوهُ رُدَّ إِلَى مَوْلاَهُ فَجَاءَتْ سَهْلَةُ بِنْتُ سُهَيْلٍ وَهِيَ امْرَأَةُ أَبِي حُذَيْفَةَ وَهِيَ مِنْ بَنِي عَامِرِ بْنِ لُؤَىٍّ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَقَالَتْ يَا رَسُولَ اللَّهِ كُنَّا نَرَى سَالِمًا وَلَدًا وَكَانَ يَدْخُلُ عَلَىَّ وَأَنَا فُضُلٌ وَلَيْسَ لَنَا إِلاَّ بَيْتٌ وَاحِدٌ فَمَاذَا تَرَى فِي شَأْنِهِ فَقَالَ لَهَا رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ أَرْضِعِيهِ خَمْسَ رَضَعَاتٍ فَيَحْرُمُ بِلَبَنِهَا ‏\"‏ ‏.‏ وَكَانَتْ تَرَاهُ ابْنًا مِنَ الرَّضَاعَةِ فَأَخَذَتْ بِذَلِكَ عَائِشَةُ أُمُّ الْمُؤْمِنِينَ فِيمَنْ كَانَتْ تُحِبُّ أَنْ يَدْخُلَ عَلَيْهَا مِنَ الرِّجَالِ فَكَانَتْ تَأْمُرُ أُخْتَهَا أُمَّ كُلْثُومٍ بِنْتَ أَبِي بَكْرٍ الصِّدِّيقِ وَبَنَاتِ أَخِيهَا أَنْ يُرْضِعْنَ مَنْ أَحَبَّتْ أَنْ يَدْخُلَ عَلَيْهَا مِنَ الرِّجَالِ وَأَبَى سَائِرُ أَزْوَاجِ النَّبِيِّ صلى الله عليه وسلم أَنْ يَدْخُلَ عَلَيْهِنَّ بِتِلْكَ الرَّضَاعَةِ أَحَدٌ مِنَ النَّاسِ وَقُلْنَ لاَ وَاللَّهِ مَا نَرَى الَّذِي أَمَرَ بِهِ رَسُولُ اللَّهِ صلى الله عليه وسلم سَهْلَةَ بِنْتَ سُهَيْلٍ إِلاَّ رُخْصَةً مِنْ رَسُولِ اللَّهِ صلى الله عليه وسلم فِي رَضَاعَةِ سَالِمٍ وَحْدَهُ لاَ وَاللَّهِ لاَ يَدْخُلُ عَلَيْنَا بِهَذِهِ الرَّضَاعَةِ أَحَدٌ فَعَلَى هَذَا كَانَ أَزْوَاجُ النَّبِيِّ صلى الله عليه وسلم فِي رَضَاعَةِ الْكَبِيرِ ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 1476a","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-1476a","x":"'A'isha (Allah be pleased with her) reported that Allah's Messenger (ﷺ) sought our permission when he had a (turn to spend) a day with (one of his wives) amongst us (whereas he wanted to visit his other wives too). It was after this that this verse was revealed:\n\n\" Thou mayest put off whom thou pleasest of them, and take for thee whom thou pleasest\" (xxxiii. 5). Mu'adha said to her: What did you say to Allah's Messenger (ﷺ) when he sought your permission? She said: I used to say: If it had the option in this I would not have (allowed anyone) to have precedence over me.","ar":"حَدَّثَنَا سُرَيْجُ بْنُ يُونُسَ، حَدَّثَنَا عَبَّادُ بْنُ عَبَّادٍ، عَنْ عَاصِمٍ، عَنْ مُعَاذَةَ الْعَدَوِيَّةِ، عَنْ عَائِشَةَ، قَالَتْ كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يَسْتَأْذِنُنَا إِذَا كَانَ فِي يَوْمِ الْمَرْأَةِ مِنَّا بَعْدَ مَا نَزَلَتْ ‏{‏ تُرْجِي مَنْ تَشَاءُ مِنْهُنَّ وَتُؤْوِي إِلَيْكَ مَنْ تَشَاءُ‏}‏ فَقَالَتْ لَهَا مُعَاذَةُ فَمَا كُنْتِ تَقُولِينَ لِرَسُولِ اللَّهِ صلى الله عليه وسلم إِذَا اسْتَأْذَنَكِ قَالَتْ كُنْتُ أَقُولُ إِنْ كَانَ ذَاكَ إِلَىَّ لَمْ أُوثِرْ أَحَدًا عَلَى نَفْسِي ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3207","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3207","x":"Narrated 'Aishah [may Allah be pleased with her]:\n\n\"If the Messenger of Allah (ﷺ) was to have concealed anything that was revealed to him, then he would have concealed these Ayat: 'When you said to him on whom Allah has bestowed grace (meaning by Islam); and you have done a favor (meaning that he was a slave and you freed him) \"Keep your wife to yourself, and have Taqwa of Allah.\" But you did hide in yourself that which Allah will make manifest, you did fear the people whereas Allah had better right that you should fear Him' up to His saying: 'And Allah's command must be fulfilled (33:37).' They said: 'He married his wife's son, so Allah revealed: 'Muhammad is not the father of any of your men, but he is the Messenger of Allah and the Last of the Prophets (33:40).' The Messenger of Allah (ﷺ) had taken (adopted) him as a son when he was small, and he remained being called 'Zaid bin Muhammad' until he grew up to adulthood, then Allah revealed: 'Call them by their fathers, then your brothers in religion and your Mawali (33:5). (Say) So-and-so, the Mawla of so-and-so, and; So-and-so, the brother of so-and-so. 'That is more just with Allah' meaning that doing that is more just to Allah.\"","ar":"حَدَّثَنَا عَلِيُّ بْنُ حُجْرٍ، أَخْبَرَنَا دَاوُدُ بْنُ الزِّبْرِقَانِ، عَنْ دَاوُدَ بْنِ أَبِي هِنْدٍ، عَنِ الشَّعْبِيِّ، عَنْ عَائِشَةَ، رضى الله عنها قَالَتْ لَوْ كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم كَاتِمًا شَيْئًا مِنَ الْوَحْىِ لَكَتَمَ هَذِهِ الآيَةَ ‏:‏ ‏(‏ إِذْ تَقُولُ لِلَّذِي أَنْعَمَ اللَّهُ عَلَيْهِ ‏)‏ يَعْنِي بِالإِسْلاَمِ ‏:‏ ‏(‏ وأَنْعَمْتَ عَلَيْهِ ‏)‏ بِالْعِتْقِ فَأَعْتَقْتَهُ ‏:‏ ‏(‏ أمْسِكْ عَلَيْكَ زَوْجَكَ وَاتَّقِ اللَّهَ وَتُخْفِي فِي نَفْسِكَ مَا اللَّهُ مُبْدِيهِ وَتَخْشَى النَّاسَ وَاللَّهُ أَحَقُّ أَنْ تَخْشَاهُ ‏)‏ إِلَى قَوْلِهِ ‏:‏ ‏(‏وكَانَ أَمْرُ اللَّهِ مَفْعُولاً ‏)‏ وَإِنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم لَمَّا تَزَوَّجَهَا قَالُوا تَزَوَّجَ حَلِيلَةَ ابْنِهِ فَأَنْزَلَ اللَّهُ تَعَالَى ‏:‏ ‏(‏ ما كَانَ مُحَمَّدٌ أَبَا أَحَدٍ مِنْ رِجَالِكُمْ وَلَكِنْ رَسُولَ اللَّهِ وَخَاتَمَ النَّبِيِّينَ ‏)‏ وَكَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم تَبَنَّاهُ وَهُوَ صَغِيرٌ فَلَبِثَ حَتَّى صَارَ رَجُلاً يُقَالُ لَهُ زَيْدُ بْنُ مُحَمَّدٍ فَأَنْزَلَ اللَّهُ ‏:‏ ‏(‏ ادعُوهُمْ لآبَائِهِمْ هُوَ أَقْسَطُ عِنْدَ اللَّهِ فَإِنْ لَمْ تَعْلَمُوا آبَاءَهُمْ فَإِخْوَانُكُمْ فِي الدِّينِ وَمَوَالِيكُمْ ‏)‏ فُلاَنٌ مَوْلَى فُلاَنٍ وَفُلاَنٌ أَخُو فُلاَنٍ ‏(‏هُوَ أَقْسَطُ عِنْدَ اللَّهِ ‏)‏ يَعْنِي أَعْدَلُ عِنْدَ اللَّهِ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ غَرِيبٌ ‏.‏ قَدْ رُوِيَ عَنْ دَاوُدَ بْنِ أَبِي هِنْدٍ، عَنِ الشَّعْبِيِّ، عَنْ مَسْرُوقٍ، عَنْ عَائِشَةَ، قَالَتْ لَوْ كَانَ النَّبِيُّ صلى الله عليه وسلم كَاتِمًا شَيْئًا مِنَ الْوَحْىِ لَكَتَمَ هَذِهِ الآيَةَ ‏:‏ ‏(‏ إِذْ تَقُولُ لِلَّذِي أَنْعَمَ اللَّهُ عَلَيْهِ وَأَنْعَمْتَ عَلَيْهِ ‏)‏ الآيَةَ هَذَا الْحَرْفُ لَمْ يُرْوَ بِطُولِهِ ‏.‏ حَدَّثَنَا بِذَلِكَ عَبْدُ اللَّهِ بْنُ وَضَّاحٍ الْكُوفِيُّ حَدَّثَنَا عَبْدُ اللَّهِ بْنُ إِدْرِيسَ عَنْ دَاوُدَ بْنِ أَبِي هِنْدٍ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3209","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3209","x":"Narrated Ibn 'Umar:\n\n\"We called Zaid bin Harithah nothing but 'Zaid bin Muhammad' until the Qur'an was revealed (saying): 'Call them by their fathers, that is more just according to Allah (33:5).'\"","ar":"حَدَّثَنَا قُتَيْبَةُ، حَدَّثَنَا يَعْقُوبُ بْنُ عَبْدِ الرَّحْمَنِ، عَنْ مُوسَى بْنِ عُقْبَةَ، عَنْ سَالِمٍ، عَنِ ابْنِ عُمَرَ، قَالَ مَا كُنَّا نَدْعُو زَيْدَ بْنَ حَارِثَةَ إِلاَّ زَيْدَ بْنَ مُحَمَّدٍ حَتَّى نَزَلَ الْقُرْآنُ ‏:‏ ‏(‏ ادعُوهُمْ لآبَائِهِمْ هُوَ أَقْسَطُ عِنْدَ اللَّهِ ‏)‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 6, Book 46, Hadith 3814","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-6/Book-46/Hadith-3814","x":"Narrated Ibn 'Umar:\n\n\"We called Zaid bin Harithah nothing but 'Zaid bin Muhammad' until the Qur'an was revealed (ordering): Call them by their fathers, that is more just according to Allah. (33:5)\"","ar":"حَدَّثَنَا قُتَيْبَةُ، قَالَ حَدَّثَنَا يَعْقُوبُ بْنُ عَبْدِ الرَّحْمَنِ، عَنْ مُوسَى بْنِ عُقْبَةَ، عَنْ سَالِمِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ، عَنْ أَبِيهِ، قَالَ مَا كُنَّا نَدْعُو زَيْدَ بْنَ حَارِثَةَ إِلاَّ زَيْدَ بْنَ مُحَمَّدٍ حَتَّى نَزَلَتْ ‏:‏ ‏(‏ ادعُوهُمْ لِأَبَائِهِمْ هُوَ أَقْسَطُ عِنْدَ اللَّهِ ‏)‏ ‏.‏ هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏","v":[]}],"6":[{"c":"Sahih Bukhari","r":"Hadith 2399","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2399","x":"Narrated Abu Huraira:\n\nThe Prophet (ﷺ) said, \"I am closer to the believers than their selves in this world and in the Hereafter, and if you like, you can read Allah's Statement: \"The Prophet (ﷺ) is closer to the believers than their own selves.\" (33.6) So, if a true believer dies and leaves behind some property, it will be for his inheritors (from the father's side), and if he leaves behind some debt to be paid or needy offspring, then they should come to me as I am the guardian of the deceased.\"","ar":"حَدَّثَنَا عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ، حَدَّثَنَا أَبُو عَامِرٍ، حَدَّثَنَا فُلَيْحٌ، عَنْ هِلاَلِ بْنِ عَلِيٍّ، عَنْ عَبْدِ الرَّحْمَنِ بْنِ أَبِي عَمْرَةَ، عَنْ أَبِي هُرَيْرَةَ ـ رضى الله عنه ـ أَنَّ النَّبِيَّ صلى الله عليه وسلم قَالَ ‏\"‏ مَا مِنْ مُؤْمِنٍ إِلاَّ وَأَنَا أَوْلَى بِهِ فِي الدُّنْيَا وَالآخِرَةِ اقْرَءُوا إِنْ شِئْتُمْ ‏{‏النَّبِيُّ أَوْلَى بِالْمُؤْمِنِينَ مِنْ أَنْفُسِهِمْ‏}‏ فَأَيُّمَا مُؤْمِنٍ مَاتَ وَتَرَكَ مَالاً فَلْيَرِثْهُ عَصَبَتُهُ مَنْ كَانُوا، وَمَنْ تَرَكَ دَيْنًا أَوْ ضَيَاعًا فَلْيَأْتِنِي فَأَنَا مَوْلاَهُ ‏\"‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4781","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4781","x":"Narrated Abu Huraira:\n\nThe Prophet (ﷺ) said, \"There is no believer but I, of all the people, I am the closest to him both in this world and in the Hereafter. Recite if you wish: 'The Prophet (ﷺ) is closer to the believers than their own selves.' (33.6) so if a believer (dies) leaves some property then his relatives will inherit that property; but if he is in debt or he leaves poor children, let those (creditors and children) come to me (that I may pay the debt and provide for the children), for them I am his sponsor (surely).","ar":"حَدَّثَنِي إِبْرَاهِيمُ بْنُ الْمُنْذِرِ، حَدَّثَنَا مُحَمَّدُ بْنُ فُلَيْحٍ، حَدَّثَنَا أَبِي، عَنْ هِلاَلِ بْنِ عَلِيٍّ، عَنْ عَبْدِ الرَّحْمَنِ بْنِ أَبِي عَمْرَةَ، عَنْ أَبِي هُرَيْرَةَ ـ رضى الله عنه ـ عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏\"‏ مَا مِنْ مُؤْمِنٍ إِلاَّ وَأَنَا أَوْلَى النَّاسِ بِهِ فِي الدُّنْيَا وَالآخِرَةِ، اقْرَءُوا إِنْ شِئْتُمْ ‏{‏النَّبِيُّ أَوْلَى بِالْمُؤْمِنِينَ مِنْ أَنْفُسِهِمْ‏}‏ فَأَيُّمَا مُؤْمِنٍ تَرَكَ مَالاً فَلْيَرِثْهُ عَصَبَتُهُ مَنْ كَانُوا، فَإِنْ تَرَكَ دَيْنًا أَوْ ضِيَاعًا فَلْيَأْتِنِي وَأَنَا مَوْلاَهُ ‏\"‏‏.‏","v":[]}],"8":[{"c":"Sahih Muslim","r":"Hadith 2876a","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-2876a","x":"'A'isha reported that Allah's Messenger (ﷺ) said:\n\nHe who is taken to account on the Day of Resurrection is in fact put to torment. I said: Has Allah, the Exalted and Glorious, not said this: 'He will be made subject to an easy reckoning\" (Ixxxiv. 8)? Thereupon he said: (What it implies) is not the actual reckoning, but only the presentation of one's deeds to Him. He who is thoroughly examined in reckoning is put to torment.","ar":"حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، وَعَلِيُّ بْنُ حُجْرٍ، جَمِيعًا عَنْ إِسْمَاعِيلَ، قَالَ أَبُو بَكْرٍ حَدَّثَنَا ابْنُ عُلَيَّةَ، عَنْ أَيُّوبَ، عَنْ عَبْدِ اللَّهِ بْنِ أَبِي مُلَيْكَةَ، عَنْ عَائِشَةَ، قَالَتْ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ مَنْ حُوسِبَ يَوْمَ الْقِيَامَةِ عُذِّبَ ‏\"‏ ‏.‏ فَقُلْتُ أَلَيْسَ قَدْ قَالَ اللَّهُ عَزَّ وَجَلَّ ‏{‏ فَسَوْفَ يُحَاسَبُ حِسَابًا يَسِيرًا‏}‏ فَقَالَ ‏\"‏ لَيْسَ ذَاكِ الْحِسَابُ إِنَّمَا ذَاكِ الْعَرْضُ مَنْ نُوقِشَ الْحِسَابَ يَوْمَ الْقِيَامَةِ عُذِّبَ ‏\"‏ ‏.‏","v":[]}],"10":[{"c":"Sahih Bukhari","r":"Hadith 4103","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4103","x":"Narrated `Aisha:\n\nAs regards the following Qur'anic Verse:-- \"When they came on you from above and from below you (from east and west of the valley) and when the eyes grew wild and the hearts reached up to the throats.....\" (33.10) That happened on the day of Al-Khandaq (i.e. Trench).","ar":"حَدَّثَنِي عُثْمَانُ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا عَبْدَةُ، عَنْ هِشَامٍ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ، رضى الله عنها ‏{‏إِذْ جَاءُوكُمْ مِنْ فَوْقِكُمْ وَمِنْ أَسْفَلَ مِنْكُمْ وَإِذْ زَاغَتِ الأَبْصَارُ‏}‏ قَالَتْ كَانَ ذَاكَ يَوْمَ الْخَنْدَقِ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 3020","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-3020","x":"'A'isha reported that these words of Allah:\n\n\" When they came upon you from above you and from below you and when the eyes turned dull and the hearts rose up to the throats\" (xxxiii. 10) pertain to the day of Ditch.","ar":"حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا عَبْدَةُ بْنُ سُلَيْمَانَ، عَنْ هِشَامٍ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ، فِي قَوْلِهِ عَزَّ وَجَلَّ ‏{‏ إِذْ جَاءُوكُمْ مِنْ فَوْقِكُمْ وَمِنْ أَسْفَلَ مِنْكُمْ وَإِذْ زَاغَتِ الأَبْصَارُ وَبَلَغَتِ الْقُلُوبُ الْحَنَاجِرَ‏}‏ قَالَتْ كَانَ ذَلِكَ يَوْمَ الْخَنْدَقِ ‏.‏","v":[]}],"21":[{"c":"Sahih Bukhari","r":"Hadith 774","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-774","x":"Narrated Ibn `Abbas:\n\nThe Prophet (ﷺ) recited aloud in the prayers in which he was ordered to do so and quietly in the prayers in which he was ordered to do so. \"And your Lord is not forgetful.\" \"Verily there was a good example for you in the ways of the Prophet.\"","ar":"حَدَّثَنَا مُسَدَّدٌ، قَالَ حَدَّثَنَا إِسْمَاعِيلُ، قَالَ حَدَّثَنَا أَيُّوبُ، عَنْ عِكْرِمَةَ، عَنِ ابْنِ عَبَّاسٍ، قَالَ قَرَأَ النَّبِيُّ صلى الله عليه وسلم فِيمَا أُمِرَ، وَسَكَتَ فِيمَا أُمِرَ ‏{‏وَمَا كَانَ رَبُّكَ نَسِيًّا‏}‏ ‏{‏لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ‏}‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 1101","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-1101","x":"Narrated Hafs bin `Asim:\n\nIbn `Umar went on a journey and said, \"I accompanied the Prophet (ﷺ) and he did not offer optional prayers during the journey, and Allah says: 'Verily! In Allah's Messenger (ﷺ) you have a good example to follow.' \" (33.21)","ar":"حَدَّثَنَا يَحْيَى بْنُ سُلَيْمَانَ، قَالَ حَدَّثَنِي ابْنُ وَهْبٍ، قَالَ حَدَّثَنِي عُمَرُ بْنُ مُحَمَّدٍ، أَنَّ حَفْصَ بْنَ عَاصِمٍ، حَدَّثَهُ قَالَ سَافَرَ ابْنُ عُمَرَ ـ رضى الله عنهما ـ فَقَالَ صَحِبْتُ النَّبِيَّ صلى الله عليه وسلم فَلَمْ أَرَهُ يُسَبِّحُ فِي السَّفَرِ، وَقَالَ اللَّهُ جَلَّ ذِكْرُهُ ‏{‏لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ‏}‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2235","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2235","x":"Narrated Anas bin Malik:\n\nThe Prophet (ﷺ) came to Khaibar and when Allah made him victorious and he conquered the town by breaking the enemy's defense, the beauty of Safiya bint Huyai bin Akhtab was mentioned to him and her husband had been killed while she was a bride. Allah's Messenger (ﷺ) selected her for himself and he set out in her company till he reached Sadd-ar-Rawha' where her menses were over and he married her. Then Hais (a kind of meal) was prepared and served on a small leather sheet (used for serving meals). Allah's Messenger (ﷺ) then said to me, \"Inform those who are around you (about the wedding banquet).\" So that was the marriage banquet given by Allah's Messenger (ﷺ) for (his marriage with) Safiya. After that we proceeded to Medina and I saw that Allah's Messenger (ﷺ) was covering her with a cloak while she was behind him. Then he would sit beside his camel and let Safiya put her feet on his knees to ride (the camel).","ar":"حَدَّثَنَا عَبْدُ الْغَفَّارِ بْنُ دَاوُدَ، حَدَّثَنَا يَعْقُوبُ بْنُ عَبْدِ الرَّحْمَنِ، عَنْ عَمْرِو بْنِ أَبِي عَمْرٍو، عَنْ أَنَسِ بْنِ مَالِكٍ ـ رضى الله عنه ـ قَالَ قَدِمَ النَّبِيُّ صلى الله عليه وسلم خَيْبَرَ، فَلَمَّا فَتَحَ اللَّهُ عَلَيْهِ الْحِصْنَ ذُكِرَ لَهُ جَمَالُ صَفِيَّةَ بِنْتِ حُيَىِّ بْنِ أَخْطَبَ، وَقَدْ قُتِلَ زَوْجُهَا، وَكَانَتْ عَرُوسًا، فَاصْطَفَاهَا رَسُولُ اللَّهِ صلى الله عليه وسلم لِنَفْسِهِ فَخَرَجَ بِهَا، حَتَّى بَلَغْنَا سَدَّ الرَّوْحَاءِ حَلَّتْ، فَبَنَى بِهَا، ثُمَّ صَنَعَ حَيْسًا فِي نِطَعٍ صَغِيرٍ، ثُمَّ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\n\n\"‏ آذِنْ مَنْ حَوْلَكَ ‏\"\n\n‏‏.‏ فَكَانَتْ تِلْكَ وَلِيمَةَ رَسُولِ اللَّهِ صلى الله عليه وسلم عَلَى صَفِيَّةَ، ثُمَّ خَرَجْنَا إِلَى الْمَدِينَةِ، قَالَ فَرَأَيْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم يُحَوِّي لَهَا وَرَاءَهُ بِعَبَاءَةٍ، ثُمَّ يَجْلِسُ عِنْدَ بَعِيرِهِ فَيَضَعُ رُكْبَتَهُ، فَتَضَعُ صَفِيَّةُ رِجْلَهَا عَلَى رُكْبَتِهِ، حَتَّى تَرْكَبَ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4184","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4184","x":"Narrated Nafi`:\n\nIbn `Umar assumed Ihram and said, \"If something should intervene between me and the Ka`ba, then I will do what the Prophet (ﷺ) did when the Quraish infidels intervened between him and (the Ka`ba). Then Ibn `Umar recited: \"You have indeed in Allah's Messenger (ﷺ) A good example to follow.\" (33.21)","ar":"حَدَّثَنَا مُسَدَّدٌ، حَدَّثَنَا يَحْيَى، عَنْ عُبَيْدِ اللَّهِ، عَنْ نَافِعٍ، عَنِ ابْنِ عُمَرَ، أَنَّهُ أَهَلَّ وَقَالَ إِنْ حِيلَ بَيْنِي وَبَيْنَهُ لَفَعَلْتُ كَمَا فَعَلَ النَّبِيُّ صلى الله عليه وسلم حِينَ حَالَتْ كُفَّارُ قُرَيْشٍ بَيْنَهُ‏.‏ وَتَلاَ ‏{‏لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ‏}‏","v":[]},{"c":"Sunan Ibn Majah","r":"Volume 2, Book 5, Hadith 1071","u":"https://quranx.com/Hadith/IbnMajah/DarusSalam/Volume-2/Book-5/Hadith-1071","x":"It was narrated from ‘Isa bin Hafs bin ‘Asim bin ‘Umar bin Khattab that his father told him:\n\n\"We were with Ibn ‘Umar on a journey, and he led us in prayer. Then we finished with him and he finished turning around, and saw some people praying. He said: ‘What are these people doing?’ I said: ‘Glorifying Allah.’* He said: ‘If I wanted to glorify Allah (perform voluntary prayer) I would have completed my prayer. O son of my brother! I accompanied the Messenger of Allah (ﷺ) and he never prayed more than two Rak’ah when he was traveling, until Allah took his soul. Then I accompanied Abu Bakr and he never prayed more than two Rak’ah (when he was traveling), until Allah took his soul. Then I accompanied ‘Umar and he never prayed more than two Rak’ah, until Allah took his soul. Then I accompanied ‘Uthman and he never prayed more than two Rak’ah, until Allah took his soul. Allah says: ‘Indeed in the Messenger of Allah (Muhammad (ﷺ)) you have a good example to follow.’\" [33:21] * Meaning, they were offering voluntary prayer.","ar":"حَدَّثَنَا أَبُو بَكْرِ بْنُ خَلاَّدٍ الْبَاهِلِيُّ، حَدَّثَنَا أَبُو عَامِرٍ، عَنْ عِيسَى بْنِ حَفْصِ بْنِ عَاصِمِ بْنِ عُمَرَ بْنِ الْخَطَّابِ، حَدَّثَنِي أَبِي قَالَ، كَنَّا مَعَ ابْنِ عُمَرَ فِي سَفَرٍ فَصَلَّى بِنَا ثُمَّ انْصَرَفْنَا مَعَهُ وَانْصَرَفَ ‏.‏ قَالَ فَالْتَفَتَ فَرَأَى أُنَاسًا يُصَلُّونَ فَقَالَ مَا يَصْنَعُ هَؤُلاَءِ قُلْتُ يُسَبِّحُونَ ‏.‏ قَالَ لَوْ كُنْتُ مُسَبِّحًا لأَتْمَمْتُ صَلاَتِي يَا ابْنَ أَخِي إِنِّي صَحِبْتُ رَسُولَ اللَّهِ ـ صلى الله عليه وسلم ـ فَلَمْ يَزِدْ عَلَى رَكْعَتَيْنِ فِي السَّفَرِ حَتَّى قَبَضَهُ اللَّهُ ثُمَّ صَحِبْتُ أَبَا بَكْرٍ فَلَمْ يَزِدْ عَلَى رَكْعَتَيْنِ ثُمَّ صَحِبْتُ عُمَرَ فَلَمْ يَزِدْ عَلَى رَكْعَتَيْنِ ثُمَّ صَحِبْتُ عُثْمَانَ فَلَمْ يَزِدْ عَلَى رَكْعَتَيْنِ حَتَّى قَبَضَهُمُ اللَّهُ وَاللَّهُ يَقُولُ ‏{لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ ‏}‏ ‏.‏","v":[]},{"c":"Sunan Ibn Majah","r":"Volume 3, Book 10, Hadith 2073","u":"https://quranx.com/Hadith/IbnMajah/DarusSalam/Volume-3/Book-10/Hadith-2073","x":"It was narrated from Sa'eed bin Jubair that Ibn 'Abbas said:\n\n\"For the one who makes unlawful is the swearing.\" (Sahih)And Ibn 'Abbas used to say: \"You had the best example in the Messenger of Allah.\" (33:21)","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ يَحْيَى، حَدَّثَنَا وَهْبُ بْنُ جَرِيرٍ، حَدَّثَنَا هِشَامٌ الدَّسْتَوَائِيُّ، عَنْ يَحْيَى بْنِ أَبِي كَثِيرٍ، عَنْ يَعْلَى بْنِ حَكِيمٍ، عَنْ سَعِيدِ بْنِ جُبَيْرٍ، قَالَ قَالَ ابْنُ عَبَّاسٍ فِي الْحَرَامِ يَمِينٌ ‏.‏ وَكَانَ ابْنُ عَبَّاسٍ يَقُولُ لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 689a","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-689a","x":"Hafs b. 'Asim said:\n\nI accompanied Ibn 'Umar on the road to Mecca and he led us in two rak'ahs at the noon prayer, then he went forward and we too went along with him to a place where he alighted, and he sat and we sat along with him, and he cast a glance to the side where he said prayer and he saw people standing and asked: What are they doing? I said: They are engaged in glorifying Allah, offering Sunnah prayer. He said: If I had done so I would have perfected my prayer; O my nephew! I accompanied the Messenger of Allah (ﷺ) on a journey, and he made no addittion to two rak'ahs, till Allah called him. I accompanied Abu Bakr and he made no addition to two rak'ahs till Allah caused him to die. I accompanied 'Umar and he made no addition to two rak'ahs till Allah caused him to die. I accompanied 'Uthman and he made no addition to two rak'ahs, till Allah caused him to die, and Allah has said:\" There is a model pattern for you in the Messenger of Allah\" (al-Qur'an, xxxiii. 21).","ar":"وَحَدَّثَنَا عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ بْنِ قَعْنَبٍ، حَدَّثَنَا عِيسَى بْنُ حَفْصِ بْنِ عَاصِمِ بْنِ عُمَرَ بْنِ الْخَطَّابِ، عَنْ أَبِيهِ، قَالَ صَحِبْتُ ابْنَ عُمَرَ فِي طَرِيقِ مَكَّةَ - قَالَ - فَصَلَّى لَنَا الظُّهْرَ رَكْعَتَيْنِ ثُمَّ أَقْبَلَ وَأَقْبَلْنَا مَعَهُ حَتَّى جَاءَ رَحْلَهُ وَجَلَسَ وَجَلَسْنَا مَعَهُ فَحَانَتْ مِنْهُ الْتِفَاتَةٌ نَحْوَ حَيْثُ صَلَّى فَرَأَى نَاسًا قِيَامًا فَقَالَ مَا يَصْنَعُ هَؤُلاَءِ قُلْتُ يُسَبِّحُونَ ‏.‏ قَالَ لَوْ كُنْتُ مُسَبِّحًا لأَتْمَمْتُ صَلاَتِي يَا ابْنَ أَخِي إِنِّي صَحِبْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم فِي السَّفَرِ فَلَمْ يَزِدْ عَلَى رَكْعَتَيْنِ حَتَّى قَبَضَهُ اللَّهُ وَصَحِبْتُ أَبَا بَكْرٍ فَلَمْ يَزِدْ عَلَى رَكْعَتَيْنِ حَتَّى قَبَضَهُ اللَّهُ وَصَحِبْتُ عُمَرَ فَلَمْ يَزِدْ عَلَى رَكْعَتَيْنِ حَتَّى قَبَضَهُ اللَّهُ ثُمَّ صَحِبْتُ عُثْمَانَ فَلَمْ يَزِدْ عَلَى رَكْعَتَيْنِ حَتَّى قَبَضَهُ اللَّهُ وَقَدْ قَالَ اللَّهُ ‏{‏ لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ‏}‏ ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 1230b","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-1230b","x":"Nafi' reported that 'Abdullah b. 'Abdullah and Salim b. Abdullah said to 'Abdullah (b. 'Umar) at the time when Hajjaj came to fight against Ibn Zubair:\n\nThere would be no harm if you do not (proceed) for Hajj this year, for we fear that there would be fight among people which would cause obstruction between you and the House, whereupon he said: If there would be obstruction between me and that (Ka'ba), I would do as Allah's Messenger (ﷺ) did. I was with him (the Holy Prophet) when the infidels of Quraish caused obstructions between him (the Holy Prophet) and the House. I call you as my witness (to the fact) that I have made 'Umra essential for me. He proceeded until he came to Dhu'l-Hulaifa and pronounced Talbiya for Umra, and said: If the way Is clear forme, I would then complete my 'Umra but If there is some obstruction between me and that (the Ka'ba). I would then do what Allah's Messenger (ﷺ) had done (at the occasion of Hudaibiya), and I was with him (the Holy Prophet). and then recited:\" Verily in the Messenger of Allah, there is a model pattern for you\" (xxxiii. 21). He then moved on until he came to the rear side of al-Baida' and said: There is one command for both of them automatically) (Hajj and Umra). If I am detained (in the performance) of 'Umra, I am ( automatically detained (in the performance) of Hajj (too). I call you as witness that Hajj along with 'Umra I had made essential for me. (I am performing Hajj and 'Umra as Qiran.) He then bought sacrificial animals at Qudaid and then circumambulated the House and ran between al-Safa' and al-Marwa once (covering both Hajj and Umra), and did not put off Ihram until on the Day of Sacrifice in the month of Dhu'l-Hijja.","ar":"وَحَدَّثَنَا مُحَمَّدُ بْنُ الْمُثَنَّى، حَدَّثَنَا يَحْيَى، - وَهُوَ الْقَطَّانُ - عَنْ عُبَيْدِ اللَّهِ، حَدَّثَنِي نَافِعٌ، أَنَّ عَبْدَ اللَّهِ بْنَ عَبْدِ اللَّهِ، وَسَالِمَ بْنَ عَبْدِ اللَّهِ، كَلَّمَا عَبْدَ اللَّهِ حِينَ نَزَلَ الْحَجَّاجُ لِقِتَالِ ابْنِ الزُّبَيْرِ قَالاَ لاَ يَضُرُّكَ أَنْ لاَ تَحُجَّ الْعَامَ فَإِنَّا نَخْشَى أَنْ يَكُونَ بَيْنَ النَّاسِ قِتَالٌ يُحَالُ بَيْنَكَ وَبَيْنَ الْبَيْتِ قَالَ فَإِنْ حِيلَ بَيْنِي وَبَيْنَهُ فَعَلْتُ كَمَا فَعَلَ رَسُولُ اللَّهِ صلى الله عليه وسلم وَأَنَا مَعَهُ حِينَ حَالَتْ كُفَّارُ قُرَيْشٍ بَيْنَهُ وَبَيْنَ الْبَيْتِ أُشْهِدُكُمْ أَنِّي قَدْ أَوْجَبْتُ عُمْرَةً ‏.‏ فَانْطَلَقَ حَتَّى أَتَى ذَا الْحُلَيْفَةِ فَلَبَّى بِالْعُمْرَةِ ثُمَّ قَالَ إِنْ خُلِّيَ سَبِيلِي قَضَيْتُ عُمْرَتِي وَإِنْ حِيلَ بَيْنِي وَبَيْنَهُ فَعَلْتُ كَمَا فَعَلَ رَسُولُ اللَّهِ صلى الله عليه وسلم وَأَنَا مَعَهُ ‏.‏ ثُمَّ تَلاَ ‏{‏ لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ‏}‏ ثُمَّ سَارَ حَتَّى إِذَا كَانَ بِظَهْرِ الْبَيْدَاءِ قَالَ مَا أَمْرُهُمَا إِلاَّ وَاحِدٌ إِنْ حِيلَ بَيْنِي وَبَيْنَ الْعُمْرَةِ حِيلَ بَيْنِي وَبَيْنَ الْحَجِّ أُشْهِدُكُمْ أَنِّي قَدْ أَوْجَبْتُ حَجَّةً مَعَ عُمْرَةٍ ‏.‏ فَانْطَلَقَ حَتَّى ابْتَاعَ بِقُدَيْدٍ هَدْيًا ثُمَّ طَافَ لَهُمَا طَوَافًا وَاحِدًا بِالْبَيْتِ وَبَيْنَ الصَّفَا وَالْمَرْوَةِ ثُمَّ لَمْ يَحِلَّ مِنْهُمَا حَتَّى حَلَّ مِنْهُمَا بِحَجَّةٍ يَوْمَ النَّحْرِ ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 1234a","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-1234a","x":"Amr b. Dinar said:\n\nWe asked Ibn Umar about a person who came for Umra and circumambulated the House, but he did not run between al-Safa' and al-Marwa, whether he is allowed to (put off Ihram) and have intercourse with his wife. He replied: Allah's Messenger (ﷺ) circumambulated the House seven times and offered two rak'ahs of prayer after staying (at 'Arafat), and ran between al-Safa and al-Marwa seven times.\" Verily there is in Allah's Messenger a model pattern for you\" (xxxill. 21).","ar":"حَدَّثَنِي زُهَيْرُ بْنُ حَرْبٍ، حَدَّثَنَا سُفْيَانُ بْنُ عُيَيْنَةَ، عَنْ عَمْرِو بْنِ دِينَارٍ، قَالَ سَأَلْنَا ابْنَ عُمَرَ عَنْ رَجُلٍ، قَدِمَ بِعُمْرَةٍ فَطَافَ بِالْبَيْتِ وَلَمْ يَطُفْ بَيْنَ الصَّفَا وَالْمَرْوَةِ أَيَأْتِي امْرَأَتَهُ فَقَالَ قَدِمَ رَسُولُ اللَّهِ صلى الله عليه وسلم فَطَافَ بِالْبَيْتِ سَبْعًا وَصَلَّى خَلْفَ الْمَقَامِ رَكْعَتَيْنِ وَبَيْنَ الصَّفَا وَالْمَرْوَةِ سَبْعًا وَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ ‏.‏","v":[]}],"23":[{"c":"Sahih Bukhari","r":"Hadith 2805","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2805","x":"Narrated Anas:\n\nMy uncle Anas bin An-Nadr was absent from the Battle of Badr. He said, \"O Allah's Messenger (ﷺ)! I was absent from the first battle you fought against the pagans. (By Allah) if Allah gives me a chance to fight the pagans, no doubt. Allah will see how (bravely) I will fight.\" On the day of Uhud when the Muslims turned their backs and fled, he said, \"O Allah! I apologize to You for what these (i.e. his companions) have done, and I denounce what these (i.e. the pagans) have done.\" Then he advanced and Sa`d bin Mu`adh met him. He said \"O Sa`d bin Mu`adh ! By the Lord of An-Nadr, Paradise! I am smelling its aroma coming from before (the mountain of) Uhud,\" Later on Sa`d said, \"O Allah's Apostle! I cannot achieve or do what he (i.e. Anas bin An-Nadr) did. We found more than eighty wounds by swords and arrows on his body. We found him dead and his body was mutilated so badly that none except his sister could recognize him by his fingers.\" We used to think that the following Verse was revealed concerning him and other men of his sort: \"Among the believers are men who have been true to their covenant with Allah..........\" (33.23) His sister Ar-Rubbaya' broke a front tooth of a woman and Allah's Messenger (ﷺ) ordered for retaliation. On that Anas (bin An-Nadr) said, \"O Allah's Messenger (ﷺ)! By Him Who has sent you with the Truth, my sister's tooth shall not be broken.\" Then the opponents of Anas's sister accepted the compensation and gave up the claim of retaliation. So Allah's Messenger (ﷺ) said, \"There are some people amongst Allah's slaves whose oaths are fulfilled by Allah when they take them.\"","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ سَعِيدٍ الْخُزَاعِيُّ، حَدَّثَنَا عَبْدُ الأَعْلَى، عَنْ حُمَيْدٍ، قَالَ سَأَلْتُ أَنَسًا‏.‏ حَدَّثَنَا عَمْرُو بْنُ زُرَارَةَ، حَدَّثَنَا زِيَادٌ، قَالَ حَدَّثَنِي حُمَيْدٌ الطَّوِيلُ، عَنْ أَنَسٍ ـ رضى الله عنه ـ قَالَ غَابَ عَمِّي أَنَسُ بْنُ النَّضْرِ عَنْ قِتَالِ بَدْرٍ فَقَالَ يَا رَسُولَ اللَّهِ، غِبْتُ عَنْ أَوَّلِ قِتَالٍ قَاتَلْتَ الْمُشْرِكِينَ، لَئِنِ اللَّهُ أَشْهَدَنِي قِتَالَ الْمُشْرِكِينَ لَيَرَيَنَّ اللَّهُ مَا أَصْنَعُ، فَلَمَّا كَانَ يَوْمُ أُحُدٍ وَانْكَشَفَ الْمُسْلِمُونَ قَالَ ‏\"‏ اللَّهُمَّ إِنِّي أَعْتَذِرُ إِلَيْكَ مِمَّا صَنَعَ هَؤُلاَءِ ـ يَعْنِي أَصْحَابَهُ ـ وَأَبْرَأُ إِلَيْكَ مِمَّا صَنَعَ هَؤُلاَءِ ‏\"‏ ـ يَعْنِي الْمُشْرِكِينَ ـ ثُمَّ تَقَدَّمَ، فَاسْتَقْبَلَهُ سَعْدُ بْنُ مُعَاذٍ، فَقَالَ يَا سَعْدُ بْنَ مُعَاذٍ، الْجَنَّةَ، وَرَبِّ النَّضْرِ إِنِّي أَجِدُ رِيحَهَا مِنْ دُونِ أُحُدٍ‏.‏ قَالَ سَعْدٌ فَمَا اسْتَطَعْتُ يَا رَسُولَ اللَّهِ مَا صَنَعَ‏.‏ قَالَ أَنَسٌ فَوَجَدْنَا بِهِ بِضْعًا وَثَمَانِينَ ضَرْبَةً بِالسَّيْفِ أَوْ طَعْنَةً بِرُمْحٍ أَوْ رَمْيَةً بِسَهْمٍ، وَوَجَدْنَاهُ قَدْ قُتِلَ وَقَدْ مَثَّلَ بِهِ الْمُشْرِكُونَ، فَمَا عَرَفَهُ أَحَدٌ إِلاَّ أُخْتُهُ بِبَنَانِهِ‏.‏ قَالَ أَنَسٌ كُنَّا نَرَى أَوْ نَظُنُّ أَنَّ هَذِهِ الآيَةَ نَزَلَتْ فِيهِ وَفِي أَشْبَاهِهِ ‏{‏مِنَ الْمُؤْمِنِينَ رِجَالٌ صَدَقُوا مَا عَاهَدُوا اللَّهَ عَلَيْهِ‏}‏ إِلَى آخِرِ الآيَةِ‏.‏ وَقَالَ إِنَّ أُخْتَهُ وَهْىَ تُسَمَّى الرُّبَيِّعَ كَسَرَتْ ثَنِيَّةَ امْرَأَةٍ فَأَمَرَ رَسُولُ اللَّهِ صلى الله عليه وسلم بِالْقِصَاصِ، فَقَالَ أَنَسٌ يَا رَسُولَ اللَّهِ، وَالَّذِي بَعَثَكَ بِالْحَقِّ لاَ تُكْسَرُ ثَنِيَّتُهَا‏.‏ فَرَضُوا بِالأَرْشِ وَتَرَكُوا الْقِصَاصَ، فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ إِنَّ مِنْ عِبَادِ اللَّهِ مَنْ لَوْ أَقْسَمَ عَلَى اللَّهِ لأَبَرَّهُ ‏\"‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2807","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2807","x":"Narrated Kharija bin Zaid:\n\nZaid bin Thabit said, \"When the Qur'an was compiled from various written manuscripts, one of the Verses of Surat Al-Ahzab was missing which I used to hear Allah's Messenger (ﷺ) reciting. I could not find it except with Khuza`ima bin Thabjt Al-Ansari, whose witness Allah's Messenger (ﷺ) regarded as equal to the witness of two men. And the Verse was:-- \"Among the believers are men who have been true to what they covenanted with Allah.\" (33.23)","ar":"حَدَّثَنَا أَبُو الْيَمَانِ، أَخْبَرَنَا شُعَيْبٌ، عَنِ الزُّهْرِيِّ، حَدَّثَنِي إِسْمَاعِيلُ، قَالَ حَدَّثَنِي أَخِي، عَنْ سُلَيْمَانَ، أُرَاهُ عَنْ مُحَمَّدِ بْنِ أَبِي عَتِيقٍ، عَنِ ابْنِ شِهَابٍ، عَنْ خَارِجَةَ بْنِ زَيْدٍ، أَنَّ زَيْدَ بْنَ ثَابِتٍ ـ رضى الله عنه ـ قَالَ نَسَخْتُ الصُّحُفَ فِي الْمَصَاحِفِ، فَفَقَدْتُ آيَةً مِنْ سُورَةِ الأَحْزَابِ، كُنْتُ أَسْمَعُ رَسُولَ اللَّهِ صلى الله عليه وسلم يَقْرَأُ بِهَا، فَلَمْ أَجِدْهَا إِلاَّ مَعَ خُزَيْمَةَ بْنِ ثَابِتٍ الأَنْصَارِيِّ الَّذِي جَعَلَ رَسُولُ اللَّهِ صلى الله عليه وسلم شَهَادَتَهُ شَهَادَةَ رَجُلَيْنِ، وَهْوَ قَوْلُهُ ‏{‏مِنَ الْمُؤْمِنِينَ رِجَالٌ صَدَقُوا مَا عَاهَدُوا اللَّهَ عَلَيْهِ‏}‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4049","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4049","x":"Narrated Zaid bin Thabit:\n\nWhen we wrote the Holy Qur'an, I missed one of the Verses of Surat-al-Ahzab which I used to hear Allah's Messenger (ﷺ) reciting. Then we searched for it and found it with Khuza`ima bin Thabit Al-Ansari. The Verse was:-- 'Among the Believers are men Who have been true to Their Covenant with Allah, Of them, some have fulfilled Their obligations to Allah (i.e. they have been Killed in Allah's Cause), And some of them are (still) waiting\" (33.23) So we wrote this in its place in the Qur'an.","ar":"حَدَّثَنَا مُوسَى بْنُ إِسْمَاعِيلَ، حَدَّثَنَا إِبْرَاهِيمُ بْنُ سَعْدٍ، حَدَّثَنَا ابْنُ شِهَابٍ، أَخْبَرَنِي خَارِجَةُ بْنُ زَيْدِ بْنِ ثَابِتٍ، أَنَّهُ سَمِعَ زَيْدَ بْنَ ثَابِتٍ ـ رضى الله عنه ـ يَقُولُ فَقَدْتُ آيَةً مِنَ الأَحْزَابِ حِينَ نَسَخْنَا الْمُصْحَفَ، كُنْتُ أَسْمَعُ رَسُولَ اللَّهِ صلى الله عليه وسلم يَقْرَأُ بِهَا، فَالْتَمَسْنَاهَا فَوَجَدْنَاهَا مَعَ خُزَيْمَةَ بْنِ ثَابِتٍ الأَنْصَارِيِّ ‏{‏مِنَ الْمُؤْمِنِينَ رِجَالٌ صَدَقُوا مَا عَاهَدُوا اللَّهَ عَلَيْهِ فَمِنْهُمْ مَنْ قَضَى نَحْبَهُ وَمِنْهُمْ مَنْ يَنْتَظِرُ ‏}‏ فَأَلْحَقْنَاهَا فِي سُورَتِهَا فِي الْمُصْحَفِ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4988","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4988","x":"Zaid bin Thabit added, \"A verse from Surat Ahzab was missed by me when we copied the Qur'an and I used to hear Allah's Messenger (ﷺ) reciting it. So we searched for it and found it with Khuza`ima bin Thabit Al-Ansari. (That Verse was):\n\n'Among the Believers are men who have been true in their covenant with Allah.' (33.23)","ar":"قَالَ ابْنُ شِهَابٍ وَأَخْبَرَنِي خَارِجَةُ بْنُ زَيْدِ بْنِ ثَابِتٍ، سَمِعَ زَيْدَ بْنَ ثَابِتٍ، قَالَ فَقَدْتُ آيَةً مِنَ الأَحْزَابِ حِينَ نَسَخْنَا الْمُصْحَفَ قَدْ كُنْتُ أَسْمَعُ رَسُولَ اللَّهِ صلى الله عليه وسلم يَقْرَأُ بِهَا فَالْتَمَسْنَاهَا فَوَجَدْنَاهَا مَعَ خُزَيْمَةَ بْنِ ثَابِتٍ الأَنْصَارِيِّ ‏{‏مِنَ الْمُؤْمِنِينَ رِجَالٌ صَدَقُوا مَا عَاهَدُوا اللَّهَ عَلَيْهِ‏}‏ فَأَلْحَقْنَاهَا فِي سُورَتِهَا فِي الْمُصْحَفِ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 1903","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-1903","x":"It has been Deported on the authority of Anas who said:\n\nMy uncle and I have been named after him was not present with the Messenger of Allah (mav peace be upon him) on the Day of Badr. He felt distressed about it. He would say: I have missed the first battle fought by the Messenger of Allah (ﷺ), and if God now gives me an opportunity to see a battlefield with the Messenger of Allah (ﷺ), God will see what I do therein. He was afraid to say more than this (lest he be unable to keep his word with God). He was present with the Messenger of Allah (ﷺ) on the Day of Uhud. He met Sa'd b. Mu'adh (who was retreating). Anas said to him: O Abu 'Amr, where (are you going)? Woe (to thee)! I find the smell of Paradise beside the Uhud mountain. (Reprimanding Sa'd in these words) he went forward and fought thein (the enemy) until he was killed. (The narrator says). More than eighty wounds inflicted with swords, spears and arrows were found on his body. His sister, my aunt, ar-Rubayyi', daughter of Nadr, said: I could not recognise my brother's body (it was so badly mutilated) except from his finger-tips. (It was on this occasion that) the Qur'anic verse:\" Among the Believers are men who have been true to their covenant with God. Of them some have completed their vow (to the extreme), and some still wait: but they have never changed (their determination) in the least\" (xxxiii. 23). The narrator said that the verse had been revealed about him (Anas b. Nadr) and his Companions.","ar":"وَحَدَّثَنِي مُحَمَّدُ بْنُ حَاتِمٍ، حَدَّثَنَا بَهْزٌ، حَدَّثَنَا سُلَيْمَانُ بْنُ الْمُغِيرَةِ، عَنْ ثَابِتٍ، قَالَ قَالَ أَنَسٌ عَمِّيَ الَّذِي سُمِّيتُ بِهِ لَمْ يَشْهَدْ مَعَ رَسُولِ اللَّهِ صلى الله عليه وسلم بَدْرًا - قَالَ - فَشَقَّ عَلَيْهِ قَالَ أَوَّلُ مَشْهَدٍ شَهِدَهُ رَسُولُ اللَّهِ صلى الله عليه وسلم غُيِّبْتُ عَنْهُ وَإِنْ أَرَانِيَ اللَّهُ مَشْهَدًا فِيمَا بَعْدُ مَعَ رَسُولِ اللَّهِ صلى الله عليه وسلم لَيَرَانِيَ اللَّهُ مَا أَصْنَعُ - قَالَ - فَهَابَ أَنْ يَقُولَ غَيْرَهَا - قَالَ - فَشَهِدَ مَعَ رَسُولِ اللَّهِ صلى الله عليه وسلم يَوْمَ أُحُدٍ - قَالَ - فَاسْتَقْبَلَ سَعْدُ بْنُ مُعَاذٍ فَقَالَ لَهُ أَنَسٌ يَا أَبَا عَمْرٍو أَيْنَ فَقَالَ وَاهًا لِرِيحِ الْجَنَّةِ أَجِدُهُ دُونَ أُحُدٍ - قَالَ - فَقَاتَلَهُمْ حَتَّى قُتِلَ - قَالَ - فَوُجِدَ فِي جَسَدِهِ بِضْعٌ وَثَمَانُونَ مِنْ بَيْنِ ضَرْبَةٍ وَطَعْنَةٍ وَرَمْيَةٍ - قَالَ - فَقَالَتْ أُخْتُهُ عَمَّتِيَ الرُّبَيِّعُ بِنْتُ النَّضْرِ فَمَا عَرَفْتُ أَخِي إِلاَّ بِبَنَانِهِ ‏.‏ وَنَزَلَتْ هَذِهِ الآيَةُ ‏{‏ رِجَالٌ صَدَقُوا مَا عَاهَدُوا اللَّهَ عَلَيْهِ فَمِنْهُمْ مَنْ قَضَى نَحْبَهُ وَمِنْهُمْ مَنْ يَنْتَظِرُ وَمَا بَدَّلُوا تَبْدِيلاً‏}‏ قَالَ فَكَانُوا يُرَوْنَ أَنَّهَا نَزَلَتْ فِيهِ وَفِي أَصْحَابِهِ ‏.‏","v":[]},{"c":"Riyad as-Salihin","r":"Hadith 109","u":"https://quranx.com/Hadith/Saliheen/Reference/Hadith-109","x":"Anas (May Allah be pleased with him) said:\n\nMy uncle Anas bin An-Nadr (May Allah be pleased with him) was absent from the battle of Badr and he said: \"O Messenger of Allah! I was absent from the first battle you fought against the pagans, and if Allah let me participate in a battle against the pagans, Allah will see what I do.\" So he encountered the day of Uhud Battle. The Muslims left the positions (the Prophet (ﷺ) told them to keep) and were defeated, he said: \"O Allah! excuse these people (i.e., the Muslims) for what they have done, and I am clear from what the pagans have done\". Then he went forward with his sword and met Sa'd bin Mu'adh (fleeing) and said to him: \"By the Rubb of the Ka'bah! I can smell the fragrance of Jannah from a place closer than Uhud Mount\". Sa'd said: \"O Messenger of Allah, what he did was beyond my power\". Anas said: \"We saw over eighty wounds on his body caused by stabbing, striking and shooting of arrows and spears. We found that he was killed, and mutilated by the polytheists. Nobody was able to recognize him except his sister who recognized him by the tips of his fingers.\" Anas (May Allah be pleased with him) said: \"We believe that the Ayah 'Among the believers are men who have been true to their covenant with Allah [i.e., they have gone out for Jihad (holy fighting), and showed not their backs to the disbelievers]...' (33:23), refers to him and his like\".[Al-Bukhari and Muslim].","ar":"الخامس عشر‏:‏ عن أنس رضي الله عنه، قال‏:‏ غاب عمي أنس ابن النضر رضي الله عنه، عن قتال بدر، فقال‏:‏ يارسول الله غبت عن أول قتال قاتلت المشركين، لئن الله أشهدني قتال المشركين ليرين الله ما أصنع‏.‏ فلما كان يوم أحد انكشف المسلمون، فقال اللهم أعتذر إليك مما صنع هؤلاء - يعني أصحابه- وأبرأ إليك مما صنع هؤلاء- يعني المشركين- ثم تقدم فاستقبله سعد بن معاذ، فقال‏:‏ ياسعد بن معاذ الجنة ورب الكعبة، إني أجد ريحها من دون أحد‏.‏ قال سعد‏:‏ فما استطعت يا رسول الله ما صنع‏!‏ قال أنس‏:‏ فوجدنا به بضعاً وثمانين ضربة بالسيف، أو طعنة برمح ، أو رمية بسهم، ووجدناه قد قتل ومثل به المشركون فما عرفه أحد إلا أخته ببنانه‏.‏ قال أنس‏:‏ كنا نرى أو نظن أن هذه الآيه نزلت فيه وفي أشباهه‏:‏ ‏{‏من المؤمنين رجال صدقوا ما عهدوا الله عليه‏}‏ ‏(‏‏(‏ الأحزاب‏:‏ 23‏)‏‏)‏ إلى آخرها‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏","v":[]},{"c":"Riyad as-Salihin","r":"Hadith 1317","u":"https://quranx.com/Hadith/Saliheen/Reference/Hadith-1317","x":"Anas (May Allah be pleased with him) reported:\n\nMy uncle Anas bin An- Nadr (May Allah be pleased with him) was absent from the battle of Badr. He said: \"O Messenger of Allah! I was absent from the first battle you fought against the pagans. (By Allah!) if Allah gives me a chance to fight against the pagans, no doubt, Allah will see how (bravely) I will fight.\" On the Day of Uhud, when the Muslims turned their backs and fled, he said, \"O Allah! I apologize to You for what these (i.e., his companions) have done, and I denounce what these (i.e., the pagans) have done.\" Then he advanced and Sa'd bin Mu'adh met him. He said: \"O Sa'd bin Mu'adh! By the Rubb of An-Nadr, Jannah! I am smelling its aroma coming from before (the mountain of) Uhud,\" Later on, Sa'd said: \"O Messenger of Allah! I cannot achieve or do what he (i.e., Anas bin An-Nadr) did. We found more than eighty wounds by swords, spears and arrows on his body. We found him dead and his body was mutilated so badly that none except his sister could recognise him by his finger.\" We used to think that the following Ayah was revealed concerning him and other men of his sort: \"Among the believers are men who have been true to their covenant with Allah (i.e., they have gone out for Jihad, and showed not their backs to the disbelievers), of them some have fulfilled their obligations (i.e., have been martyred).\" (33:23).","ar":"وعنه قال‏:‏ غاب عمي أنس بن النضر رضي الله عنه عن قتال بدر، فقال‏:‏ يا رسول الله غبت عن أول قتال قاتلت الشركين لئن الله أشهدني قتال المشركين ليرين الله ما أصنع‏.‏ فلما كان يوم أحد انكشف المسلمون، فقال اللهم إني اعتذر إليك مما صنع هؤلاء - يعني الصحابة- وأبرأ إليك مما صنع هؤلاء يعني المشركين- ثم تقدم فاستقبله سعد بن معاذ فقال‏:‏ يا سعد بن معاذ الجنة ورب النضر، إني أجد ريحها من دون أحد‏!‏ قال سعد‏:‏ فما استطعت يا رسول الله ما صنع‏!‏ قال أنس‏:‏ فوجدنا به بضعًا وثمانين ضربة بالسيف، أو طعنة برمح أو رمية بسهم، ووجدناه قد قتل ومثل به المشركون، فما عرفه أحد إلا أخته ببنانه، قال أنس‏:‏ كنا نرى -أو نظن- أن هذه الآية نزلت فيه وفي أشباهه‏:‏ ‏{‏من المؤمنين رجال صدقوا ما عاهدوا الله عليه فمنهم من قضى نحبه‏}‏ إلى آخره ‏(‏‏(‏الأحزاب 23‏)‏‏)‏‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ وقد سبق في باب المجاهدة‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3104","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3104","x":"Narrated Az-Zuhri:\n\nfrom Anas who said: \"Hudhaifah bin Al-Yaman came to 'Uthman, at the time when the people of Ash-Sham and the people of Al-'Iraq were waging war to conquer Arminiyah and Adharbijan. Hudhaifah saw their (the people of Ash-Sham and Al-'Iraq) different forms of recitation of the Qur'an. So he said to 'Uthman: 'O Commander of the Believers! Save this nation before they differ about the Book as the Jews and the Christians did before them.' So he ('Uthman) sent a message to Hafsah (saying): 'Send us the manuscripts so that we may copy them in the Musahif (plural of Mushaf: a written copy of the Qur'an) then we shall return it to you.' So Hafsah sent the manuscripts to 'Uthman bin 'Affan. 'Uthman then sent order for Zaid bin Thabit, Sa'eed bin Al-'As, 'Abdur-Rahman bin Al-Harith bin Hisham, and 'Abdullah bin Az-Zubair to copy the manuscripts in the Musahif. 'Uthman said to the three Quraish men: 'In case you disagree with Zaid bin Thabit on any point in the (recitation dialect of the) Qur'an, then write it in the dialect of Quraish for it was in their tongue.' So when they had copied the manuscripts, 'Uthman sent one Mushaf from those Musahif that they had copied to every province.\" Az-Zuhri said: \"Kharijah bin Zaid [bin Thabit] narrated to me that Zaid bin Thabit said: 'I missed an Ayah of Surat Al-Ahzab that I heard the Messenger of Allah (ﷺ) reciting: Among the believers are men who have been true to their covenant with Allah, of them some have fulfilled their obligations, and some of them are still waiting (33:23) - so I searched for it and found it with Khuzaimah bin Thabit, or Abu Khuzaimah, so I put it in its Surah.'\" Az-Zuhri said: \"They differed then with At-Tabut and At-Tabuh. The Quraish said: At-Tabut while Zaid said: At-Tabuh. Their disagreement was brought to 'Uthman, so he said: 'Write it as At-Tabut, for it was revealed in the tongue of the Quraish.'\" Az-Zuhri said: \"'Ubaidullah bin 'Abdullah bin 'Utbah informed me that 'Abdullah bin Mas'ud disliked Zaid bin Thabit copying the Musahif, and he said: 'O you Muslim people! I am removed from recording the transcription of the Mushaf and it is overseen by a man, by Allah, when I accepted Islam he was but in the loins of a disbelieving man' - meaning Zaid bin Thabit - and it was regarding this that 'Abdullah bin Mas'ud said: 'O people of Al-'Iraq! Keep the Musahif that are with you, and conceal them. For indeed Allah said: And whoever conceals something, he shall come with what he concealed on the Day of Judgement (3:161). So meet Allah with the Musahif.'\" Az-Zuhri said: \"It was conveyed to me that some men amongst the most virtuous of the Companions of the Messenger of Allah (ﷺ) disliked that view of Ibn Mas'ud.\"","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ بَشَّارٍ، حَدَّثَنَا عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ، حَدَّثَنَا إِبْرَاهِيمُ بْنُ سَعْدٍ، عَنِ الزُّهْرِيِّ، عَنْ أَنَسٍ، أَنَّ حُذَيْفَةَ، قَدِمَ عَلَى عُثْمَانَ بْنِ عَفَّانَ وَكَانَ يُغَازِي أَهْلَ الشَّامِ فِي فَتْحِ أَرْمِينِيَّةَ وَأَذْرَبِيجَانَ مَعَ أَهْلِ الْعِرَاقِ فَرَأَى حُذَيْفَةُ اخْتِلاَفَهُمْ فِي الْقُرْآنِ فَقَالَ لِعُثْمَانَ بْنِ عَفَّانَ يَا أَمِيرَ الْمُؤْمِنِينَ أَدْرِكْ هَذِهِ الأُمَّةَ قَبْلَ أَنْ يَخْتَلِفُوا فِي الْكِتَابِ كَمَا اخْتَلَفَتِ الْيَهُودُ وَالنَّصَارَى فَأَرْسَلَ إِلَى حَفْصَةَ أَنْ أَرْسِلِي إِلَيْنَا بِالصُّحُفِ نَنْسَخُهَا فِي الْمَصَاحِفِ ثُمَّ نَرُدُّهَا إِلَيْكِ فَأَرْسَلَتْ حَفْصَةُ إِلَى عُثْمَانَ بِالصُّحُفِ فَأَرْسَلَ عُثْمَانُ إِلَى زَيْدِ بْنِ ثَابِتٍ وَسَعِيدِ بْنِ الْعَاصِي وَعَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ بْنِ هِشَامٍ وَعَبْدِ اللَّهِ بْنِ الزُّبَيْرِ أَنِ انْسَخُوا الصُّحُفَ فِي الْمَصَاحِفِ وَقَالَ لِلرَّهْطِ الْقُرَشِيِّينَ الثَّلاَثَةِ مَا اخْتَلَفْتُمْ فِيهِ أَنْتُمْ وَزَيْدُ بْنُ ثَابِتٍ فَاكْتُبُوهُ بِلِسَانِ قُرَيْشٍ فَإِنَّمَا نَزَلَ بِلِسَانِهِمْ ‏.‏ حَتَّى نَسَخُوا الصُّحُفَ فِي الْمَصَاحِفِ بَعَثَ عُثْمَانُ إِلَى كُلِّ أُفُقٍ بِمُصْحَفٍ مِنْ تِلْكَ الْمَصَاحِفِ الَّتِي نَسَخُوا ‏.‏ قَالَ الزُّهْرِيُّ وَحَدَّثَنِي خَارِجَةُ بْنُ زَيْدِ بْنِ ثَابِتٍ أَنَّ زَيْدَ بْنَ ثَابِتٍ قَالَ فَقَدْتُ آيَةً مِنْ سُورَةِ الأَحْزَابِ كُنْتُ أَسْمَعُ رَسُولَ اللَّهِ صلى الله عليه وسلم يَقْرَؤُهَا ‏:‏ ‏(‏ مِنَ الْمُؤْمِنِينَ رِجَالٌ صَدَقُوا مَا عَاهَدُوا اللَّهَ عَلَيْهِ فَمِنْهُمْ مَنْ قَضَى نَحْبَهُ ‏)‏ فَالْتَمَسْتُهَا فَوَجَدْتُهَا مَعَ خُزَيْمَةَ بْنِ ثَابِتٍ أَوْ أَبِي خُزَيْمَةَ فَأَلْحَقْتُهَا فِي سُورَتِهَا ‏.‏ قَالَ الزُّهْرِيُّ فَاخْتَلَفُوا يَوْمَئِذٍ فِي التَّابُوتِ وَالتَّابُوهِ فَقَالَ الْقُرَشِيُّونَ التَّابُوتُ ‏.‏ وَقَالَ زَيْدٌ التَّابُوهُ ‏.‏ فَرُفِعَ اخْتِلاَفُهُمْ إِلَى عُثْمَانَ فَقَالَ اكْتُبُوهُ التَّابُوتُ فَإِنَّهُ نَزَلَ بِلِسَانِ قُرَيْشٍ ‏.‏ قَالَ الزُّهْرِيُّ فَأَخْبَرَنِي عُبَيْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ بْنِ عُتْبَةَ أَنَّ عَبْدَ اللَّهِ بْنَ مَسْعُودٍ كَرِهَ لِزَيْدِ بْنِ ثَابِتٍ نَسْخَ الْمَصَاحِفِ وَقَالَ يَا مَعْشَرَ الْمُسْلِمِينَ أُعْزَلُ عَنْ نَسْخِ كِتَابَةِ الْمُصْحَفِ وَيَتَوَلاَّهَا رَجُلٌ وَاللَّهِ لَقَدْ أَسْلَمْتُ وَإِنَّهُ لَفِي صُلْبِ رَجُلٍ كَافِرٍ يُرِيدُ زَيْدَ بْنَ ثَابِتٍ وَلِذَلِكَ قَالَ عَبْدُ اللَّهِ بْنُ مَسْعُودٍ يَا أَهْلَ الْعِرَاقِ اكْتُمُوا الْمَصَاحِفَ الَّتِي عِنْدَكُمْ وَغُلُّوهَا فَإِنَّ اللَّهَ يَقُولُ ‏:‏ ‏(‏ وَمَنْ يَغْلُلْ يَأْتِ بِمَا غَلَّ يَوْمَ الْقِيَامَةِ ‏)‏ فَالْقُوا اللَّهَ بِالْمَصَاحِفِ ‏.‏ قَالَ الزُّهْرِيُّ فَبَلَغَنِي أَنَّ ذَلِكَ كَرِهَهُ مِنْ مَقَالَةِ ابْنِ مَسْعُودٍ رِجَالٌ مِنْ أَفَاضِلِ أَصْحَابِ النَّبِيِّ صلى الله عليه وسلم ‏.‏ قَالَ هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏ وَهُوَ حَدِيثُ الزُّهْرِيِّ لاَ نَعْرِفُهُ إِلاَّ مِنْ حَدِيثِهِ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3200","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3200","x":"Narrated Anas:\n\n\"My paternal uncle Anas bin An-Nadr - after whom I was named - did not participate in the battle of Badr with the Messenger of Allah (ﷺ). This distressed him and he said: 'I was absent from the first battle which the Messenger of Allah (ﷺ) attended. By Allah! If Allah gives me the opportunity to participate in another battle along with the Messenger of Allah (ﷺ), then Allah will see what I will do!'\" He said: \"He did not want to say more than that. A year later, he attended the battle of Uhud, where he saw Sa'd bin Mu'adh and said: 'O Abu 'Amr where are you going?' He said: 'I long for the fragrance of Paradise and I have found it near the mountains of Uhud.' He fought them until he was killed. They found more than eighty wounds on his body, be they from blows of a sword, puncture wounds, or arrows. My paternal aunt Ar-Ruba'i bin An-Nadr said: 'I could not recognize my brother except by his finger tips.' And this Ayah was revealed: 'Among the believers are men who have been true to their covenant with Allah; of them some have fulfilled their vow, and some of them are still waiting, but they have never changed in the least (33:23).'\"","ar":"حَدَّثَنَا أَحْمَدُ بْنُ مُحَمَّدٍ، حَدَّثَنَا عَبْدُ اللَّهِ بْنُ الْمُبَارَكِ، أَخْبَرَنَا سُلَيْمَانُ بْنُ الْمُغِيرَةِ، عَنْ ثَابِتٍ، عَنْ أَنَسٍ، قَالَ قَالَ عَمِّي أَنَسُ بْنُ النَّضْرِ سُمِّيتُ بِهِ لَمْ يَشْهَدْ بَدْرًا مَعَ رَسُولِ اللَّهِ صلى الله عليه وسلم فَكَبُرَ عَلَيْهِ فَقَالَ أَوَّلُ مَشْهَدٍ شَهِدَهُ رَسُولُ اللَّهِ صلى الله عليه وسلم غِبْتُ عَنْهُ أَمَا وَاللَّهِ لَئِنْ أَرَانِيَ اللَّهُ مَشْهَدًا مَعَ رَسُولِ اللَّهِ صلى الله عليه وسلم لَيَرَيَنَّ اللَّهُ مَا أَصْنَعُ ‏.‏ قَالَ فَهَابَ أَنْ يَقُولَ غَيْرَهَا فَشَهِدَ مَعَ رَسُولِ اللَّهِ صلى الله عليه وسلم يَوْمَ أُحُدٍ مِنَ الْعَامِ الْقَابِلِ فَاسْتَقْبَلَهُ سَعْدُ بْنُ مُعَاذٍ فَقَالَ يَا أَبَا عَمْرٍو أَيْنَ قَالَ وَاهًا لِرِيحِ الْجَنَّةِ أَجِدُهَا دُونَ أُحُدٍ فَقَاتَلَ حَتَّى قُتِلَ فَوُجِدَ فِي جَسَدِهِ بِضْعٌ وَثَمَانُونَ مِنْ بَيْنِ ضَرْبَةٍ وَطَعْنَةٍ وَرَمْيَةٍ فَقَالَتْ عَمَّتِي الرُّبَيِّعُ بِنْتُ النَّضْرِ فَمَا عَرَفْتُ أَخِي إِلاَّ بِبَنَانِهِ ‏.‏ وَنَزَلَتْ هَذِهِ الآيَةَُ ‏:‏ ‏(‏رجالٌ صَدَقُوا مَا عَاهَدُوا اللَّهَ عَلَيْهِ فَمِنْهُمْ مَنْ قَضَى نَحْبَهُ وَمِنْهُمْ مَنْ يَنْتَظِرُ وَمَا بَدَّلُوا تَبْدِيلاً ‏)‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3201","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3201","x":"Narrated Anas bin Malik:\n\n\"My paternal uncle was absent from the fighting of Badr, so he said: 'I was absent from the first fight the Messenger of Allah (ﷺ) fought with idolaters, so if Allah grants me to participate in a fight with the idolaters, then Allah will see what I will do!' So on the Day of Uhud, when the Muslims were driven back he said: 'O Allah! Indeed I am innocent before you of what these people - meaning the idolaters - have done, and I beg of You to excuse these people for what they have done - meaning the Companions. Then he went forward and met up with Sa'd. He said: 'O my brother! Whatever you do, I am with you!' But he was not able to do the same as him. He was found with more than eighty wounds, between blows with the sword, thrusts of a spear, or arrow wounds. We would say: 'It was about him and his companions that (the following) was revealed: 'Of them some have fulfilled their vow, and some of them are still waiting, but they have never changed in the least (33:23). (One of the narrators) Yazid said: \"Meaning this Ayah.\"","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، حَدَّثَنَا يَزِيدُ بْنُ هَارُونَ، أَخْبَرَنَا حُمَيْدٌ الطَّوِيلُ، عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّ عَمَّهُ، غَابَ عَنْ قِتَالِ، بَدْرٍ فَقَالَ غِبْتُ عَنْ أَوَّلِ، قِتَالٍ قَاتَلَهُ رَسُولُ اللَّهِ صلى الله عليه وسلم الْمُشْرِكِينَ لَئِنِ اللَّهُ أَشْهَدَنِي قِتَالاً لِلْمُشْرِكِينَ لَيَرَيَنَّ اللَّهُ كَيْفَ أَصْنَعُ فَلَمَّا كَانَ يَوْمُ أُحُدٍ انْكَشَفَ الْمُسْلِمُونَ فَقَالَ اللَّهُمَّ إِنِّي أَبْرَأُ إِلَيْكَ مِمَّا جَاءَ بِهِ هَؤُلاَءِ ‏.‏ يَعْنِي الْمُشْرِكِينَ وَأَعْتَذِرُ إِلَيْكَ مِمَّا يَصْنَعُ هَؤُلاَءِ ‏.‏ يَعْنِي أَصْحَابَهُ ثُمَّ تَقَدَّمَ فَلَقِيَهُ سَعْدٌ فَقَالَ يَا أَخِي مَا فَعَلْتَ أَنَا مَعَكَ فَلَمْ أَسْتَطِعْ أَنْ أَصْنَعَ مَا صَنَعَ ‏.‏ فَوُجِدَ فِيهِ بِضْعٌ وَثَمَانُونَ مِنْ ضَرْبَةٍ بِسَيْفٍ وَطَعْنَةٍ بِرُمْحٍ وَرَمْيَةٍ بِسَهْمٍ فَكُنَّا نَقُولُ فِيهِ وَفِي أَصْحَابِهِ نَزَلَتْ ‏:‏ ‏(‏فمِنْهُمْ مَنْ قَضَى نَحْبَهُ وَمِنْهُمْ مَنْ يَنْتَظِرُ ‏)‏ ‏.‏ قَالَ يَزِيدُ يَعْنِي هَذِهِ الآيَةَ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏ وَاسْمُ عَمِّهِ أَنَسُ بْنُ النَّضْرِ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 6, Book 46, Hadith 3741","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-6/Book-46/Hadith-3741","x":"Narrated Musa bin Talhah:\n\n\"I entered upon Mu'awiyah and he said: 'Shall I not give you some good news?' I said: 'Of course!' He said: 'I heard the Messenger of Allah (ﷺ) saying: 'Talhah is among those who fulfilled their vow (referring to 33:23).'\"","ar":"حَدَّثَنَا عَبْدُ الْقُدُّوسِ بْنُ مُحَمَّدٍ الْعَطَّارُ الْبَصْرِيُّ، قَالَ حَدَّثَنَا عَمْرُو بْنُ عَاصِمٍ، عَنْ إِسْحَاقَ بْنِ يَحْيَى بْنِ طَلْحَةَ، عَنْ عَمِّهِ، مُوسَى بْنِ طَلْحَةَ قَالَ دَخَلْتُ عَلَى مُعَاوِيَةَ فَقَالَ أَلاَ أُبَشِّرُكَ سَمِعْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم يَقُولُ ‏\n\n\"‏ طَلْحَةُ مِمَّنْ قَضَى نَحْبَهُ ‏\"\n\n‏ ‏.‏هَذَا حَدِيثٌ غَرِيبٌ لاَ نَعْرِفُهُ مِنْ حَدِيثِ مُعَاوِيَةَ إِلاَّ مِنْ هَذَا الْوَجْهِ ‏.‏","v":[]}],"28":[{"c":"Sahih Bukhari","r":"Hadith 2468","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2468","x":"Narrated `Abdullah bin `Abbas:\n\nI had been eager to ask `Umar about the two ladies from among the wives of the Prophet (ﷺ) regarding whom Allah said (in the Qur'an saying): If you two (wives of the Prophet (ﷺ) namely Aisha and Hafsa) turn in repentance to Allah your hearts are indeed so inclined (to oppose what the Prophet (ﷺ) likes) (66.4), till performed the Hajj along with `Umar (and on our way back from Hajj) he went aside (to answer the call of nature) and I also went aside along with him carrying a tumbler of water. When he had answered the call of nature and returned. I poured water on his hands from the tumbler and he performed ablution. I said, \"O Chief of the believers! ' Who were the two ladies from among the wives of the Prophet (ﷺ) to whom Allah said: 'If you two return in repentance (66.4)? He said, \"I am astonished at your question, O Ibn `Abbas. They were Aisha and Hafsa.\" Then `Umar went on relating the narration and said. \"I and an Ansari neighbor of mine from Bani Umaiya bin Zaid who used to live in `Awali Al-Medina, used to visit the Prophet (ﷺ) in turns. He used to go one day, and I another day. When I went I would bring him the news of what had happened that day regarding the instructions and orders and when he went, he used to do the same for me. We, the people of Quraish, used to have authority over women, but when we came to live with the Ansar, we noticed that the Ansari women had the upper hand over their men, so our women started acquiring the habits of the Ansari women. Once I shouted at my wife and she paid me back in my coin and I disliked that she should answer me back. She said, 'Why do you take it ill that I retort upon you? By Allah, the wives of the Prophet (ﷺ) retort upon him, and some of them may not speak with him for the whole day till night.' What she said scared me and I said to her, 'Whoever amongst them does so, will be a great loser.' Then I dressed myself and went to Hafsa and asked her, 'Does any of you keep Allah's Messenger (ﷺ) angry all the day long till night?' She replied in the affirmative. I said, 'She is a ruined losing person (and will never have success)! Doesn't she fear that Allah may get angry for the anger of Allah's Messenger (ﷺ) and thus she will be ruined? Don't ask Allah's Messenger (ﷺ) too many things, and don't retort upon him in any case, and don't desert him. Demand from me whatever you like, and don't be tempted to imitate your neighbor (i.e. `Aisha) in her behavior towards the Prophet), for she (i.e. Aisha) is more beautiful than you, and more beloved to Allah's Messenger (ﷺ). In those days it was rumored that Ghassan, (a tribe living in Sham) was getting prepared their horses to invade us. My companion went (to the Prophet (ﷺ) on the day of his turn, went and returned to us at night and knocked at my door violently, asking whether I was sleeping. I was scared (by the hard knocking) and came out to him. He said that a great thing had happened. I asked him: What is it? Have Ghassan come? He replied that it was worse and more serious than that, and added that Allah's Apostle had divorced all his wives. I said, Hafsa is a ruined loser! I expected that would happen some day.' So I dressed myself and offered the Fajr prayer with the Prophet. Then the Prophet (ﷺ) entered an upper room and stayed there alone. I went to Hafsa and found her weeping. I asked her, 'Why are you weeping? Didn't I warn you? Have Allah's Messenger (ﷺ) divorced you all?' She replied, 'I don't know. He is there in the upper room.' I then went out and came to the pulpit and found a group of people around it and some of them were weeping. Then I sat with them for some time, but could not endure the situation. So I went to the upper room where the Prophet (ﷺ) was and requested to a black slave of his: \"Will you get the permission of (Allah's Apostle) for `Umar (to enter)? The slave went in, talked to the Prophet (ﷺ) about it and came out saying, 'I mentioned you to him but he did not reply.' So, I went and sat with the people who were sitting by the pulpit, but I could not bear the situation, so I went to the slave again and said: \"Will you get he permission for `Umar? He went in and brought the same reply as before. When I was leaving, behold, the slave called me saying, \"Allah's Messenger (ﷺ) has granted you permission.\" So, I entered upon the Prophet and saw him lying on a mat without wedding on it, and the mat had left its mark on the body of the Prophet, and he was leaning on a leather pillow stuffed with palm fires. I greeted him and while still standing, I said: \"Have you divorced your wives?' He raised his eyes to me and replied in the negative. And then while still standing, I said chatting: \"Will you heed what I say, 'O Allah's Messenger (ﷺ)! We, the people of Quraish used to have the upper hand over our women (wives), and when we came to the people whose women had the upper hand over them...\" `Umar told the whole story (about his wife). \"On that the Prophet (ﷺ) smiled.\" `Umar further said, \"I then said, 'I went to Hafsa and said to her: Do not be tempted to imitate your companion (`Aisha) for she is more beautiful than you and more beloved to the Prophet.' The Prophet (ﷺ) smiled again. When I saw him smiling, I sat down and cast a glance at the room, and by Allah, I couldn't see anything of importance but three hides. I said (to Allah's Messenger (ﷺ)) \"Invoke Allah to make your followers prosperous for the Persians and the Byzantines have been made prosperous and given worldly luxuries, though they do not worship Allah?' The Prophet (ﷺ) was leaning then (and on hearing my speech he sat straight) and said, 'O Ibn Al-Khattab! Do you have any doubt (that the Hereafter is better than this world)? These people have been given rewards of their good deeds in this world only.' I asked the Prophet (ﷺ). 'Please ask Allah's forgiveness for me. The Prophet (ﷺ) did not go to his wives because of the secret which Hafsa had disclosed to `Aisha, and he said that he would not go to his wives for one month as he was angry with them when Allah admonished him (for his oath that he would not approach Maria). When twenty-nine days had passed, the Prophet (ﷺ) went to Aisha first of all. She said to him, 'You took an oath that you would not come to us for one month, and today only twenty-nine days have passed, as I have been counting them day by day.' The Prophet (ﷺ) said, 'The month is also of twenty-nine days.' That month consisted of twenty-nine days. `Aisha said, 'When the Divine revelation of Choice was revealed, the Prophet (ﷺ) started with me, saying to me, 'I am telling you something, but you need not hurry to give the reply till you can consult your parents.\" `Aisha knew that her parents would not advise her to part with the Prophet (ﷺ). The Prophet (ﷺ) said that Allah had said: 'O Prophet! Say To your wives; If you desire The life of this world And its glitter,... then come! I will make a provision for you and set you free In a handsome manner. But if you seek Allah And His Apostle, and The Home of the Hereafter, then Verily, Allah has prepared For the good-doers amongst you A great reward.' (33.28) `Aisha said, 'Am I to consult my parents about this? I indeed prefer Allah, His Apostle, and the Home of the Hereafter.' After that the Prophet (ﷺ) gave the choice to his other wives and they also gave the same reply as `Aisha did.\"","ar":"حَدَّثَنَا يَحْيَى بْنُ بُكَيْرٍ، حَدَّثَنَا اللَّيْثُ، عَنْ عُقَيْلٍ، عَنِ ابْنِ شِهَابٍ، قَالَ أَخْبَرَنِي عُبَيْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي ثَوْرٍ، عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ـ رضى الله عنهما ـ قَالَ لَمْ أَزَلْ حَرِيصًا عَلَى أَنْ أَسْأَلَ عُمَرَ ـ رضى الله عنه ـ عَنِ الْمَرْأَتَيْنِ مِنْ أَزْوَاجِ النَّبِيِّ صلى الله عليه وسلم اللَّتَيْنِ قَالَ اللَّهُ لَهُمَا ‏{‏إِنْ تَتُوبَا إِلَى اللَّهِ فَقَدْ صَغَتْ قُلُوبُكُمَا‏}‏ فَحَجَجْتُ مَعَهُ فَعَدَلَ وَعَدَلْتُ مَعَهُ بِالإِدَاوَةِ، فَتَبَرَّزَ حَتَّى جَاءَ، فَسَكَبْتُ عَلَى يَدَيْهِ مِنَ الإِدَاوَةِ، فَتَوَضَّأَ فَقُلْتُ يَا أَمِيرَ الْمُؤْمِنِينَ مَنِ الْمَرْأَتَانِ مِنْ أَزْوَاجِ النَّبِيِّ صلى الله عليه وسلم اللَّتَانِ قَالَ لَهُمَا ‏{‏إِنْ تَتُوبَا إِلَى اللَّهِ‏}‏ فَقَالَ وَاعَجَبِي لَكَ يَا ابْنَ عَبَّاسٍ عَائِشَةُ وَحَفْصَةُ، ثُمَّ اسْتَقْبَلَ عُمَرُ الْحَدِيثَ يَسُوقُهُ، فَقَالَ إِنِّي كُنْتُ وَجَارٌ لِي مِنَ الأَنْصَارِ فِي بَنِي أُمَيَّةَ بْنِ زَيْدٍ، وَهْىَ مِنْ عَوَالِي الْمَدِينَةِ، وَكُنَّا نَتَنَاوَبُ النُّزُولَ عَلَى النَّبِيِّ صلى الله عليه وسلم فَيَنْزِلُ يَوْمًا وَأَنْزِلُ يَوْمًا، فَإِذَا نَزَلْتُ جِئْتُهُ مِنْ خَبَرِ ذَلِكَ الْيَوْمِ مِنَ الأَمْرِ وَغَيْرِهِ، وَإِذَا نَزَلَ فَعَلَ مِثْلَهُ، وَكُنَّا مَعْشَرَ قُرَيْشٍ نَغْلِبُ النِّسَاءَ، فَلَمَّا قَدِمْنَا عَلَى الأَنْصَارِ إِذَا هُمْ قَوْمٌ تَغْلِبُهُمْ نِسَاؤُهُمْ، فَطَفِقَ نِسَاؤُنَا يَأْخُذْنَ مِنْ أَدَبِ نِسَاءِ الأَنْصَارِ، فَصِحْتُ عَلَى امْرَأَتِي، فَرَاجَعَتْنِي، فَأَنْكَرْتُ أَنْ تُرَاجِعَنِي، فَقَالَتْ وَلِمَ تُنْكِرُ أَنْ أُرَاجِعَكَ فَوَاللَّهِ إِنَّ أَزْوَاجَ النَّبِيِّ صلى الله عليه وسلم لَيُرَاجِعْنَهُ، وَإِنَّ إِحْدَاهُنَّ لَتَهْجُرُهُ الْيَوْمَ حَتَّى اللَّيْلِ‏.‏ فَأَفْزَعَنِي، فَقُلْتُ خَابَتْ مَنْ فَعَلَ مِنْهُنَّ بِعَظِيمٍ‏.‏ ثُمَّ جَمَعْتُ عَلَىَّ ثِيَابِي، فَدَخَلْتُ عَلَى حَفْصَةَ فَقُلْتُ أَىْ حَفْصَةُ، أَتُغَاضِبُ إِحْدَاكُنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم الْيَوْمَ حَتَّى اللَّيْلِ فَقَالَتْ نَعَمْ‏.‏ فَقُلْتُ خَابَتْ وَخَسِرَتْ، أَفَتَأْمَنُ أَنْ يَغْضَبَ اللَّهُ لِغَضَبِ رَسُولِهِ صلى الله عليه وسلم فَتَهْلِكِينَ لاَ تَسْتَكْثِرِي عَلَى رَسُولِ اللَّهِ صلى الله عليه وسلم وَلاَ تُرَاجِعِيهِ فِي شَىْءٍ وَلاَ تَهْجُرِيهِ، وَاسْأَلِينِي مَا بَدَا لَكِ، وَلاَ يَغُرَّنَّكِ أَنْ كَانَتْ جَارَتُكِ هِيَ أَوْضَأَ مِنْكِ وَأَحَبَّ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم ـ يُرِيدُ عَائِشَةَ ـ وَكُنَّا تَحَدَّثْنَا أَنَّ غَسَّانَ تُنْعِلُ النِّعَالَ لِغَزْوِنَا، فَنَزَلَ صَاحِبِي يَوْمَ نَوْبَتِهِ فَرَجَعَ عِشَاءً، فَضَرَبَ بَابِي ضَرْبًا شَدِيدًا، وَقَالَ أَنَائِمٌ هُوَ فَفَزِعْتُ فَخَرَجْتُ إِلَيْهِ‏.‏ وَقَالَ حَدَثَ أَمْرٌ عَظِيمٌ‏.‏ قُلْتُ مَا هُوَ أَجَاءَتْ غَسَّانُ قَالَ لاَ، بَلْ أَعْظَمُ مِنْهُ وَأَطْوَلُ، طَلَّقَ رَسُولُ اللَّهِ صلى الله عليه وسلم نِسَاءَهُ‏.‏ قَالَ قَدْ خَابَتْ حَفْصَةُ وَخَسِرَتْ، كُنْتُ أَظُنُّ أَنَّ هَذَا يُوشِكُ أَنْ يَكُونَ، فَجَمَعْتُ عَلَىَّ ثِيَابِي، فَصَلَّيْتُ صَلاَةَ الْفَجْرِ مَعَ النَّبِيِّ صلى الله عليه وسلم فَدَخَلَ مَشْرُبَةً لَهُ فَاعْتَزَلَ فِيهَا، فَدَخَلْتُ عَلَى حَفْصَةَ، فَإِذَا هِيَ تَبْكِي‏.‏ قُلْتُ مَا يُبْكِيكِ أَوَلَمْ أَكُنْ حَذَّرْتُكِ أَطَلَّقَكُنَّ رَسُولُ اللَّهِ صلى الله عليه وسلم قَالَتْ لاَ أَدْرِي هُوَ ذَا فِي الْمَشْرُبَةِ‏.‏ فَخَرَجْتُ، فَجِئْتُ الْمِنْبَرَ، فَإِذَا حَوْلَهُ رَهْطٌ يَبْكِي بَعْضُهُمْ، فَجَلَسْتُ مَعَهُمْ قَلِيلاً ثُمَّ غَلَبَنِي مَا أَجِدُ، فَجِئْتُ الْمَشْرُبَةَ الَّتِي هُوَ فِيهَا فَقُلْتُ لِغُلاَمٍ لَهُ أَسْوَدَ اسْتَأْذِنْ لِعُمَرَ‏.‏ فَدَخَلَ، فَكَلَّمَ النَّبِيَّ صلى الله عليه وسلم ثُمَّ خَرَجَ، فَقَالَ ذَكَرْتُكَ لَهُ، فَصَمَتَ، فَانْصَرَفْتُ حَتَّى جَلَسْتُ مَعَ الرَّهْطِ الَّذِينَ عِنْدَ الْمِنْبَرِ، ثُمَّ غَلَبَنِي مَا أَجِدُ فَجِئْتُ، فَذَكَرَ مِثْلَهُ، فَجَلَسْتُ مَعَ الرَّهْطِ الَّذِينَ عِنْدَ الْمِنْبَرِ، ثُمَّ غَلَبَنِي مَا أَجِدُ فَجِئْتُ الْغُلاَمَ‏.‏ فَقُلْتُ اسْتَأْذِنْ لِعُمَرَ‏.‏ فَذَكَرَ مِثْلَهُ، فَلَمَّا وَلَّيْتُ مُنْصَرِفًا، فَإِذَا الْغُلاَمُ يَدْعُونِي قَالَ أَذِنَ لَكَ رَسُولُ اللَّهِ صلى الله عليه وسلم‏.‏ فَدَخَلْتُ عَلَيْهِ، فَإِذَا هُوَ مُضْطَجِعٌ عَلَى رِمَالِ حَصِيرٍ لَيْسَ بَيْنَهُ وَبَيْنَهُ فِرَاشٌ، قَدْ أَثَّرَ الرِّمَالُ بِجَنْبِهِ، مُتَّكِئٌ عَلَى وِسَادَةٍ مِنْ أَدَمٍ حَشْوُهَا لِيفٌ، فَسَلَّمْتُ عَلَيْهِ، ثُمَّ قُلْتُ وَأَنَا قَائِمٌ طَلَّقْتَ نِسَاءَكَ فَرَفَعَ بَصَرَهُ إِلَىَّ، فَقَالَ ‏\"‏ لاَ ‏\"‏‏.‏ ثُمَّ قُلْتُ ـ وَأَنَا قَائِمٌ أَسْتَأْنِسُ يَا رَسُولَ اللَّهِ، لَوْ رَأَيْتَنِي، وَكُنَّا مَعْشَرَ قُرَيْشٍ نَغْلِبُ النِّسَاءَ، فَلَمَّا قَدِمْنَا عَلَى قَوْمٍ تَغْلِبُهُمْ نِسَاؤُهُمْ، فَذَكَرَهُ، فَتَبَسَّمَ النَّبِيُّ صلى الله عليه وسلم، ثُمَّ قُلْتُ لَوْ رَأَيْتَنِي، وَدَخَلْتُ عَلَى حَفْصَةَ، فَقُلْتُ لاَ يَغُرَّنَّكِ أَنْ كَانَتْ جَارَتُكِ هِيَ أَوْضَأَ مِنْكِ وَأَحَبَّ إِلَى النَّبِيِّ صلى الله عليه وسلم ـ يُرِيدُ عَائِشَةَ ـ فَتَبَسَّمَ أُخْرَى، فَجَلَسْتُ حِينَ رَأَيْتُهُ تَبَسَّمَ، ثُمَّ رَفَعْتُ بَصَرِي فِي بَيْتِهِ، فَوَاللَّهِ مَا رَأَيْتُ فِيهِ شَيْئًا يَرُدُّ الْبَصَرَ غَيْرَ أَهَبَةٍ ثَلاَثَةٍ‏.‏ فَقُلْتُ ادْعُ اللَّهَ فَلْيُوَسِّعْ عَلَى أُمَّتِكَ، فَإِنَّ فَارِسَ وَالرُّومَ وُسِّعَ عَلَيْهِمْ وَأُعْطُوا الدُّنْيَا، وَهُمْ لاَ يَعْبُدُونَ اللَّهَ، وَكَانَ مُتَّكِئًا‏.‏ فَقَالَ ‏\"‏ أَوَفِي شَكٍّ أَنْتَ يَا ابْنَ الْخَطَّابِ أُولَئِكَ قَوْمٌ عُجِّلَتْ لَهُمْ طَيِّبَاتُهُمْ فِي الْحَيَاةِ الدُّنْيَا ‏\"‏‏.‏ فَقُلْتُ يَا رَسُولَ اللَّهِ اسْتَغْفِرْ لِي‏.‏ فَاعْتَزَلَ النَّبِيُّ صلى الله عليه وسلم مِنْ أَجْلِ ذَلِكَ الْحَدِيثِ حِينَ أَفْشَتْهُ حَفْصَةُ إِلَى عَائِشَةَ، وَكَانَ قَدْ قَالَ ‏\"‏ مَا أَنَا بِدَاخِلٍ عَلَيْهِنَّ شَهْرًا ‏\"‏‏.‏ مِنْ شِدَّةِ مَوْجَدَتِهِ عَلَيْهِنَّ حِينَ عَاتَبَهُ اللَّهُ‏.‏ فَلَمَّا مَضَتْ تِسْعٌ وَعِشْرُونَ دَخَلَ عَلَى عَائِشَةَ فَبَدَأَ بِهَا، فَقَالَتْ لَهُ عَائِشَةُ إِنَّكَ أَقْسَمْتَ أَنْ لاَ تَدْخُلَ عَلَيْنَا شَهْرًا، وَإِنَّا أَصْبَحْنَا لِتِسْعٍ وَعِشْرِينَ لَيْلَةً، أَعُدُّهَا عَدًّا‏.‏ فَقَالَ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ الشَّهْرُ تِسْعٌ وَعِشْرُونَ ‏\"‏‏.‏ وَكَانَ ذَلِكَ الشَّهْرُ تِسْعٌ وَعِشْرُونَ‏.‏ قَالَتْ عَائِشَةُ فَأُنْزِلَتْ آيَةُ التَّخْيِيرِ فَبَدَأَ بِي أَوَّلَ امْرَأَةٍ، فَقَالَ ‏\"‏ إِنِّي ذَاكِرٌ لَكِ أَمْرًا، وَلاَ عَلَيْكِ أَنْ لاَ تَعْجَلِي حَتَّى تَسْتَأْمِرِي أَبَوَيْكِ ‏\"‏‏.‏ قَالَتْ قَدْ أَعْلَمُ أَنَّ أَبَوَىَّ لَمْ يَكُونَا يَأْمُرَانِي بِفِرَاقِكَ‏.‏ ثُمَّ قَالَ ‏\"‏ إِنَّ اللَّهَ قَالَ ‏{‏يَا أَيُّهَا النَّبِيُّ قُلْ لأَزْوَاجِكَ‏}‏ إِلَى قَوْلِهِ ‏{‏ عَظِيمًا‏}‏ ‏\"‏‏.‏ قُلْتُ أَفِي هَذَا أَسْتَأْمِرُ أَبَوَىَّ فَإِنِّي أُرِيدُ اللَّهَ وَرَسُولَهُ وَالدَّارَ الآخِرَةَ‏.‏ ثُمَّ خَيَّرَ نِسَاءَهُ، فَقُلْنَ مِثْلَ مَا قَالَتْ عَائِشَةُ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4785","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4785","x":"Narrated `Aisha:\n\n(the wife of the Prophet) Allah's Messenger (ﷺ) came to me when Allah ordered him to give option to his wives. So Allah's Messenger (ﷺ) started with me, saying, \"I am going to mention to you something but you should not hasten (to give your reply) unless you consult your parents.' He knew that my parents would not order me to leave him. Then he said, \"Allah says:-- \"O Prophet! Say to your wives...\" (33.28-29) On that I said to him, \"Then why should I consult my parents? Verily, I seek Allah, His Apostle and the Home of the Hereafter.\"","ar":"حَدَّثَنَا أَبُو الْيَمَانِ، أَخْبَرَنَا شُعَيْبٌ، عَنِ الزُّهْرِيِّ، قَالَ أَخْبَرَنِي أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ، أَنَّ عَائِشَةَ، رضى الله عنها زَوْجَ النَّبِيِّ صلى الله عليه وسلم أَخْبَرَتْهُ أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم جَاءَهَا حِينَ أَمَرَ اللَّهُ أَنْ يُخَيِّرَ أَزْوَاجَهُ، فَبَدَأَ بِي رَسُولُ اللَّهِ صلى الله عليه وسلم فَقَالَ ‏\"‏ إِنِّي ذَاكِرٌ لَكِ أَمْرًا فَلاَ عَلَيْكِ أَنْ تَسْتَعْجِلِي حَتَّى تَسْتَأْمِرِي أَبَوَيْكِ ‏\"‏، وَقَدْ عَلِمَ أَنَّ أَبَوَىَّ لَمْ يَكُونَا يَأْمُرَانِي بِفِرَاقِهِ، قَالَتْ ثُمَّ قَالَ ‏\"‏ إِنَّ اللَّهَ قَالَ ‏{‏يَا أَيُّهَا النَّبِيُّ قُلْ لأَزْوَاجِكَ‏}‏ ‏\"‏‏.‏ إِلَى تَمَامِ الآيَتَيْنِ فَقُلْتُ لَهُ فَفِي أَىِّ هَذَا أَسْتَأْمِرُ أَبَوَىَّ فَإِنِّي أُرِيدُ اللَّهَ وَرَسُولَهُ وَالدَّارَ الآخِرَةَ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4786","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4786","x":"Narrated `Aisha:\n\n(the wife of the Prophet) when Allah's Messenger (ﷺ) was ordered to give option to his wives, he started with me, saying, \"I am going to mention to you something, but you shall not hasten (to give your reply) unless you consult your parents.\" The Prophet (ﷺ) knew that my parents would not order me to leave him. Then he said, \"Allah says: 'O Prophet (Muhammad)! Say to your wives: If you desire the life of this world and its glitter........a great reward.\" (33.28-29) I said, \"Then why I consult my parents? Verily, I seek Allah, His Apostle and the Home of the Hereafter.\" Then all the other wives of the Prophet (ﷺ) did the same as I did.","ar":"وَقَالَ اللَّيْثُ حَدَّثَنِي يُونُسُ، عَنِ ابْنِ شِهَابٍ، قَالَ أَخْبَرَنِي أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ، أَنَّ عَائِشَةَ، زَوْجَ النَّبِيِّ صلى الله عليه وسلم قَالَتْ لَمَّا أُمِرَ رَسُولُ اللَّهِ صلى الله عليه وسلم بِتَخْيِيرِ أَزْوَاجِهِ بَدَأَ بِي فَقَالَ ‏\"‏ إِنِّي ذَاكِرٌ لَكِ أَمْرًا فَلاَ عَلَيْكِ أَنْ لاَ تَعْجَلِي حَتَّى تَسْتَأْمِرِي أَبَوَيْكِ ‏\"‏‏.‏ قَالَتْ وَقَدْ عَلِمَ أَنَّ أَبَوَىَّ لَمْ يَكُونَا يَأْمُرَانِي بِفِرَاقِهِ، قَالَتْ ثُمَّ قَالَ ‏\"‏ إِنَّ اللَّهَ جَلَّ ثَنَاؤُهُ قَالَ ‏{‏يَا أَيُّهَا النَّبِيُّ قُلْ لأَزْوَاجِكَ إِنْ كُنْتُنَّ تُرِدْنَ الْحَيَاةَ الدُّنْيَا وَزِينَتَهَا‏}‏ إِلَى ‏{‏أَجْرًا عَظِيمًا‏}‏ ‏\"‏‏.‏ قَالَتْ فَقُلْتُ فَفِي أَىِّ هَذَا أَسْتَأْمِرُ أَبَوَىَّ فَإِنِّي أُرِيدُ اللَّهَ وَرَسُولَهُ وَالدَّارَ الآخِرَةَ، قَالَتْ ثُمَّ فَعَلَ أَزْوَاجُ النَّبِيِّ صلى الله عليه وسلم مِثْلَ مَا فَعَلْتُ‏.‏ تَابَعَهُ مُوسَى بْنُ أَعْيَنَ عَنْ مَعْمَرٍ عَنِ الزُّهْرِيِّ قَالَ أَخْبَرَنِي أَبُو سَلَمَةَ‏.‏ وَقَالَ عَبْدُ الرَّزَّاقِ وَأَبُو سُفْيَانَ الْمَعْمَرِيُّ عَنْ مَعْمَرٍ عَنِ الزُّهْرِيِّ عَنْ عُرْوَةَ عَنْ عَائِشَةَ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 1478","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-1478","x":"Jabir b. 'Abdullah (Allah be pleased with them) reported:\n\nAbu Bakr (Allah be pleased with him) came and sought permission to see Allah's Messenger (ﷺ). He found people sitting at his door and none amongst them had been granted permission, but it was granted to Abu Bakr and he went in. Then came 'Umar and he sought permission and it was granted to him, and he found Allah's Apostle (ﷺ) sitting sad and silent with his wives around him. He (Hadrat 'Umar) said: I would say something which would make the Prophet (ﷺ) laugh, so he said: Messenger of Allah, I wish you had seen (the treatment meted out to) the daughter ofKhadija when you asked me some money, and I got up and slapped her on her neck. Allah's Messenger (mav peace be upon him) laughed and said: They are around me as you see, asking for extra money. Abu Bakr (Allah be pleased with him) then got up went to 'A'isha (Allah be pleased with her) and slapped her on the neck, and 'Umar stood up before Hafsa and slapped her saying: You ask Allah's Messenger (ﷺ) which he does not possess. They said: By Allah, we do not ask Allah's Messenger (ﷺ) for anything he does not possess. Then he withdrew from them for a month or for twenty-nine days. Then this verse was revealed to him:\" Prophet: Say to thy wives... for a mighty reward\" (xxxiii. 28). He then went first to 'A'isha (Allah be pleased with her) and said: I want to propound something to you, 'A'isha, but wish no hasty reply before you consult your parents. She said: Messenger of Allah, what is that? He (the Holy Prophet) recited to her the verse, whereupon she said: Is it about you that I should consult my parents, Messenger of Allah? Nay, I choose Allah, His Messenger, and the Last Abode; but I ask you not to tell any of your wives what I have said He replied: Not one of them will ask me without my informing her. God did not send me to be harsh, or cause harm, but He has sent me to teach and make things easy.","ar":"وَحَدَّثَنَا زُهَيْرُ بْنُ حَرْبٍ، حَدَّثَنَا رَوْحُ بْنُ عُبَادَةَ، حَدَّثَنَا زَكَرِيَّاءُ بْنُ إِسْحَاقَ، حَدَّثَنَا أَبُو الزُّبَيْرِ، عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ دَخَلَ أَبُو بَكْرٍ يَسْتَأْذِنُ عَلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَوَجَدَ النَّاسَ جُلُوسًا بِبَابِهِ لَمْ يُؤْذَنْ لأَحَدٍ مِنْهُمْ - قَالَ - فَأُذِنَ لأَبِي بَكْرٍ فَدَخَلَ ثُمَّ أَقْبَلَ عُمَرُ فَاسْتَأْذَنَ فَأُذِنَ لَهُ فَوَجَدَ النَّبِيَّ صلى الله عليه وسلم جَالِسًا حَوْلَهُ نِسَاؤُهُ وَاجِمًا سَاكِتًا - قَالَ - فَقَالَ لأَقُولَنَّ شَيْئًا أُضْحِكُ النَّبِيَّ صلى الله عليه وسلم فَقَالَ يَا رَسُولَ اللَّهِ لَوْ رَأَيْتَ بِنْتَ خَارِجَةَ سَأَلَتْنِي النَّفَقَةَ فَقُمْتُ إِلَيْهَا فَوَجَأْتُ عُنُقَهَا ‏.‏ فَضَحِكَ رَسُولُ اللَّهِ صلى الله عليه وسلم وَقَالَ ‏\"‏ هُنَّ حَوْلِي كَمَا تَرَى يَسْأَلْنَنِي النَّفَقَةَ ‏\"‏ ‏.‏ فَقَامَ أَبُو بَكْرٍ إِلَى عَائِشَةَ يَجَأُ عُنُقَهَا فَقَامَ عُمَرُ إِلَى حَفْصَةَ يَجَأُ عُنُقَهَا كِلاَهُمَا يَقُولُ تَسْأَلْنَ رَسُولَ اللَّهِ صلى الله عليه وسلم مَا لَيْسَ عِنْدَهُ ‏.‏ فَقُلْنَ وَاللَّهِ لاَ نَسْأَلُ رَسُولَ اللَّهِ صلى الله عليه وسلم شَيْئًا أَبَدًا لَيْسَ عِنْدَهُ ثُمَّ اعْتَزَلَهُنَّ شَهْرًا أَوْ تِسْعًا وَعِشْرِينَ ثُمَّ نَزَلَتْ عَلَيْهِ هَذِهِ الآيَةُ ‏{‏ يَا أَيُّهَا النَّبِيُّ قُلْ لأَزْوَاجِكَ‏}‏ حَتَّى بَلَغَ ‏{‏ لِلْمُحْسِنَاتِ مِنْكُنَّ أَجْرًا عَظِيمًا‏}‏ قَالَ فَبَدَأَ بِعَائِشَةَ فَقَالَ ‏\"‏ يَا عَائِشَةُ إِنِّي أُرِيدُ أَنْ أَعْرِضَ عَلَيْكَ أَمْرًا أُحِبُّ أَنْ لاَ تَعْجَلِي فِيهِ حَتَّى تَسْتَشِيرِي أَبَوَيْكِ ‏\"‏ ‏.‏ قَالَتْ وَمَا هُوَ يَا رَسُولَ اللَّهِ فَتَلاَ عَلَيْهَا الآيَةَ قَالَتْ أَفِيكَ يَا رَسُولَ اللَّهِ أَسْتَشِيرُ أَبَوَىَّ بَلْ أَخْتَارُ اللَّهَ وَرَسُولَهُ وَالدَّارَ الآخِرَةَ وَأَسْأَلُكَ أَنْ لاَ تُخْبِرَ امْرَأَةً مِنْ نِسَائِكَ بِالَّذِي قُلْتُ ‏.‏ قَالَ ‏\"‏ لاَ تَسْأَلُنِي امْرَأَةٌ مِنْهُنَّ إِلاَّ أَخْبَرْتُهَا إِنَّ اللَّهَ لَمْ يَبْعَثْنِي مُعَنِّتًا وَلاَ مُتَعَنِّتًا وَلَكِنْ بَعَثَنِي مُعَلِّمًا مُيَسِّرًا ‏\"‏ ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 1479e","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-1479e","x":"Ibn 'Abbas (Allah be pleased with them) reported. I had always been anxious to ask 'Umar (Allah be pleased with him) about the two ladies amongst the wives of Allah's Prophet (may peace be upon Lim) about whom Allah, the Exalted, said:\n\n\" If you both turn in repentance to Allah, then indeed your hearts are inclined (to this)\" (Ixvi. 4), until 'Umar (Allah be pleased with him) set out for Hajj and I also went along with him. And as we were going along a path, 'Umar (Allah be pleased with hiyn) went aside and I also went aside with him with a jug (of water). He answered the call of nature, and then came to me and I poured water over his hands and he performed ablution I said: Commander of the Faithful, who are the two ladies amongst the wives of Allah's Prophet (ﷺ) about whom Allah, the Exalted and Majestic, said: 'If you both turn to Allah in repentance, then indeed your heart are inclined to it\"? 'Umar (Allah he pleased with him) said: How strange is it for you, Ibn 'Abbas! (Zuhri said: By Allah, he disliked what he asked about, but did not keep it a secret.) He ('Umar) said: They are Hafsa and 'A'isha; and he then began to narrate the hadith and said: We were such people among the Quraish who dominated women, and as we reached Medina we found there people who were dominated by their women, and our women began to learn (the habits) of their women. He further said: And my house was situated in the suburb of Aledina in the tribe of Banu Umayya b. Zaid. One day I became angry with my wife and she retorted upon me. I did not like that she should retort upon me. She said: You disapprove of my retorting upon you By Allah, the wives of Allah's Apostle (ﷺ) retort upon him, and one of them detaches herself from him for the day until the night. So I ('Umar) went out and visited Hafsa and said: Do you retort upon Allah's Messenger (ﷺ)? She said: Yes. I said; Does any one of you detach herself from him from the day to the night? She said: Yes. He said: She who did like it amongst you in fact failed and incurred loss. Does everyone amongst you not fear the wrath of Allah upon her due to the wrath of His Messenger (ﷺ), and (as a result thereof) she may perish? So do not retort upon Allah's Messenger (ﷺ) and do not ask him for anything, but ask me that which you desire, (and the frank behaviour) of your companion may not mislead you, if she is more graceful and is dearer to Allah's Messenger (ﷺ) than you (meaning 'A'isha) (Allah be pleased with her). He (Hadrat 'Umar further) said: I had a compalaion from the Ansar and, we used to remain in the company of the Messenger (ﷺ) turn by turn. He remained there for a day while I remained there on the other day, and he brought me the news about the revelation and other (matter), and I brought him (the news) like this. And we discussed that the Ghassanids were shoeing the horses in order to attack us. Id y companion once attended (the Apostle). and then came to me at night and knocked at my door and called me, and I came out to him, and he said: A matter of great importance has happened. I said: What is that? Have the Ghassanids come? He said: No, but even more serious and more significant than that: the Prophet (ﷺ) has divorced his wives. I said: Hafsa has failed and has incurred loss. and I feared that it would happen. When it was dawn I observed the dawn prayer and dressed myself, and then came there (in the house of the Holy Prophet) and visited Hafsa, and she was weeping. I said: Has Allah's Messenger (ﷺ) divorced you (all)? She said: I do not know. He has, however, separated himself in his attic. I came to a black servant and said to him: Seek permission for 'Umar. He went in and then came to me and said: I made mention of you to him, but he kept quiet. I then went to the pulpit and sat there, and there was a group of people sitting by it and some of then were weeping. I sat there for some time, until I was overpowered (by that very idea) which was in my mind. I then came back to the boy and said to him: Seek permission for Umar. He went in and came to me and said: I made mention of you to him but he kept quiet. I was about to turn back when the boy called me and said: Go in; permission has been granted to you. I went in and greeted Allah's Messenger (ﷺ) and he was reclining against the couch of mat and it had left its marks upon his side. I said: Messenger of Allah, have you divorced your wives? He raised his head towards me and said: No. I said: Allah is the Greatest. Messenger of Allah, I wish if you had seen how we the people of Quraish had domination over women but when we came to Medina we found people whom their women dominated. So our women began to learn from their women. One dily I became angry with my wife and she began to retort upon me. I did not approve that she should retort upon me. She said: You do not like that I should retort upon you, but, by Allah. the wives of Allah's Apostle (ﷺ) retort upon him and any one of them separates herself from him for a day until night. I said: He who did that amongst them in fact failed and incurred loss. Does any of them feel sate from the wrath of Allahupon her due to the wrath of Allah's Messenger (ﷺ), and she has certainly perished. Allah's Messtnger (ﷺ) smiled, I said: Messenger of Allah, I visited Hafsa and said: (The behaviour) of your companion ('A'isha) may not mislead you, If she is more graceful than you and is dearer to Allah's Messenger (ﷺ) than you. Allah's Messenger (ﷺ) smiled for the second time. I said: Allah's Messenger, way I talk to you about agreeable things? He said: Yes. I sat down and lifted my head (to see things) in the house and, by Allah, I did not see anything significant besides three hides. I said: Messenger of Allah, supplicate the Lord that He should make (life) prosperous for your Ummah as He has made plentiful for the people of Persia and Rome (in spite of the fact) that they do no, worship Allah, the Exalted and Majestic, whereupon he (Allah's Messenger) sat up an I then said: Ibn Khattab, do you doubt that they are a nation whom their nice things have been given immediately in the life of this world. I said: Allah's Messenger! seek pardon for me. And he (Allah's Messenger) had taken an oath that he would not visit them for a month due to extreme annoyance with them until Allah showed His displeasure to him (Allah's Messenger). Zuhri said: 'Urwa informed me that 'A'Isha (Allah be pleased with her) said: When twenty-nine nights were over, Allah's Messenger (ﷺ) visited me, and he began (his visit) with me. I said: Messenger of Allah, you had taken an oath that you would not visit us for a month, while you have visited after I have counted only twenty-nine (nights). Thereupon he said: The month may also be of twenty-nine (days). He then said: 'A'isha, I am going to talk to you about a matter, and you should not be hasty in it (and do not give your final decision) until you have consulted your parents. He then recited this verse to me:\" O Prophet, say to your wives\" till he reached\" mighty reward\" (xxxiii. 28). 'A'isha (Allah be pleased with her) said: By Allah, he knew that my parents would not allow me to separate from him. I said: Is there any need to consult my parents in this matter? I in fact choose Allah and His Messenger (ﷺ) and the abode in the Hereafter. Ma'mar said: Ayyub reported to me that 'A'isha said: Don't inform your wives that I have chosen you, whereupon Allah's Apostle (ﷺ) said: Verily Allah has sent me as a conveyer of message, and He has not sent me as a source of hardship (to others). Qatada said:\" Saghat qulubukum\" means\" Your hearts have inclined.\"","ar":"وَحَدَّثَنَا إِسْحَاقُ بْنُ إِبْرَاهِيمَ الْحَنْظَلِيُّ، وَمُحَمَّدُ بْنُ أَبِي عُمَرَ، - وَتَقَارَبَا فِي لَفْظِ الْحَدِيثِ - قَالَ ابْنُ أَبِي عُمَرَ حَدَّثَنَا وَقَالَ، إِسْحَاقُ أَخْبَرَنَا عَبْدُ الرَّزَّاقِ، أَخْبَرَنَا مَعْمَرٌ، عَنِ الزُّهْرِيِّ، عَنْ عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي ثَوْرٍ، عَنِ ابْنِ عَبَّاسٍ، قَالَ لَمْ أَزَلْ حَرِيصًا أَنْأَسْأَلَ عُمَرَ عَنِ الْمَرْأَتَيْنِ مِنْ أَزْوَاجِ النَّبِيِّ صلى الله عليه وسلم اللَّتَيْنِ قَالَ اللَّهُ تَعَالَى ‏{‏إِنْ تَتُوبَا إِلَى اللَّهِ فَقَدْ صَغَتْ قُلُوبُكُمَا‏}‏ حَتَّى حَجَّ عُمَرُ وَحَجَجْتُ مَعَهُ فَلَمَّا كُنَّا بِبَعْضِ الطَّرِيقِ عَدَلَ عُمَرُ وَعَدَلْتُ مَعَهُ بِالإِدَاوَةِ فَتَبَرَّزَ ثُمَّ أَتَانِي فَسَكَبْتُ عَلَى يَدَيْهِ فَتَوَضَّأَ فَقُلْتُ يَا أَمِيرَ الْمُؤْمِنِينَ مَنِ الْمَرْأَتَانِ مِنْ أَزْوَاجِ النَّبِيِّ صلى الله عليه وسلم اللَّتَانِ قَالَ اللَّهُ عَزَّ وَجَلَّ لَهُمَا ‏{‏ إِنْ تَتُوبَا إِلَى اللَّهِ فَقَدْ صَغَتْ قُلُوبُكُمَا‏}‏ قَالَ عُمَرُ وَاعَجَبًا لَكَ يَا ابْنَ عَبَّاسٍ - قَالَ الزُّهْرِيُّ كَرِهَ وَاللَّهِ مَا سَأَلَهُ عَنْهُ وَلَمْ يَكْتُمْهُ - قَالَ هِيَ حَفْصَةُ وَعَائِشَةُ ‏.‏ ثُمَّ أَخَذَ يَسُوقُ الْحَدِيثَ قَالَ كُنَّا مَعْشَرَ قُرَيْشٍ قَوْمًا نَغْلِبُ النِّسَاءَ فَلَمَّا قَدِمْنَا الْمَدِينَةَ وَجَدْنَا قَوْمًا تَغْلِبُهُمْ نِسَاؤُهُمْ فَطَفِقَ نِسَاؤُنَا يَتَعَلَّمْنَ مِنْ نِسَائِهِمْ - قَالَ - وَكَانَ مَنْزِلِي فِي بَنِي أُمَيَّةَ بْنِ زَيْدٍ بِالْعَوَالِي فَتَغَضَّبْتُ يَوْمًا عَلَى امْرَأَتِي فَإِذَا هِيَ تُرَاجِعُنِي فَأَنْكَرْتُ أَنْ تُرَاجِعَنِي ‏.‏ فَقَالَتْ مَا تُنْكِرُ أَنْ أُرَاجِعَكَ فَوَاللَّهِ إِنَّ أَزْوَاجَ النَّبِيِّ صلى الله عليه وسلم لَيُرَاجِعْنَهُ وَتَهْجُرُهُ إِحْدَاهُنَّ الْيَوْمَ إِلَى اللَّيْلِ ‏.‏ فَانْطَلَقْتُ فَدَخَلْتُ عَلَى حَفْصَةَ فَقُلْتُ أَتُرَاجِعِينَ رَسُولَ اللَّهِ صلى الله عليه وسلم فَقَالَتْ نَعَمْ ‏.‏ فَقُلْتُ أَتَهْجُرُهُ إِحْدَاكُنَّ الْيَوْمَ إِلَى اللَّيْلِ قَالَتْ نَعَمْ ‏.‏ قُلْتُ قَدْ خَابَ مَنْ فَعَلَ ذَلِكَ مِنْكُنَّ وَخَسِرَ أَفَتَأْمَنُ إِحْدَاكُنَّ أَنْ يَغْضَبَ اللَّهُ عَلَيْهَا لِغَضَبِ رَسُولِهِ صلى الله عليه وسلم فَإِذَا هِيَ قَدْ هَلَكَتْ لاَ تُرَاجِعِي رَسُولَ اللَّهِ صلى الله عليه وسلم وَلاَ تَسْأَلِيهِ شَيْئًا وَسَلِينِي مَا بَدَا لَكِ وَلاَ يَغُرَّنَّكِ أَنْ كَانَتْ جَارَتُكِ هِيَ أَوْسَمَ وَأَحَبَّ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم مِنْكِ - يُرِيدُ عَائِشَةَ - قَالَ وَكَانَ لِي جَارٌ مِنَ الأَنْصَارِ فَكُنَّا نَتَنَاوَبُ النُّزُولَ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَيَنْزِلُ يَوْمًا وَأَنْزِلُ يَوْمًا فَيَأْتِينِي بِخَبَرِ الْوَحْىِ وَغَيْرِهِ وَآتِيهِ بِمِثْلِ ذَلِكَ وَكُنَّا نَتَحَدَّثُ أَنَّ غَسَّانَ تُنْعِلُ الْخَيْلَ لِتَغْزُوَنَا فَنَزَلَ صَاحِبِي ثُمَّ أَتَانِي عِشَاءً فَضَرَبَ بَابِي ثُمَّ نَادَانِي فَخَرَجْتُ إِلَيْهِ فَقَالَ حَدَثَ أَمْرٌ عَظِيمٌ ‏.‏ قُلْتُ مَاذَا أَجَاءَتْ غَسَّانُ قَالَ لاَ بَلْ أَعْظَمُ مِنْ ذَلِكَ وَأَطْوَلُ طَلَّقَ النَّبِيُّ صلى الله عليه وسلم نِسَاءَهُ ‏.‏ فَقُلْتُ قَدْ خَابَتْ حَفْصَةُ وَخَسِرَتْ قَدْ كُنْتُ أَظُنُّ هَذَا كَائِنًا حَتَّى إِذَا صَلَّيْتُ الصُّبْحَ شَدَدْتُ عَلَىَّ ثِيَابِي ثُمَّ نَزَلْتُ فَدَخَلْتُ عَلَى حَفْصَةَ وَهْىَ تَبْكِي فَقُلْتُ أَطَلَّقَكُنَّ رَسُولُ اللَّهِ صلى الله عليه وسلم فَقَالَتْ لاَ أَدْرِي هَا هُوَ ذَا مُعْتَزِلٌ فِي هَذِهِ الْمَشْرُبَةِ ‏.‏ فَأَتَيْتُ غُلاَمًا لَهُ أَسْوَدَ فَقُلْتُ اسْتَأْذِنْ لِعُمَرَ ‏.‏ فَدَخَلَ ثُمَّ خَرَجَ إِلَىَّ فَقَالَ قَدْ ذَكَرْتُكَ لَهُ فَصَمَتَ فَانْطَلَقْتُ حَتَّى انْتَهَيْتُ إِلَى الْمِنْبَرِ فَجَلَسْتُ فَإِذَا عِنْدَهُ رَهْطٌ جُلُوسٌ يَبْكِي بَعْضُهُمْ فَجَلَسْتُ قَلِيلاً ثُمَّ غَلَبَنِي مَا أَجِدُ ثُمَّ أَتَيْتُ الْغُلاَمَ فَقُلْتُ اسْتَأْذِنْ لِعُمَرَ ‏.‏ فَدَخَلَ ثُمَّ خَرَجَ إِلَىَّ ‏.‏ فَقَالَ قَدْ ذَكَرْتُكَ لَهُ فَصَمَتَ ‏.‏ فَوَلَّيْتُ مُدْبِرًا فَإِذَا الْغُلاَمُ يَدْعُونِي فَقَالَ ادْخُلْ فَقَدْ أَذِنَ لَكَ فَدَخَلْتُ فَسَلَّمْتُ عَلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَإِذَا هُوَ مُتَّكِئٌ عَلَى رَمْلِ حَصِيرٍ قَدْ أَثَّرَ فِي جَنْبِهِ فَقُلْتُ أَطَلَّقْتَ يَا رَسُولَ اللَّهِ نِسَاءَكَ فَرَفَعَ رَأْسَهُ إِلَىَّ وَقَالَ ‏\"‏ لاَ ‏\"‏ ‏.‏ فَقُلْتُ اللَّهُ أَكْبَرُ لَوْ رَأَيْتَنَا يَا رَسُولَ اللَّهِ وَكُنَّا مَعْشَرَ قُرَيْشٍ قَوْمًا نَغْلِبُ النِّسَاءَ فَلَمَّا قَدِمْنَا الْمَدِينَةَ وَجَدْنَا قَوْمًا تَغْلِبُهُمْ نِسَاؤُهُمْ فَطَفِقَ نِسَاؤُنَا يَتَعَلَّمْنَ مِنْ نِسَائِهِمْ فَتَغَضَّبْتُ عَلَى امْرَأَتِي يَوْمًا فَإِذَا هِيَ تُرَاجِعُنِي فَأَنْكَرْتُ أَنْ تُرَاجِعَنِي ‏.‏ فَقَالَتْ مَا تُنْكِرُ أَنْ أُرَاجِعَكَ فَوَاللَّهِ إِنَّ أَزْوَاجَ النَّبِيِّ صلى الله عليه وسلم لَيُرَاجِعْنَهُ وَتَهْجُرُهُ إِحْدَاهُنَّ الْيَوْمَ إِلَى اللَّيْلِ ‏.‏ فَقُلْتُ قَدْ خَابَ مَنْ فَعَلَ ذَلِكَ مِنْهُنَّ وَخَسِرَ أَفَتَأْمَنُ إِحْدَاهُنَّ أَنْ يَغْضَبَ اللَّهُ عَلَيْهَا لِغَضَبِ رَسُولِهِ صلى الله عليه وسلم فَإِذَا هِيَ قَدْ هَلَكَتْ فَتَبَسَّمَ رَسُولُ اللَّهِ صلى الله عليه وسلم فَقُلْتُ يَا رَسُولَ اللَّهِ قَدْ دَخَلْتُ عَلَى حَفْصَةَ فَقُلْتُ لاَ يَغُرَّنَّكِ أَنْ كَانَتْ جَارَتُكِ هِيَ أَوْسَمُ مِنْكِ وَأَحَبُّ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم مِنْكِ ‏.‏ فَتَبَسَّمَ أُخْرَى فَقُلْتُ أَسْتَأْنِسُ يَا رَسُولَ اللَّهِ ‏.‏ قَالَ ‏\"‏ نَعَمْ ‏\"‏ ‏.‏ فَجَلَسْتُ فَرَفَعْتُ رَأْسِي فِي الْبَيْتِ فَوَاللَّهِ مَا رَأَيْتُ فِيهِ شَيْئًا يَرُدُّ الْبَصَرَ إِلاَّ أُهُبًا ثَلاَثَةً فَقُلْتُ ادْعُ اللَّهَ يَا رَسُولَ اللَّهِ أَنْ يُوَسِّعَ عَلَى أُمَّتِكَ فَقَدْ وَسَّعَ عَلَى فَارِسَ وَالرُّومِ وَهُمْ لاَ يَعْبُدُونَ اللَّهَ فَاسْتَوَى جَالِسًا ثُمَّ قَالَ ‏\"‏ أَفِي شَكٍّ أَنْتَ يَا ابْنَ الْخَطَّابِ أُولَئِكَ قَوْمٌ عُجِّلَتْ لَهُمْ طَيِّبَاتُهُمْ فِي الْحَيَاةِ الدُّنْيَا ‏\"‏ ‏.‏ فَقُلْتُ اسْتَغْفِرْ لِي يَا رَسُولَ اللَّهِ ‏.‏ وَكَانَ أَقْسَمَ أَنْ لاَ يَدْخُلَ عَلَيْهِنَّ شَهْرًا مِنْ شِدَّةِ مَوْجِدَتِهِ عَلَيْهِنَّ ‏.‏ حَتَّى عَاتَبَهُ اللَّهُ عَزَّ وَجَلَّ ‏.‏ قَالَ الزُّهْرِيُّ فَأَخْبَرَنِي عُرْوَةُ، عَنْ عَائِشَةَ، قَالَتْ لَمَّا مَضَى تِسْعٌ وَعِشْرُونَ لَيْلَةً دَخَلَ عَلَىَّ رَسُولُ اللَّهِ صلى الله عليه وسلم بَدَأَ بِي فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّكَ أَقْسَمْتَ أَنْ لاَ تَدْخُلَ عَلَيْنَا شَهْرًا وَإِنَّكَ دَخَلْتَ مِنْ تِسْعٍ وَعِشْرِينَ أَعُدُّهُنَّ ‏.‏ فَقَالَ ‏\"‏ إِنَّ الشَّهْرَ تِسْعٌ وَعِشْرُونَ - ثُمَّ قَالَ - يَا عَائِشَةُ إِنِّي ذَاكِرٌ لَكِ أَمْرًا فَلاَ عَلَيْكِ أَنْ لاَ تَعْجَلِي فِيهِ حَتَّى تَسْتَأْمِرِي أَبَوَيْكِ ‏\"‏ ‏.‏ ثُمَّ قَرَأَ عَلَىَّ الآيَةَ ‏{‏ يَا أَيُّهَا النَّبِيُّ قُلْ لأَزْوَاجِكَ‏}‏ حَتَّى بَلَغَ ‏{‏ أَجْرًا عَظِيمًا‏}‏ قَالَتْ عَائِشَةُ قَدْ عَلِمَ وَاللَّهِ أَنَّ أَبَوَىَّ لَمْ يَكُونَا لِيَأْمُرَانِي بِفِرَاقِهِ قَالَتْ فَقُلْتُ أَوَفِي هَذَا أَسْتَأْمِرُ أَبَوَىَّ فَإِنِّي أُرِيدُ اللَّهَ وَرَسُولَهُ وَالدَّارَ الآخِرَةَ ‏.‏ قَالَ مَعْمَرٌ فَأَخْبَرَنِي أَيُّوبُ أَنَّ عَائِشَةَ قَالَتْ لاَ تُخْبِرْ نِسَاءَكَ أَنِّي اخْتَرْتُكَ فَقَالَ لَهَا النَّبِيُّ صلى الله عليه وسلم ‏\"‏ إِنَّ اللَّهَ أَرْسَلَنِي مُبَلِّغًا وَلَمْ يُرْسِلْنِي مُتَعَنِّتًا ‏\"‏ ‏.‏ قَالَ قَتَادَةُ صَغَتْ قُلُوبُكُمَا مَالَتْ قُلُوبُكُمَا‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3204","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3204","x":"Narrated 'Aishah [may Allah be pleased with her]:\n\n\"When the Messenger of Allah (ﷺ) was ordered to tell his wives to make a choice, he started with me. He said: 'O 'Aishah! I am going to mention something to you, but you should not hasten (to reply) until you have consulted your parents.'\" She said: \"And he knew that my parents would not have ordered me to part from him.'\" She said: \"Then Allah [Most High] revealed: 'O Prophet! Say to your wives: If you desire the life of this world and its glitter then come...' until reaching: '...for the good doers among you an enormous reward (33:28 & 29).' I said: 'For what should I consult my parents? Indeed I want Allah, His Messenger, and the abode of the Hereafter.' The (remaining) wives of the Prophet (ﷺ) did the same as I did.\"","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، حَدَّثَنَا عُثْمَانُ بْنُ عُمَرَ، عَنْ يُونُسَ بْنِ يَزِيدَ، عَنِ الزُّهْرِيِّ، عَنْ أَبِي سَلَمَةَ، عَنْ عَائِشَةَ، رضى الله عنها قَالَتْ لَمَّا أُمِرَ رَسُولُ اللَّهِ صلى الله عليه وسلم بِتَخْيِيرِ أَزْوَاجِهِ بَدَأَ بِي فَقَالَ ‏\"‏ يَا عَائِشَةُ إِنِّي ذَاكِرٌ لَكِ أَمْرًا فَلاَ عَلَيْكِ أَنْ لاَ تَسْتَعْجِلِي حَتَّى تَسْتَأْمِرِي أَبَوَيْكِ ‏\"‏ ‏.‏ قَالَتْ وَقَدْ عَلِمَ أَنَّ أَبَوَاىَ لَمْ يَكُونَا لِيَأْمُرَانِي بِفِرَاقِهِ قَالَتْ ثُمَّ قَالَ ‏\"‏ إِنَّ اللَّهَ تَعَالَى يَقُولُ‏:‏ ‏(‏ يا أَيُّهَا النَّبِيُّ قُلْ لأَزْوَاجِكَ إِنْ كُنْتُنَّ تُرِدْنَ الْحَيَاةَ الدُّنْيَا وَزِينَتَهَا فَتَعَالَيْنَ ‏)‏ حَتَّى بَلَغَ ‏:‏ ‏(‏ للْمُحْسِنَاتِ مِنْكُنَّ أَجْرًا عَظِيمًا ‏)‏ فَقُلْتُ فِي أَىِّ هَذَا أَسْتَأْمِرُ أَبَوَىَّ فَإِنِّي أُرِيدُ اللَّهَ وَرَسُولَهُ وَالدَّارَ الآخِرَةَ وَفَعَلَ أَزْوَاجُ النَّبِيِّ صلى الله عليه وسلم مِثْلَ مَا فَعَلْتُ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏ وَقَدْ رُوِيَ هَذَا أَيْضًا عَنِ الزُّهْرِيِّ عَنْ عُرْوَةَ عَنْ عَائِشَةَ رضى الله عنها ‏.‏","v":[]}],"29":[{"c":"Sahih Bukhari","r":"Hadith 4785","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4785","x":"Narrated `Aisha:\n\n(the wife of the Prophet) Allah's Messenger (ﷺ) came to me when Allah ordered him to give option to his wives. So Allah's Messenger (ﷺ) started with me, saying, \"I am going to mention to you something but you should not hasten (to give your reply) unless you consult your parents.' He knew that my parents would not order me to leave him. Then he said, \"Allah says:-- \"O Prophet! Say to your wives...\" (33.28-29) On that I said to him, \"Then why should I consult my parents? Verily, I seek Allah, His Apostle and the Home of the Hereafter.\"","ar":"حَدَّثَنَا أَبُو الْيَمَانِ، أَخْبَرَنَا شُعَيْبٌ، عَنِ الزُّهْرِيِّ، قَالَ أَخْبَرَنِي أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ، أَنَّ عَائِشَةَ، رضى الله عنها زَوْجَ النَّبِيِّ صلى الله عليه وسلم أَخْبَرَتْهُ أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم جَاءَهَا حِينَ أَمَرَ اللَّهُ أَنْ يُخَيِّرَ أَزْوَاجَهُ، فَبَدَأَ بِي رَسُولُ اللَّهِ صلى الله عليه وسلم فَقَالَ ‏\"‏ إِنِّي ذَاكِرٌ لَكِ أَمْرًا فَلاَ عَلَيْكِ أَنْ تَسْتَعْجِلِي حَتَّى تَسْتَأْمِرِي أَبَوَيْكِ ‏\"‏، وَقَدْ عَلِمَ أَنَّ أَبَوَىَّ لَمْ يَكُونَا يَأْمُرَانِي بِفِرَاقِهِ، قَالَتْ ثُمَّ قَالَ ‏\"‏ إِنَّ اللَّهَ قَالَ ‏{‏يَا أَيُّهَا النَّبِيُّ قُلْ لأَزْوَاجِكَ‏}‏ ‏\"‏‏.‏ إِلَى تَمَامِ الآيَتَيْنِ فَقُلْتُ لَهُ فَفِي أَىِّ هَذَا أَسْتَأْمِرُ أَبَوَىَّ فَإِنِّي أُرِيدُ اللَّهَ وَرَسُولَهُ وَالدَّارَ الآخِرَةَ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4786","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4786","x":"Narrated `Aisha:\n\n(the wife of the Prophet) when Allah's Messenger (ﷺ) was ordered to give option to his wives, he started with me, saying, \"I am going to mention to you something, but you shall not hasten (to give your reply) unless you consult your parents.\" The Prophet (ﷺ) knew that my parents would not order me to leave him. Then he said, \"Allah says: 'O Prophet (Muhammad)! Say to your wives: If you desire the life of this world and its glitter........a great reward.\" (33.28-29) I said, \"Then why I consult my parents? Verily, I seek Allah, His Apostle and the Home of the Hereafter.\" Then all the other wives of the Prophet (ﷺ) did the same as I did.","ar":"وَقَالَ اللَّيْثُ حَدَّثَنِي يُونُسُ، عَنِ ابْنِ شِهَابٍ، قَالَ أَخْبَرَنِي أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ، أَنَّ عَائِشَةَ، زَوْجَ النَّبِيِّ صلى الله عليه وسلم قَالَتْ لَمَّا أُمِرَ رَسُولُ اللَّهِ صلى الله عليه وسلم بِتَخْيِيرِ أَزْوَاجِهِ بَدَأَ بِي فَقَالَ ‏\"‏ إِنِّي ذَاكِرٌ لَكِ أَمْرًا فَلاَ عَلَيْكِ أَنْ لاَ تَعْجَلِي حَتَّى تَسْتَأْمِرِي أَبَوَيْكِ ‏\"‏‏.‏ قَالَتْ وَقَدْ عَلِمَ أَنَّ أَبَوَىَّ لَمْ يَكُونَا يَأْمُرَانِي بِفِرَاقِهِ، قَالَتْ ثُمَّ قَالَ ‏\"‏ إِنَّ اللَّهَ جَلَّ ثَنَاؤُهُ قَالَ ‏{‏يَا أَيُّهَا النَّبِيُّ قُلْ لأَزْوَاجِكَ إِنْ كُنْتُنَّ تُرِدْنَ الْحَيَاةَ الدُّنْيَا وَزِينَتَهَا‏}‏ إِلَى ‏{‏أَجْرًا عَظِيمًا‏}‏ ‏\"‏‏.‏ قَالَتْ فَقُلْتُ فَفِي أَىِّ هَذَا أَسْتَأْمِرُ أَبَوَىَّ فَإِنِّي أُرِيدُ اللَّهَ وَرَسُولَهُ وَالدَّارَ الآخِرَةَ، قَالَتْ ثُمَّ فَعَلَ أَزْوَاجُ النَّبِيِّ صلى الله عليه وسلم مِثْلَ مَا فَعَلْتُ‏.‏ تَابَعَهُ مُوسَى بْنُ أَعْيَنَ عَنْ مَعْمَرٍ عَنِ الزُّهْرِيِّ قَالَ أَخْبَرَنِي أَبُو سَلَمَةَ‏.‏ وَقَالَ عَبْدُ الرَّزَّاقِ وَأَبُو سُفْيَانَ الْمَعْمَرِيُّ عَنْ مَعْمَرٍ عَنِ الزُّهْرِيِّ عَنْ عُرْوَةَ عَنْ عَائِشَةَ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3204","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3204","x":"Narrated 'Aishah [may Allah be pleased with her]:\n\n\"When the Messenger of Allah (ﷺ) was ordered to tell his wives to make a choice, he started with me. He said: 'O 'Aishah! I am going to mention something to you, but you should not hasten (to reply) until you have consulted your parents.'\" She said: \"And he knew that my parents would not have ordered me to part from him.'\" She said: \"Then Allah [Most High] revealed: 'O Prophet! Say to your wives: If you desire the life of this world and its glitter then come...' until reaching: '...for the good doers among you an enormous reward (33:28 & 29).' I said: 'For what should I consult my parents? Indeed I want Allah, His Messenger, and the abode of the Hereafter.' The (remaining) wives of the Prophet (ﷺ) did the same as I did.\"","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، حَدَّثَنَا عُثْمَانُ بْنُ عُمَرَ، عَنْ يُونُسَ بْنِ يَزِيدَ، عَنِ الزُّهْرِيِّ، عَنْ أَبِي سَلَمَةَ، عَنْ عَائِشَةَ، رضى الله عنها قَالَتْ لَمَّا أُمِرَ رَسُولُ اللَّهِ صلى الله عليه وسلم بِتَخْيِيرِ أَزْوَاجِهِ بَدَأَ بِي فَقَالَ ‏\"‏ يَا عَائِشَةُ إِنِّي ذَاكِرٌ لَكِ أَمْرًا فَلاَ عَلَيْكِ أَنْ لاَ تَسْتَعْجِلِي حَتَّى تَسْتَأْمِرِي أَبَوَيْكِ ‏\"‏ ‏.‏ قَالَتْ وَقَدْ عَلِمَ أَنَّ أَبَوَاىَ لَمْ يَكُونَا لِيَأْمُرَانِي بِفِرَاقِهِ قَالَتْ ثُمَّ قَالَ ‏\"‏ إِنَّ اللَّهَ تَعَالَى يَقُولُ‏:‏ ‏(‏ يا أَيُّهَا النَّبِيُّ قُلْ لأَزْوَاجِكَ إِنْ كُنْتُنَّ تُرِدْنَ الْحَيَاةَ الدُّنْيَا وَزِينَتَهَا فَتَعَالَيْنَ ‏)‏ حَتَّى بَلَغَ ‏:‏ ‏(‏ للْمُحْسِنَاتِ مِنْكُنَّ أَجْرًا عَظِيمًا ‏)‏ فَقُلْتُ فِي أَىِّ هَذَا أَسْتَأْمِرُ أَبَوَىَّ فَإِنِّي أُرِيدُ اللَّهَ وَرَسُولَهُ وَالدَّارَ الآخِرَةَ وَفَعَلَ أَزْوَاجُ النَّبِيِّ صلى الله عليه وسلم مِثْلَ مَا فَعَلْتُ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏ وَقَدْ رُوِيَ هَذَا أَيْضًا عَنِ الزُّهْرِيِّ عَنْ عُرْوَةَ عَنْ عَائِشَةَ رضى الله عنها ‏.‏","v":[]}],"33":[{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3205","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3205","x":"Narrated 'Umar bin Abi Salamah - the step-son of the Prophet (ﷺ):\n\n\"When these Ayat were revealed to the Prophet (ﷺ): 'Allah only wishes to remove the Rijs from you, O members of the family, and to purify you with a thorough purification (33:33)' in the home of Umm Salamah, he called for Fatimah, Hasan, Husain, and wrapped him in the cloak, and 'Ali was behind him, so he wrapped him in the cloak, then he said: 'O Allah! These are the people of my house, so remove the Rijs from them, and purify them with a thorough purification.' So Umm Salamah said: 'And I, Prophet of Allah?' He said: 'You are in your place (meaning you are already a member of my household), and you are goodness.'\"","ar":"حَدَّثَنَا قُتَيْبَةُ، حَدَّثَنَا مُحَمَّدُ بْنُ سُلَيْمَانَ بْنِ الأَصْبَهَانِيِّ، عَنْ يَحْيَى بْنِ عُبَيْدٍ، عَنْ عَطَاءِ بْنِ أَبِي رَبَاحٍ، عَنْ عُمَرَ بْنِ أَبِي سَلَمَةَ، رَبِيبِ النَّبِيِّ صلى الله عليه وسلم قَالَ لَمَّا نَزَلَتْ هَذِهِ الآيَةُ عَلَى النَّبِيِّ صلى الله عليه وسلمَّ ‏:‏ ‏(‏ إنمَا يُرِيدُ اللَّهُ لِيُذْهِبَ عَنْكُمُ الرِّجْسَ أَهْلَ الْبَيْتِ وَيُطَهِّرَكُمْ تَطْهِيرًا ‏)‏ فِي بَيْتِ أُمِّ سَلَمَةَ فَدَعَا فَاطِمَةَ وَحَسَنًا وَحُسَيْنًا فَجَلَّلَهُمْ بِكِسَاءٍ وَعَلِيٌّ خَلْفَ ظَهْرِهِ فَجَلَّلَهُمْ بِكِسَاءٍ ثُمَّ قَالَ ‏\"‏ اللَّهُمَّ هَؤُلاَءِ أَهْلُ بَيْتِي فَأَذْهِبْ عَنْهُمُ الرِّجْسَ وَطَهِّرْهُمْ تَطْهِيرًا ‏\"‏ ‏.‏ قَالَتْ أُمُّ سَلَمَةَ وَأَنَا مَعَهُمْ يَا نَبِيَّ اللَّهِ قَالَ ‏\"‏ أَنْتِ عَلَى مَكَانِكِ وَأَنْتِ عَلَى خَيْرٍ ‏\"‏ ‏.‏ قَالَ هَذَا حَدِيثٌ غَرِيبٌ مِنْ هَذَا الْوَجْهِ مِنْ حَدِيثِ عَطَاءٍ عَنْ عُمَرَ بْنِ أَبِي سَلَمَةَ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3206","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3206","x":"Narrated Anas bin Malik:\n\n\"For six months, the Messenger of Allah (ﷺ) would pass by the door of Fatimah when going to the Fajr prayer saying: 'As-Salat O People of the house! Allah only wishes to remove the Rijs from you, O members of the family, and to purify you with thorough purification (33:33).'\"","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، حَدَّثَنَا عَفَّانُ بْنُ مُسْلِمٍ، حَدَّثَنَا حَمَّادُ بْنُ سَلَمَةَ، أَخْبَرَنَا عَلِيُّ بْنُ زَيْدٍ، عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم كَانَ يَمُرُّ بِبَابِ فَاطِمَةَ سِتَّةَ أَشْهُرٍ إِذَا خَرَجَ إِلَى صَلاَةِ الْفَجْرِ يَقُولُ ‏\"‏ الصَّلاَةَ يَا أَهْلَ الْبَيْتِ ‏:‏ ‏(‏ إنَّمَا يُرِيدُ اللَّهُ لِيُذْهِبَ عَنْكُمُ الرِّجْسَ أَهْلَ الْبَيْتِ وَيُطَهِّرَكُمْ تَطْهِيرًا ‏)‏ ‏\"‏ ‏.‏ قَالَ هَذَا حَدِيثٌ حَسَنٌ غَرِيبٌ مِنْ هَذَا الْوَجْهِ إِنَّمَا نَعْرِفُهُ مِنْ حَدِيثِ حَمَّادِ بْنِ سَلَمَةَ ‏.‏ قَالَ وَفِي الْبَابِ عَنْ أَبِي الْحَمْرَاءِ وَمَعْقِلِ بْنِ يَسَارٍ وَأُمِّ سَلَمَةَ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 6, Book 46, Hadith 3787","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-6/Book-46/Hadith-3787","x":"Narrated 'Umar bin Abi Salamah - the step-son of the Prophet (ﷺ):\n\n\"When these Ayat were revealed to the Prophet (ﷺ): 'Allah only wishes to remove the Rijs from you, O members of the family, and to purify you with a thorough purification...' (33:33) in the home of Umm Salamah, he called for Fatimah, Hasan, Husain, and wrapped them in a cloak, and 'Ali was behind him, so he wrapped him in the cloak, then he said: 'O Allah! These are the people of my house, so remove the Rijs from them, and purify them with a thorough purification.' So Umm Salamah said: 'And am I with them O Messenger of Allah?' He said: 'You are in your place, and you are more virtuous to me.'\"","ar":"حَدَّثَنَا قُتَيْبَةُ بْنُ سَعِيدٍ، قَالَ حَدَّثَنَا مُحَمَّدُ بْنُ سُلَيْمَانَ الأَصْبَهَانِيُّ، عَنْ يَحْيَى بْنِ عُبَيْدٍ، عَنْ عَطَاءِ بْنِ أَبِي رَبَاحٍ، عَنْ عُمَرَ بْنِ أَبِي سَلَمَةَ، رَبِيبِ النَّبِيِّ صلى الله عليه وسلم قَالَ نَزَلَتْ هَذِهِ الآيَةُ عَلَى النَّبِيِّ صلى الله عليه وسلمَّ ‏:‏ ‏(‏ إنمَا يُرِيدُ اللَّهُ لِيُذْهِبَ عَنْكُمُ الرِّجْسَ أَهْلَ الْبَيْتِ وَيُطَهِّرَكُمْ تَطْهِيرًا ‏)‏ فِي بَيْتِ أُمِّ سَلَمَةَ فَدَعَا النَّبِيُّ صلى الله عليه وسلم فَاطِمَةَ وَحَسَنًا وَحُسَيْنًا فَجَلَّلَهُمْ بِكِسَاءٍ وَعَلِيٌّ خَلْفَ ظَهْرِهِ فَجَلَّلَهُ بِكِسَاءٍ ثُمَّ قَالَ ‏\"‏ اللَّهُمَّ هَؤُلاَءِ أَهْلُ بَيْتِي فَأَذْهِبْ عَنْهُمُ الرِّجْسَ وَطَهِّرْهُمْ تَطْهِيرًا ‏\"‏ ‏.‏ قَالَتْ أُمُّ سَلَمَةَ وَأَنَا مَعَهُمْ يَا نَبِيَّ اللَّهِ قَالَ ‏\"‏ أَنْتِ عَلَى مَكَانِكِ وَأَنْتِ إِلَيَّ خَيْرٍ ‏\"‏ ‏. وَفِي الْبَابِ عَنْ أُمِّ سَلَمَةَ وَمَعْقِلِ بْنِ يَسَارٍ وَأَبِي الْحَمْرَاءِ وَأَنَسٍ بْنِ مَالِكٍ ‏.‏ وَهَذَا حَدِيثٌ غَرِيبٌ مِنْ هَذَا الْوَجْهِ ‏.‏","v":[]}],"35":[{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3022","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3022","x":"Narrated Mujahid:\n\nfrom Umm Salamah that she said: \"The men fight and the women do not fight, and we only get half the inheritance.' So Allah, Blessed and Most High, revealed: 'And wish not for things in which Allah has made some of you excell over others... (4:32)' Mujahid said: \"And the following was revealed about that: 'Verily the Muslim men and the Muslim women... (33:35). And Umm Salamah was the first camel-borne woman to arrive in Al-Madinah as an emigrant.","ar":"حَدَّثَنَا ابْنُ أَبِي عُمَرَ، حَدَّثَنَا سُفْيَانُ، عَنِ ابْنِ أَبِي نَجِيحٍ، عَنْ مُجَاهِدٍ، عَنْ أُمِّ سَلَمَةَ، أَنَّهَا قَالَتْ يَغْزُو الرِّجَالُ وَلاَ يَغْزُو النِّسَاءُ وَإِنَّمَا لَنَا نِصْفُ الْمِيرَاثِ ‏.‏ فَأَنْزَلَ اللَّهُ ‏:‏ ‏(‏وَلاَ تَتَمَنَّوْا مَا فَضَّلَ اللَّهُ بِهِ بَعْضَكُمْ عَلَى بَعْضٍ ‏)‏ ‏.‏ قَالَ مُجَاهِدٌ فَأُنْزِلَ فِيهَا ‏:‏ ‏(‏ إِنَّ الْمُسْلِمِينَ وَالْمُسْلِمَاتِ ‏)‏ وَكَانَتْ أُمُّ سَلَمَةَ أَوَّلَ ظَعِينَةٍ قَدِمَتِ الْمَدِينَةَ مُهَاجِرَةً ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ مُرْسَلٌ ‏.‏ وَرَوَاهُ بَعْضُهُمْ عَنِ ابْنِ أَبِي نَجِيحٍ عَنْ مُجَاهِدٍ مُرْسَلٌ أَنَّ أُمَّ سَلَمَةَ قَالَتْ كَذَا وَكَذَا ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3211","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3211","x":"Narrated Umm 'Umarah Al-Ansariyyah:\n\nthat she came to the Prophet (ﷺ) and said: \"I do not see but that everything is for the men, and I do not see anything being mentioned for the women.\" So this Ayah was revealed: 'Indeed the Muslim men and the Muslim women, the believing men and the believing women... (33:35)'","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، حَدَّثَنَا مُحَمَّدُ بْنُ كَثِيرٍ، حَدَّثَنَا سُلَيْمَانُ بْنُ كَثِيرٍ، عَنْ حُسَيْنٍ، عَنْ عِكْرِمَةَ، عَنْ أُمِّ عُمَارَةَ الأَنْصَارِيَّةِ، أَنَّهَا أَتَتِ النَّبِيَّ صلى الله عليه وسلم فَقَالَتْ مَا أَرَى كُلَّ شَيْءٍ إِلاَّ لِلرِّجَالِ وَمَا أَرَى النِّسَاءَ يُذْكَرْنَ بِشَيْءٍ فَنَزَلَتْ هَذِهِ الآيَةُ ‏:‏ ‏(‏إن الْمُسْلِمِينَ وَالْمُسْلِمَاتِ وَالْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ ‏)‏ الآيَةَ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ غَرِيبٌ وَإِنَّمَا يُعْرَفُ هَذَا الْحَدِيثُ مِنْ هَذَا الْوَجْهِ ‏.‏","v":[]}],"37":[{"c":"Sahih Bukhari","r":"Hadith 4787","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4787","x":"Narrated Anas bin Malik:\n\nThe Verse: 'But you did hide in your mind that which Allah was about to make manifest.' (33.37) was revealed concerning Zainab bint Jahsh and Zaid bin Haritha.","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ عَبْدِ الرَّحِيمِ، حَدَّثَنَا مُعَلَّى بْنُ مَنْصُورٍ، عَنْ حَمَّادِ بْنِ زَيْدٍ، حَدَّثَنَا ثَابِتٌ، عَنْ أَنَسِ بْنِ مَالِكٍ ـ رضى الله عنه ـ أَنَّ هَذِهِ، الآيَةَ ‏{‏وَتُخْفِي فِي نَفْسِكَ مَا اللَّهُ مُبْدِيهِ‏}‏ نَزَلَتْ فِي شَأْنِ زَيْنَبَ ابْنَةِ جَحْشٍ وَزَيْدِ بْنِ حَارِثَةَ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 7420","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-7420","x":"Narrated Anas:\n\nZaid bin Haritha came to the Prophet (ﷺ) complaining about his wife. The Prophet (ﷺ) kept on saying (to him), \"Be afraid of Allah and keep your wife.\" Aisha said, \"If Allah's Messenger (ﷺ) were to conceal anything (of the Qur'an he would have concealed this Verse.\" Zainab used to boast before the wives of the Prophet (ﷺ) and used to say, \"You were given in marriage by your families, while I was married (to the Prophet) by Allah from over seven Heavens.\" And Thabit recited, \"The Verse:-- 'But (O Muhammad) you did hide in your heart that which Allah was about to make manifest, you did fear the people,' (33.37) was revealed in connection with Zainab and Zaid bin Haritha.\"","ar":"حَدَّثَنَا أَحْمَدُ، حَدَّثَنَا مُحَمَّدُ بْنُ أَبِي بَكْرٍ الْمُقَدَّمِيُّ، حَدَّثَنَا حَمَّادُ بْنُ زَيْدٍ، عَنْ ثَابِتٍ، عَنْ أَنَسٍ، قَالَ جَاءَ زَيْدُ بْنُ حَارِثَةَ يَشْكُو فَجَعَلَ النَّبِيُّ صلى الله عليه وسلم يَقُولُ ‏\"‏ اتَّقِ اللَّهَ، وَأَمْسِكْ عَلَيْكَ زَوْجَكَ ‏\"‏‏.‏ قَالَتْ عَائِشَةُ لَوْ كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم كَاتِمًا شَيْئًا لَكَتَمَ هَذِهِ‏.‏ قَالَ فَكَانَتْ زَيْنَبُ تَفْخَرُ عَلَى أَزْوَاجِ النَّبِيِّ صلى الله عليه وسلم تَقُولُ زَوَّجَكُنَّ أَهَالِيكُنَّ، وَزَوَّجَنِي اللَّهُ تَعَالَى مِنْ فَوْقِ سَبْعِ سَمَوَاتٍ‏.‏ وَعَنْ ثَابِتٍ ‏{‏وَتُخْفِي فِي نَفْسِكَ مَا اللَّهُ مُبْدِيهِ وَتَخْشَى النَّاسَ‏}‏ نَزَلَتْ فِي شَأْنِ زَيْنَبَ وَزَيْدِ بْنِ حَارِثَةَ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3207","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3207","x":"Narrated 'Aishah [may Allah be pleased with her]:\n\n\"If the Messenger of Allah (ﷺ) was to have concealed anything that was revealed to him, then he would have concealed these Ayat: 'When you said to him on whom Allah has bestowed grace (meaning by Islam); and you have done a favor (meaning that he was a slave and you freed him) \"Keep your wife to yourself, and have Taqwa of Allah.\" But you did hide in yourself that which Allah will make manifest, you did fear the people whereas Allah had better right that you should fear Him' up to His saying: 'And Allah's command must be fulfilled (33:37).' They said: 'He married his wife's son, so Allah revealed: 'Muhammad is not the father of any of your men, but he is the Messenger of Allah and the Last of the Prophets (33:40).' The Messenger of Allah (ﷺ) had taken (adopted) him as a son when he was small, and he remained being called 'Zaid bin Muhammad' until he grew up to adulthood, then Allah revealed: 'Call them by their fathers, then your brothers in religion and your Mawali (33:5). (Say) So-and-so, the Mawla of so-and-so, and; So-and-so, the brother of so-and-so. 'That is more just with Allah' meaning that doing that is more just to Allah.\"","ar":"حَدَّثَنَا عَلِيُّ بْنُ حُجْرٍ، أَخْبَرَنَا دَاوُدُ بْنُ الزِّبْرِقَانِ، عَنْ دَاوُدَ بْنِ أَبِي هِنْدٍ، عَنِ الشَّعْبِيِّ، عَنْ عَائِشَةَ، رضى الله عنها قَالَتْ لَوْ كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم كَاتِمًا شَيْئًا مِنَ الْوَحْىِ لَكَتَمَ هَذِهِ الآيَةَ ‏:‏ ‏(‏ إِذْ تَقُولُ لِلَّذِي أَنْعَمَ اللَّهُ عَلَيْهِ ‏)‏ يَعْنِي بِالإِسْلاَمِ ‏:‏ ‏(‏ وأَنْعَمْتَ عَلَيْهِ ‏)‏ بِالْعِتْقِ فَأَعْتَقْتَهُ ‏:‏ ‏(‏ أمْسِكْ عَلَيْكَ زَوْجَكَ وَاتَّقِ اللَّهَ وَتُخْفِي فِي نَفْسِكَ مَا اللَّهُ مُبْدِيهِ وَتَخْشَى النَّاسَ وَاللَّهُ أَحَقُّ أَنْ تَخْشَاهُ ‏)‏ إِلَى قَوْلِهِ ‏:‏ ‏(‏وكَانَ أَمْرُ اللَّهِ مَفْعُولاً ‏)‏ وَإِنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم لَمَّا تَزَوَّجَهَا قَالُوا تَزَوَّجَ حَلِيلَةَ ابْنِهِ فَأَنْزَلَ اللَّهُ تَعَالَى ‏:‏ ‏(‏ ما كَانَ مُحَمَّدٌ أَبَا أَحَدٍ مِنْ رِجَالِكُمْ وَلَكِنْ رَسُولَ اللَّهِ وَخَاتَمَ النَّبِيِّينَ ‏)‏ وَكَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم تَبَنَّاهُ وَهُوَ صَغِيرٌ فَلَبِثَ حَتَّى صَارَ رَجُلاً يُقَالُ لَهُ زَيْدُ بْنُ مُحَمَّدٍ فَأَنْزَلَ اللَّهُ ‏:‏ ‏(‏ ادعُوهُمْ لآبَائِهِمْ هُوَ أَقْسَطُ عِنْدَ اللَّهِ فَإِنْ لَمْ تَعْلَمُوا آبَاءَهُمْ فَإِخْوَانُكُمْ فِي الدِّينِ وَمَوَالِيكُمْ ‏)‏ فُلاَنٌ مَوْلَى فُلاَنٍ وَفُلاَنٌ أَخُو فُلاَنٍ ‏(‏هُوَ أَقْسَطُ عِنْدَ اللَّهِ ‏)‏ يَعْنِي أَعْدَلُ عِنْدَ اللَّهِ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ غَرِيبٌ ‏.‏ قَدْ رُوِيَ عَنْ دَاوُدَ بْنِ أَبِي هِنْدٍ، عَنِ الشَّعْبِيِّ، عَنْ مَسْرُوقٍ، عَنْ عَائِشَةَ، قَالَتْ لَوْ كَانَ النَّبِيُّ صلى الله عليه وسلم كَاتِمًا شَيْئًا مِنَ الْوَحْىِ لَكَتَمَ هَذِهِ الآيَةَ ‏:‏ ‏(‏ إِذْ تَقُولُ لِلَّذِي أَنْعَمَ اللَّهُ عَلَيْهِ وَأَنْعَمْتَ عَلَيْهِ ‏)‏ الآيَةَ هَذَا الْحَرْفُ لَمْ يُرْوَ بِطُولِهِ ‏.‏ حَدَّثَنَا بِذَلِكَ عَبْدُ اللَّهِ بْنُ وَضَّاحٍ الْكُوفِيُّ حَدَّثَنَا عَبْدُ اللَّهِ بْنُ إِدْرِيسَ عَنْ دَاوُدَ بْنِ أَبِي هِنْدٍ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3208","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3208","x":"Narrated 'Aishah [may Allah be pleased with her]:\n\n\"If the Prophet (ﷺ) was to have hidden anything from the Revelation, then he would have hidden this Ayah: 'When you said to him on whom Allah has bestowed grace and you have done a favor (33:37).'\"","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ أَبَانَ، حَدَّثَنَا ابْنُ أَبِي عَدِيٍّ، عَنْ دَاوُدَ بْنِ أَبِي هِنْدٍ، عَنِ الشَّعْبِيِّ، عَنْ مَسْرُوقٍ، عَنْ عَائِشَةَ، رضى الله عنها قَالَتْ لَوْ كَانَ النَّبِيُّ صلى الله عليه وسلم كَاتِمًا شَيْئًا مِنَ الْوَحْىِ لَكَتَمَ هَذِهِ الآيَةَِ ‏:‏ ‏(‏ إذْ تَقُولُ لِلَّذِي أَنْعَمَ اللَّهُ عَلَيْهِ وَأَنْعَمْتَ عَلَيْهِ ‏)‏ الآيَةَ ‏.‏ قَالَ هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3212","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3212","x":"Narrated Anas:\n\n\"When this Ayah was revealed: 'But you did hide in yourself that which Allah will make manifest... (33:37)' about Zainab bint Jahsh, Zaid had come to the Prophet (ﷺ) complaining, and he wanted to divorce her, so he consulted with the Prophet (ﷺ). The Prophet (ﷺ) said: 'Keep your wife to yourself, and have Taqwa of Allah (33:37).'\"","ar":"حَدَّثَنَا أَحْمَدُ بْنُ عَبْدَةَ الضَّبِّيُّ، حَدَّثَنَا حَمَّادُ بْنُ زَيْدٍ، عَنْ ثَابِتٍ، عَنْ أَنَسٍ، قَالَ نَزَلَتْ هَذِهِ الآيَةُ ‏:‏ ‏(‏وتُخْفِي فِي نَفْسِكَ مَا اللَّهُ مُبْدِيهِ وَتَخْشَى النَّاسَ ‏)‏ فِي شَأْنِ زَيْنَبَ بِنْتِ جَحْشٍ جَاءَ زَيْدٌ يَشْكُو فَهَمَّ بِطَلاَقِهَا فَاسْتَأْمَرَ النَّبِيَّ صلى الله عليه وسلم فَقَالَ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ أَمْسِكْ عَلَيْكَ زَوْجَكَ وَاتَّقِ اللَّهَ ‏\"‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3213","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3213","x":"Narrated Anas:\n\n\"When this Ayah was revealed about Zainab bint Jahsh: 'So when Zaid had completed his aim with her, We gave her to you in marriage (33:37)' - he said: \"She used to boast to the wives of the Prophet (ﷺ): 'Your families married you (to him) while Allah married me (to him) from above the Seven Heavens.'\"","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، حَدَّثَنَا مُحَمَّدُ بْنُ الْفَضْلِ، حَدَّثَنَا حَمَّادُ بْنُ زَيْدٍ، عَنْ ثَابِتٍ، عَنْ أَنَسٍ، قَالَ نَزَلَتْ هَذِهِ الآيَةُ فِي زَيْنَبَ بِنْتِ جَحْشٍ ‏:‏ ‏(‏فلَمَّا قَضَى زَيْدٌ مِنْهَا وَطَرًا زَوَّجْنَاكَهَا ‏)‏ قَالَ فَكَانَتْ تَفْتَخِرُ عَلَى أَزْوَاجِ النَّبِيِّ صلى الله عليه وسلم تَقُولُ زَوَّجَكُنَّ أَهْلُكُنَّ وَزَوَّجَنِي اللَّهُ مِنْ فَوْقِ سَبْعِ سَمَوَاتٍ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏","v":[]}],"40":[{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3207","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3207","x":"Narrated 'Aishah [may Allah be pleased with her]:\n\n\"If the Messenger of Allah (ﷺ) was to have concealed anything that was revealed to him, then he would have concealed these Ayat: 'When you said to him on whom Allah has bestowed grace (meaning by Islam); and you have done a favor (meaning that he was a slave and you freed him) \"Keep your wife to yourself, and have Taqwa of Allah.\" But you did hide in yourself that which Allah will make manifest, you did fear the people whereas Allah had better right that you should fear Him' up to His saying: 'And Allah's command must be fulfilled (33:37).' They said: 'He married his wife's son, so Allah revealed: 'Muhammad is not the father of any of your men, but he is the Messenger of Allah and the Last of the Prophets (33:40).' The Messenger of Allah (ﷺ) had taken (adopted) him as a son when he was small, and he remained being called 'Zaid bin Muhammad' until he grew up to adulthood, then Allah revealed: 'Call them by their fathers, then your brothers in religion and your Mawali (33:5). (Say) So-and-so, the Mawla of so-and-so, and; So-and-so, the brother of so-and-so. 'That is more just with Allah' meaning that doing that is more just to Allah.\"","ar":"حَدَّثَنَا عَلِيُّ بْنُ حُجْرٍ، أَخْبَرَنَا دَاوُدُ بْنُ الزِّبْرِقَانِ، عَنْ دَاوُدَ بْنِ أَبِي هِنْدٍ، عَنِ الشَّعْبِيِّ، عَنْ عَائِشَةَ، رضى الله عنها قَالَتْ لَوْ كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم كَاتِمًا شَيْئًا مِنَ الْوَحْىِ لَكَتَمَ هَذِهِ الآيَةَ ‏:‏ ‏(‏ إِذْ تَقُولُ لِلَّذِي أَنْعَمَ اللَّهُ عَلَيْهِ ‏)‏ يَعْنِي بِالإِسْلاَمِ ‏:‏ ‏(‏ وأَنْعَمْتَ عَلَيْهِ ‏)‏ بِالْعِتْقِ فَأَعْتَقْتَهُ ‏:‏ ‏(‏ أمْسِكْ عَلَيْكَ زَوْجَكَ وَاتَّقِ اللَّهَ وَتُخْفِي فِي نَفْسِكَ مَا اللَّهُ مُبْدِيهِ وَتَخْشَى النَّاسَ وَاللَّهُ أَحَقُّ أَنْ تَخْشَاهُ ‏)‏ إِلَى قَوْلِهِ ‏:‏ ‏(‏وكَانَ أَمْرُ اللَّهِ مَفْعُولاً ‏)‏ وَإِنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم لَمَّا تَزَوَّجَهَا قَالُوا تَزَوَّجَ حَلِيلَةَ ابْنِهِ فَأَنْزَلَ اللَّهُ تَعَالَى ‏:‏ ‏(‏ ما كَانَ مُحَمَّدٌ أَبَا أَحَدٍ مِنْ رِجَالِكُمْ وَلَكِنْ رَسُولَ اللَّهِ وَخَاتَمَ النَّبِيِّينَ ‏)‏ وَكَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم تَبَنَّاهُ وَهُوَ صَغِيرٌ فَلَبِثَ حَتَّى صَارَ رَجُلاً يُقَالُ لَهُ زَيْدُ بْنُ مُحَمَّدٍ فَأَنْزَلَ اللَّهُ ‏:‏ ‏(‏ ادعُوهُمْ لآبَائِهِمْ هُوَ أَقْسَطُ عِنْدَ اللَّهِ فَإِنْ لَمْ تَعْلَمُوا آبَاءَهُمْ فَإِخْوَانُكُمْ فِي الدِّينِ وَمَوَالِيكُمْ ‏)‏ فُلاَنٌ مَوْلَى فُلاَنٍ وَفُلاَنٌ أَخُو فُلاَنٍ ‏(‏هُوَ أَقْسَطُ عِنْدَ اللَّهِ ‏)‏ يَعْنِي أَعْدَلُ عِنْدَ اللَّهِ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ غَرِيبٌ ‏.‏ قَدْ رُوِيَ عَنْ دَاوُدَ بْنِ أَبِي هِنْدٍ، عَنِ الشَّعْبِيِّ، عَنْ مَسْرُوقٍ، عَنْ عَائِشَةَ، قَالَتْ لَوْ كَانَ النَّبِيُّ صلى الله عليه وسلم كَاتِمًا شَيْئًا مِنَ الْوَحْىِ لَكَتَمَ هَذِهِ الآيَةَ ‏:‏ ‏(‏ إِذْ تَقُولُ لِلَّذِي أَنْعَمَ اللَّهُ عَلَيْهِ وَأَنْعَمْتَ عَلَيْهِ ‏)‏ الآيَةَ هَذَا الْحَرْفُ لَمْ يُرْوَ بِطُولِهِ ‏.‏ حَدَّثَنَا بِذَلِكَ عَبْدُ اللَّهِ بْنُ وَضَّاحٍ الْكُوفِيُّ حَدَّثَنَا عَبْدُ اللَّهِ بْنُ إِدْرِيسَ عَنْ دَاوُدَ بْنِ أَبِي هِنْدٍ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3210","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3210","x":"Narrated Dawud bin Abi Hind:\n\nfrom Ash-Sha'bi regarding the saying of Allah [the Mighty and Sublime]: 'Muhammad is not the father of any one of your men (33:40)' he said: \"No male children of his would live among them.\"","ar":"حَدَّثَنَا الْحَسَنُ بْنُ قَزَعَةَ، - بَصْرِيٌّ - حَدَّثَنَا مَسْلَمَةُ بْنُ عَلْقَمَةَ، عَنْ دَاوُدَ بْنِ أَبِي هِنْدٍ، عَنْ عَامِرٍ الشَّعْبِيِّ، فِي قَوْلِ اللَّهِ عَزَّ وَجَلَّ ‏:‏ ‏(‏ ما كَانَ مُحَمَّدٌ أَبَا أَحَدٍ مِنْ رِجَالِكُمْ ‏)‏ قَالَ مَا كَانَ لِيَعِيشَ لَهُ فِيكُمْ وَلَدٌ ذَكَرٌ ‏.‏","v":[]}],"45":[{"c":"Al-Adab Al-Mufrad","r":"Book 12, Hadith 247","u":"https://quranx.com/Hadith/Adab/English/Book-12/Hadith-247","x":"'Abdullah ibn 'Ata' said, \"This ayat which is in the Qur'an, 'O Prophet, We have sent you as a witness, a bringer of good news and a warner' (33:45) is found in the Torah in a similar form.\"","ar":"حَدَّثَنَا عَبْدُ اللهِ بْنُ صَالِحٍ قَالَ‏:‏ حَدَّثَنِي عَبْدُ الْعَزِيزِ بْنُ أَبِي سَلَمَةَ، عَنْ هِلاَلِ بْنِ أَبِي هِلاَلٍ، عَنْ عَطَاءِ بْنِ يَسَارٍ، عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو قَالَ‏:‏ إِنَّ هَذِهِ الْآيَةَ الَّتِي فِي الْقُرْآنِ ‏{‏يَا أَيُّهَا النَّبِيُّ إِنَّا أَرْسَلْنَاكَ شَاهِدًا وَمُبَشِّرًا وَنَذِيرًا‏}‏ فِي التَّوْرَاةِ نَحْوَهُ‏.‏","v":[]}],"49":[{"c":"Sunan Abu Dawud","r":"Hadith 2289","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2289","x":"Abu Salamah reported on the authority of Fatimah daughter of Qays who said to him that she was the wife of AbuHafs ibn al-Mughirah who divorced her by three pronouncements. She said that she came to the Messenger of Allah (ﷺ) and sought his opinion about her going out from her house. He commanded her to shift to (the house of )Ibn Umm Maktum who was blind. Marwan denied to confirm the tradition of Fatimah about the going out of a divorced woman from her house. Urwah said:\n\nAisha objected to Fatimah daughter of Qays. Abu Dawud said: Salih b. Kaisan, Ibn Juraij, and Shu'aib b. Abi Hamzah -- all of them narrated on the authority of al-Zuhru in a similar way. Abu Dawud said: Shu'aibn b. Abi Hamzah the name of Abu Hamzah is Dinar. He is a client of Ziyad.","ar":"حَدَّثَنَا يَزِيدُ بْنُ خَالِدٍ الرَّمْلِيُّ، حَدَّثَنَا اللَّيْثُ، عَنْ عُقَيْلٍ، عَنِ ابْنِ شِهَابٍ، عَنْ أَبِي سَلَمَةَ، عَنْ فَاطِمَةَ بِنْتِ قَيْسٍ، أَنَّهَا أَخْبَرَتْهُ أَنَّهَا، كَانَتْ عِنْدَ أَبِي حَفْصِ بْنِ الْمُغِيرَةِ وَأَنَّ أَبَا حَفْصِ بْنَ الْمُغِيرَةِ طَلَّقَهَا آخِرَ ثَلاَثِ تَطْلِيقَاتٍ فَزَعَمَتْ أَنَّهَا جَاءَتْ رَسُولَ اللَّهِ صلى الله عليه وسلم فَاسْتَفْتَتْهُ فِي خُرُوجِهَا مِنْ بَيْتِهَا فَأَمَرَهَا أَنْ تَنْتَقِلَ إِلَى ابْنِ أُمِّ مَكْتُومٍ الأَعْمَى فَأَبَى مَرْوَانُ أَنْ يُصَدِّقَ حَدِيثَ فَاطِمَةَ فِي خُرُوجِ الْمُطَلَّقَةِ مِنْ بَيْتِهَا ‏.‏ قَالَ عُرْوَةُ وَأَنْكَرَتْ عَائِشَةُ - رضى الله عنها - عَلَى فَاطِمَةَ بِنْتِ قَيْسٍ ‏.‏ قَالَ أَبُو دَاوُدَ وَكَذَلِكَ رَوَاهُ صَالِحُ بْنُ كَيْسَانَ وَابْنُ جُرَيْجٍ وَشُعَيْبُ بْنُ أَبِي حَمْزَةَ كُلُّهُمْ عَنِ الزُّهْرِيِّ ‏.‏ قَالَ أَبُو دَاوُدَ وَشُعَيْبُ بْنُ أَبِي حَمْزَةَ وَاسْمُ أَبِي حَمْزَةَ دِينَارٌ وَهُوَ مَوْلَى زِيَادٍ ‏.‏","v":[]}],"50":[{"c":"Sahih Bukhari","r":"Hadith 268","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-268","x":"Narrated Qatada:\n\nAnas bin Malik said, \"The Prophet (ﷺ) used to visit all his wives in a round, during the day and night and they were eleven in number.\" I asked Anas, \"Had the Prophet (ﷺ) the strength for it?\" Anas replied, \"We used to say that the Prophet (ﷺ) was given the strength of thirty (men).\" And Sa`id said on the authority of Qatada that Anas had told him about nine wives only (not eleven).","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ بَشَّارٍ، قَالَ حَدَّثَنَا مُعَاذُ بْنُ هِشَامٍ، قَالَ حَدَّثَنِي أَبِي، عَنْ قَتَادَةَ، قَالَ حَدَّثَنَا أَنَسُ بْنُ مَالِكٍ، قَالَ كَانَ النَّبِيُّ صلى الله عليه وسلم يَدُورُ عَلَى نِسَائِهِ فِي السَّاعَةِ الْوَاحِدَةِ مِنَ اللَّيْلِ وَالنَّهَارِ، وَهُنَّ إِحْدَى عَشْرَةَ‏.‏ قَالَ قُلْتُ لأَنَسٍ أَوَكَانَ يُطِيقُهُ قَالَ كُنَّا نَتَحَدَّثُ أَنَّهُ أُعْطِيَ قُوَّةَ ثَلاَثِينَ‏.‏ وَقَالَ سَعِيدٌ عَنْ قَتَادَةَ إِنَّ أَنَسًا حَدَّثَهُمْ تِسْعُ نِسْوَةٍ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 284","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-284","x":"Narrated Anas bin Malik:\n\nThe Prophet (ﷺ) used to visit all his wives in one night and he had nine wives at that time.","ar":"حَدَّثَنَا عَبْدُ الأَعْلَى بْنُ حَمَّادٍ، قَالَ حَدَّثَنَا يَزِيدُ بْنُ زُرَيْعٍ، قَالَ حَدَّثَنَا سَعِيدٌ، عَنْ قَتَادَةَ، أَنَّ أَنَسَ بْنَ مَالِكٍ، حَدَّثَهُمْ أَنَّ نَبِيَّ اللَّهِ صلى الله عليه وسلم كَانَ يَطُوفُ عَلَى نِسَائِهِ فِي اللَّيْلَةِ الْوَاحِدَةِ، وَلَهُ يَوْمَئِذٍ تِسْعُ نِسْوَةٍ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3214","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3214","x":"Narrated Umm Hani bint Abu Talib:\n\n\"The Messenger of Allah (ﷺ) proposed to me, but I asked him to excuse me. Then Allah [Most High] revealed: 'Verily We have made lawful to you your wives, to whom you have paid their due, and those whom your right hand possess - whom Allah has given to you, and the daughters of your paternal uncles, and the daughters of your paternal aunts, and the daughters of your maternal uncles, and the daughters of your maternal aunts, who migrated with you, and a believing woman if she offers herself to the Prophet... (33:50)' She said: \"So I was not lawful for him because I did not perform Hijrah; I was one of the Tulaqa (those that accepted Islam after the conquest of Makkah).'\"","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، حَدَّثَنَا عُبَيْدُ اللَّهِ بْنُ مُوسَى، عَنْ إِسْرَائِيلَ، عَنِ السُّدِّيِّ، عَنْ أَبِي صَالِحٍ، عَنْ أُمِّ هَانِئٍ بِنْتِ أَبِي طَالِبٍ، قَالَتْ خَطَبَنِي رَسُولُ اللَّهِ صلى الله عليه وسلم فَاعْتَذَرْتُ إِلَيْهِ فَعَذَرَنِي ثُمَّ أَنْزَلَ اللَّهُ تَعَالَى ‏:‏ ‏(‏إنَّا أَحْلَلْنَا لَكَ أَزْوَاجَكَ اللاَّتِي آتَيْتَ أُجُورَهُنَّ وَمَا مَلَكَتْ يَمِينُكَ مِمَّا أَفَاءَ اللَّهُ عَلَيْكَ وَبَنَاتِ عَمِّكَ وَبَنَاتِ عَمَّاتِكَ وَبَنَاتِ خَالِكَ وَبَنَاتِ خَالاَتِكَ اللاَّتِي هَاجَرْنَ مَعَكَ وَامْرَأَةً مُؤْمِنَةً إِنْ وَهَبَتْ نَفْسَهَا لِلنَّبِيِّ ‏)‏ الآيَةَ قَالَتْ فَلَمْ أَكُنْ أَحِلُّ لَهُ لأَنِّي لَمْ أُهَاجِرْ كُنْتُ مِنَ الطُّلَقَاءِ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ لاَ نَعْرِفُهُ إِلاَّ مِنْ هَذَا الْوَجْهِ مِنْ حَدِيثِ السُّدِّيِّ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3215","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3215","x":"Narrated Ibn 'Abbas:\n\n\"All types of women were prohibited for the Messenger of ALlah (ﷺ) except for the believing women among those who emigrated. (Allah) said: 'It is not lawful for you (to marry other) women after this, nor to change them for other wives even though their beauty attracts you, except those whom your right hand possesses (33:52). - And Allah made your believing girls lawful 'And a believing woman if she offers herself to the Prophet (33:50)' and He made every woman of a religion other than Islam unlawful.\" Then He said: \"And whoever disbelieves in faith then fruitless is his work; and in the Hereafter he will be among the losers (5:5).\" And he said: \"Verily We have made lawful to you your wives, to whom you have paid their due, and those whom your right hands possess - whom Allah has given you\" up to His saying: \"A privilege to only you, not for the (rest of) the believers (33:50).\" He made the other types of women unlawful.\"","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، حَدَّثَنَا رَوْحٌ، عَنْ عَبْدِ الْحَمِيدِ بْنِ بَهْرَامَ، عَنْ شَهْرِ بْنِ حَوْشَبٍ، قَالَ قَالَ ابْنُ عَبَّاسٍ رضى الله عنهما نُهِيَ رَسُولُ اللَّهِ صلى الله عليه وسلم عَنْ أَصْنَافِ النِّسَاءِ إِلاَّ مَا كَانَ مِنَ الْمُؤْمِنَاتِ الْمُهَاجِرَاتِ قَالَ ‏:‏ ‏(‏ لا يَحِلُّ لَكَ النِّسَاءُ مِنْ بَعْدُ وَلاَ أَنْ تَبَدَّلَ بِهِنَّ مِنْ أَزْوَاجٍ وَلَوْ أَعْجَبَكَ حُسْنُهُنَّ إِلاَّ مَا مَلَكَتْ يَمِينُكَ ‏)‏ فَأَحَلَّ اللَّهُ فَتَيَاتِكُمُ الْمُؤْمِنَاتِ وَامْرَأَةً مُؤْمِنَةً إِنْ وَهَبَتْ نَفْسَهَا لِلنَّبِيِّ وَحَرَّمَ كُلَّ ذَاتِ دِينٍ غَيْرَ الإِسْلاَمِ ثُمَّ قَالَ ‏:‏ ‏(‏ومَنْ يَكْفُرْ بِالإِيمَانِ فَقَدْ حَبِطَ عَمَلُهُ وَهُوَ فِي الآخِرَةِ مِنَ الْخَاسِرِينَ ‏)‏ وَقَالَ ‏:‏ ‏(‏ يا أَيُّهَا النَّبِيُّ إِنَّا أَحْلَلْنَا لَكَ أَزْوَاجَكَ اللاَّتِي آتَيْتَ أُجُورَهُنَّ وَمَا مَلَكَتْ يَمِينُكَ مِمَّا أَفَاءَ اللَّهُ عَلَيْكَ ‏)‏ إِلَى قَوْلِهِ ‏:‏ ‏(‏ خالِصَةً لَكَ مِنْ دُونِ الْمُؤْمِنِينَ ‏)‏ وَحَرَّمَ مَا سِوَى ذَلِكَ مِنْ أَصْنَافِ النِّسَاءِ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ إِنَّمَا نَعْرِفُهُ مِنْ حَدِيثِ عَبْدِ الْحَمِيدِ بْنِ بَهْرَامَ ‏.‏ قَالَ سَمِعْتُ أَحْمَدَ بْنَ الْحَسَنِ يَقُولُ قَالَ أَحْمَدُ بْنُ حَنْبَلِ لاَ بَأْسَ بِحَدِيثِ عَبْدِ الْحَمِيدِ بْنِ بَهْرَامَ عَنْ شَهْرِ بْنِ حَوْشَبٍ ‏.‏","v":[]}],"51":[{"c":"Sunan Abu Dawud","r":"Hadith 2136","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2136","x":"Narrated 'Aishah:\n\nThe Messenger of Allah (ﷺ) used to aske our permission on the day he had to stay with one of his wives (by turns) after the following Qur'anic verse was revealed: \"You may distance those whom you like, and draw close to those whom you like\" [33:51]. The narrator Mu'adhah said: I said to her: What did you say to the Messenger of Allah (ﷺ) ? She said: I used to say: If had an option for that, I would not preferred anyone to myself.","ar":"حَدَّثَنَا يَحْيَى بْنُ مَعِينٍ، وَمُحَمَّدُ بْنُ عِيسَى، - الْمَعْنَى - قَالاَ حَدَّثَنَا عَبَّادُ بْنُ عَبَّادٍ، عَنْ عَاصِمٍ، عَنْ مُعَاذَةَ، عَنْ عَائِشَةَ، قَالَتْ كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يَسْتَأْذِنُنَا إِذَا كَانَ فِي يَوْمِ الْمَرْأَةِ مِنَّا بَعْدَ مَا نَزَلَتْ ‏{‏ تُرْجِي مَنْ تَشَاءُ مِنْهُنَّ وَتُؤْوِي إِلَيْكَ مَنْ تَشَاءُ ‏}‏ قَالَتْ مُعَاذَةُ فَقُلْتُ لَهَا مَا كُنْتِ تَقُولِينَ لِرَسُولِ اللَّهِ صلى الله عليه وسلم قَالَتْ كُنْتُ أَقُولُ إِنْ كَانَ ذَلِكَ إِلَىَّ لَمْ أُوثِرْ أَحَدًا عَلَى نَفْسِي ‏.‏","v":[]},{"c":"Sunan Abu Dawud","r":"Hadith 2141","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2141","x":"Abu Hurairah reported the Prophet (ﷺ) as saying \"When a man calls his wife to come to his bed and she refuses and does not come to him and he spends the night angry, the angels curse her till the morning.\"","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ عَمْرٍو الرَّازِيُّ، حَدَّثَنَا جَرِيرٌ، عَنِ الأَعْمَشِ، عَنْ أَبِي حَازِمٍ، عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏\n\n\"‏ إِذَا دَعَا الرَّجُلُ امْرَأَتَهُ إِلَى فِرَاشِهِ فَأَبَتْ فَلَمْ تَأْتِهِ فَبَاتَ غَضْبَانَ عَلَيْهَا لَعَنَتْهَا الْمَلاَئِكَةُ حَتَّى تُصْبِحَ ‏\"\n\n‏ ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 268","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-268","x":"Narrated Qatada:\n\nAnas bin Malik said, \"The Prophet (ﷺ) used to visit all his wives in a round, during the day and night and they were eleven in number.\" I asked Anas, \"Had the Prophet (ﷺ) the strength for it?\" Anas replied, \"We used to say that the Prophet (ﷺ) was given the strength of thirty (men).\" And Sa`id said on the authority of Qatada that Anas had told him about nine wives only (not eleven).","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ بَشَّارٍ، قَالَ حَدَّثَنَا مُعَاذُ بْنُ هِشَامٍ، قَالَ حَدَّثَنِي أَبِي، عَنْ قَتَادَةَ، قَالَ حَدَّثَنَا أَنَسُ بْنُ مَالِكٍ، قَالَ كَانَ النَّبِيُّ صلى الله عليه وسلم يَدُورُ عَلَى نِسَائِهِ فِي السَّاعَةِ الْوَاحِدَةِ مِنَ اللَّيْلِ وَالنَّهَارِ، وَهُنَّ إِحْدَى عَشْرَةَ‏.‏ قَالَ قُلْتُ لأَنَسٍ أَوَكَانَ يُطِيقُهُ قَالَ كُنَّا نَتَحَدَّثُ أَنَّهُ أُعْطِيَ قُوَّةَ ثَلاَثِينَ‏.‏ وَقَالَ سَعِيدٌ عَنْ قَتَادَةَ إِنَّ أَنَسًا حَدَّثَهُمْ تِسْعُ نِسْوَةٍ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 284","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-284","x":"Narrated Anas bin Malik:\n\nThe Prophet (ﷺ) used to visit all his wives in one night and he had nine wives at that time.","ar":"حَدَّثَنَا عَبْدُ الأَعْلَى بْنُ حَمَّادٍ، قَالَ حَدَّثَنَا يَزِيدُ بْنُ زُرَيْعٍ، قَالَ حَدَّثَنَا سَعِيدٌ، عَنْ قَتَادَةَ، أَنَّ أَنَسَ بْنَ مَالِكٍ، حَدَّثَهُمْ أَنَّ نَبِيَّ اللَّهِ صلى الله عليه وسلم كَانَ يَطُوفُ عَلَى نِسَائِهِ فِي اللَّيْلَةِ الْوَاحِدَةِ، وَلَهُ يَوْمَئِذٍ تِسْعُ نِسْوَةٍ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2468","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2468","x":"Narrated `Abdullah bin `Abbas:\n\nI had been eager to ask `Umar about the two ladies from among the wives of the Prophet (ﷺ) regarding whom Allah said (in the Qur'an saying): If you two (wives of the Prophet (ﷺ) namely Aisha and Hafsa) turn in repentance to Allah your hearts are indeed so inclined (to oppose what the Prophet (ﷺ) likes) (66.4), till performed the Hajj along with `Umar (and on our way back from Hajj) he went aside (to answer the call of nature) and I also went aside along with him carrying a tumbler of water. When he had answered the call of nature and returned. I poured water on his hands from the tumbler and he performed ablution. I said, \"O Chief of the believers! ' Who were the two ladies from among the wives of the Prophet (ﷺ) to whom Allah said: 'If you two return in repentance (66.4)? He said, \"I am astonished at your question, O Ibn `Abbas. They were Aisha and Hafsa.\" Then `Umar went on relating the narration and said. \"I and an Ansari neighbor of mine from Bani Umaiya bin Zaid who used to live in `Awali Al-Medina, used to visit the Prophet (ﷺ) in turns. He used to go one day, and I another day. When I went I would bring him the news of what had happened that day regarding the instructions and orders and when he went, he used to do the same for me. We, the people of Quraish, used to have authority over women, but when we came to live with the Ansar, we noticed that the Ansari women had the upper hand over their men, so our women started acquiring the habits of the Ansari women. Once I shouted at my wife and she paid me back in my coin and I disliked that she should answer me back. She said, 'Why do you take it ill that I retort upon you? By Allah, the wives of the Prophet (ﷺ) retort upon him, and some of them may not speak with him for the whole day till night.' What she said scared me and I said to her, 'Whoever amongst them does so, will be a great loser.' Then I dressed myself and went to Hafsa and asked her, 'Does any of you keep Allah's Messenger (ﷺ) angry all the day long till night?' She replied in the affirmative. I said, 'She is a ruined losing person (and will never have success)! Doesn't she fear that Allah may get angry for the anger of Allah's Messenger (ﷺ) and thus she will be ruined? Don't ask Allah's Messenger (ﷺ) too many things, and don't retort upon him in any case, and don't desert him. Demand from me whatever you like, and don't be tempted to imitate your neighbor (i.e. `Aisha) in her behavior towards the Prophet), for she (i.e. Aisha) is more beautiful than you, and more beloved to Allah's Messenger (ﷺ). In those days it was rumored that Ghassan, (a tribe living in Sham) was getting prepared their horses to invade us. My companion went (to the Prophet (ﷺ) on the day of his turn, went and returned to us at night and knocked at my door violently, asking whether I was sleeping. I was scared (by the hard knocking) and came out to him. He said that a great thing had happened. I asked him: What is it? Have Ghassan come? He replied that it was worse and more serious than that, and added that Allah's Apostle had divorced all his wives. I said, Hafsa is a ruined loser! I expected that would happen some day.' So I dressed myself and offered the Fajr prayer with the Prophet. Then the Prophet (ﷺ) entered an upper room and stayed there alone. I went to Hafsa and found her weeping. I asked her, 'Why are you weeping? Didn't I warn you? Have Allah's Messenger (ﷺ) divorced you all?' She replied, 'I don't know. He is there in the upper room.' I then went out and came to the pulpit and found a group of people around it and some of them were weeping. Then I sat with them for some time, but could not endure the situation. So I went to the upper room where the Prophet (ﷺ) was and requested to a black slave of his: \"Will you get the permission of (Allah's Apostle) for `Umar (to enter)? The slave went in, talked to the Prophet (ﷺ) about it and came out saying, 'I mentioned you to him but he did not reply.' So, I went and sat with the people who were sitting by the pulpit, but I could not bear the situation, so I went to the slave again and said: \"Will you get he permission for `Umar? He went in and brought the same reply as before. When I was leaving, behold, the slave called me saying, \"Allah's Messenger (ﷺ) has granted you permission.\" So, I entered upon the Prophet and saw him lying on a mat without wedding on it, and the mat had left its mark on the body of the Prophet, and he was leaning on a leather pillow stuffed with palm fires. I greeted him and while still standing, I said: \"Have you divorced your wives?' He raised his eyes to me and replied in the negative. And then while still standing, I said chatting: \"Will you heed what I say, 'O Allah's Messenger (ﷺ)! We, the people of Quraish used to have the upper hand over our women (wives), and when we came to the people whose women had the upper hand over them...\" `Umar told the whole story (about his wife). \"On that the Prophet (ﷺ) smiled.\" `Umar further said, \"I then said, 'I went to Hafsa and said to her: Do not be tempted to imitate your companion (`Aisha) for she is more beautiful than you and more beloved to the Prophet.' The Prophet (ﷺ) smiled again. When I saw him smiling, I sat down and cast a glance at the room, and by Allah, I couldn't see anything of importance but three hides. I said (to Allah's Messenger (ﷺ)) \"Invoke Allah to make your followers prosperous for the Persians and the Byzantines have been made prosperous and given worldly luxuries, though they do not worship Allah?' The Prophet (ﷺ) was leaning then (and on hearing my speech he sat straight) and said, 'O Ibn Al-Khattab! Do you have any doubt (that the Hereafter is better than this world)? These people have been given rewards of their good deeds in this world only.' I asked the Prophet (ﷺ). 'Please ask Allah's forgiveness for me. The Prophet (ﷺ) did not go to his wives because of the secret which Hafsa had disclosed to `Aisha, and he said that he would not go to his wives for one month as he was angry with them when Allah admonished him (for his oath that he would not approach Maria). When twenty-nine days had passed, the Prophet (ﷺ) went to Aisha first of all. She said to him, 'You took an oath that you would not come to us for one month, and today only twenty-nine days have passed, as I have been counting them day by day.' The Prophet (ﷺ) said, 'The month is also of twenty-nine days.' That month consisted of twenty-nine days. `Aisha said, 'When the Divine revelation of Choice was revealed, the Prophet (ﷺ) started with me, saying to me, 'I am telling you something, but you need not hurry to give the reply till you can consult your parents.\" `Aisha knew that her parents would not advise her to part with the Prophet (ﷺ). The Prophet (ﷺ) said that Allah had said: 'O Prophet! Say To your wives; If you desire The life of this world And its glitter,... then come! I will make a provision for you and set you free In a handsome manner. But if you seek Allah And His Apostle, and The Home of the Hereafter, then Verily, Allah has prepared For the good-doers amongst you A great reward.' (33.28) `Aisha said, 'Am I to consult my parents about this? I indeed prefer Allah, His Apostle, and the Home of the Hereafter.' After that the Prophet (ﷺ) gave the choice to his other wives and they also gave the same reply as `Aisha did.\"","ar":"حَدَّثَنَا يَحْيَى بْنُ بُكَيْرٍ، حَدَّثَنَا اللَّيْثُ، عَنْ عُقَيْلٍ، عَنِ ابْنِ شِهَابٍ، قَالَ أَخْبَرَنِي عُبَيْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي ثَوْرٍ، عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ـ رضى الله عنهما ـ قَالَ لَمْ أَزَلْ حَرِيصًا عَلَى أَنْ أَسْأَلَ عُمَرَ ـ رضى الله عنه ـ عَنِ الْمَرْأَتَيْنِ مِنْ أَزْوَاجِ النَّبِيِّ صلى الله عليه وسلم اللَّتَيْنِ قَالَ اللَّهُ لَهُمَا ‏{‏إِنْ تَتُوبَا إِلَى اللَّهِ فَقَدْ صَغَتْ قُلُوبُكُمَا‏}‏ فَحَجَجْتُ مَعَهُ فَعَدَلَ وَعَدَلْتُ مَعَهُ بِالإِدَاوَةِ، فَتَبَرَّزَ حَتَّى جَاءَ، فَسَكَبْتُ عَلَى يَدَيْهِ مِنَ الإِدَاوَةِ، فَتَوَضَّأَ فَقُلْتُ يَا أَمِيرَ الْمُؤْمِنِينَ مَنِ الْمَرْأَتَانِ مِنْ أَزْوَاجِ النَّبِيِّ صلى الله عليه وسلم اللَّتَانِ قَالَ لَهُمَا ‏{‏إِنْ تَتُوبَا إِلَى اللَّهِ‏}‏ فَقَالَ وَاعَجَبِي لَكَ يَا ابْنَ عَبَّاسٍ عَائِشَةُ وَحَفْصَةُ، ثُمَّ اسْتَقْبَلَ عُمَرُ الْحَدِيثَ يَسُوقُهُ، فَقَالَ إِنِّي كُنْتُ وَجَارٌ لِي مِنَ الأَنْصَارِ فِي بَنِي أُمَيَّةَ بْنِ زَيْدٍ، وَهْىَ مِنْ عَوَالِي الْمَدِينَةِ، وَكُنَّا نَتَنَاوَبُ النُّزُولَ عَلَى النَّبِيِّ صلى الله عليه وسلم فَيَنْزِلُ يَوْمًا وَأَنْزِلُ يَوْمًا، فَإِذَا نَزَلْتُ جِئْتُهُ مِنْ خَبَرِ ذَلِكَ الْيَوْمِ مِنَ الأَمْرِ وَغَيْرِهِ، وَإِذَا نَزَلَ فَعَلَ مِثْلَهُ، وَكُنَّا مَعْشَرَ قُرَيْشٍ نَغْلِبُ النِّسَاءَ، فَلَمَّا قَدِمْنَا عَلَى الأَنْصَارِ إِذَا هُمْ قَوْمٌ تَغْلِبُهُمْ نِسَاؤُهُمْ، فَطَفِقَ نِسَاؤُنَا يَأْخُذْنَ مِنْ أَدَبِ نِسَاءِ الأَنْصَارِ، فَصِحْتُ عَلَى امْرَأَتِي، فَرَاجَعَتْنِي، فَأَنْكَرْتُ أَنْ تُرَاجِعَنِي، فَقَالَتْ وَلِمَ تُنْكِرُ أَنْ أُرَاجِعَكَ فَوَاللَّهِ إِنَّ أَزْوَاجَ النَّبِيِّ صلى الله عليه وسلم لَيُرَاجِعْنَهُ، وَإِنَّ إِحْدَاهُنَّ لَتَهْجُرُهُ الْيَوْمَ حَتَّى اللَّيْلِ‏.‏ فَأَفْزَعَنِي، فَقُلْتُ خَابَتْ مَنْ فَعَلَ مِنْهُنَّ بِعَظِيمٍ‏.‏ ثُمَّ جَمَعْتُ عَلَىَّ ثِيَابِي، فَدَخَلْتُ عَلَى حَفْصَةَ فَقُلْتُ أَىْ حَفْصَةُ، أَتُغَاضِبُ إِحْدَاكُنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم الْيَوْمَ حَتَّى اللَّيْلِ فَقَالَتْ نَعَمْ‏.‏ فَقُلْتُ خَابَتْ وَخَسِرَتْ، أَفَتَأْمَنُ أَنْ يَغْضَبَ اللَّهُ لِغَضَبِ رَسُولِهِ صلى الله عليه وسلم فَتَهْلِكِينَ لاَ تَسْتَكْثِرِي عَلَى رَسُولِ اللَّهِ صلى الله عليه وسلم وَلاَ تُرَاجِعِيهِ فِي شَىْءٍ وَلاَ تَهْجُرِيهِ، وَاسْأَلِينِي مَا بَدَا لَكِ، وَلاَ يَغُرَّنَّكِ أَنْ كَانَتْ جَارَتُكِ هِيَ أَوْضَأَ مِنْكِ وَأَحَبَّ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم ـ يُرِيدُ عَائِشَةَ ـ وَكُنَّا تَحَدَّثْنَا أَنَّ غَسَّانَ تُنْعِلُ النِّعَالَ لِغَزْوِنَا، فَنَزَلَ صَاحِبِي يَوْمَ نَوْبَتِهِ فَرَجَعَ عِشَاءً، فَضَرَبَ بَابِي ضَرْبًا شَدِيدًا، وَقَالَ أَنَائِمٌ هُوَ فَفَزِعْتُ فَخَرَجْتُ إِلَيْهِ‏.‏ وَقَالَ حَدَثَ أَمْرٌ عَظِيمٌ‏.‏ قُلْتُ مَا هُوَ أَجَاءَتْ غَسَّانُ قَالَ لاَ، بَلْ أَعْظَمُ مِنْهُ وَأَطْوَلُ، طَلَّقَ رَسُولُ اللَّهِ صلى الله عليه وسلم نِسَاءَهُ‏.‏ قَالَ قَدْ خَابَتْ حَفْصَةُ وَخَسِرَتْ، كُنْتُ أَظُنُّ أَنَّ هَذَا يُوشِكُ أَنْ يَكُونَ، فَجَمَعْتُ عَلَىَّ ثِيَابِي، فَصَلَّيْتُ صَلاَةَ الْفَجْرِ مَعَ النَّبِيِّ صلى الله عليه وسلم فَدَخَلَ مَشْرُبَةً لَهُ فَاعْتَزَلَ فِيهَا، فَدَخَلْتُ عَلَى حَفْصَةَ، فَإِذَا هِيَ تَبْكِي‏.‏ قُلْتُ مَا يُبْكِيكِ أَوَلَمْ أَكُنْ حَذَّرْتُكِ أَطَلَّقَكُنَّ رَسُولُ اللَّهِ صلى الله عليه وسلم قَالَتْ لاَ أَدْرِي هُوَ ذَا فِي الْمَشْرُبَةِ‏.‏ فَخَرَجْتُ، فَجِئْتُ الْمِنْبَرَ، فَإِذَا حَوْلَهُ رَهْطٌ يَبْكِي بَعْضُهُمْ، فَجَلَسْتُ مَعَهُمْ قَلِيلاً ثُمَّ غَلَبَنِي مَا أَجِدُ، فَجِئْتُ الْمَشْرُبَةَ الَّتِي هُوَ فِيهَا فَقُلْتُ لِغُلاَمٍ لَهُ أَسْوَدَ اسْتَأْذِنْ لِعُمَرَ‏.‏ فَدَخَلَ، فَكَلَّمَ النَّبِيَّ صلى الله عليه وسلم ثُمَّ خَرَجَ، فَقَالَ ذَكَرْتُكَ لَهُ، فَصَمَتَ، فَانْصَرَفْتُ حَتَّى جَلَسْتُ مَعَ الرَّهْطِ الَّذِينَ عِنْدَ الْمِنْبَرِ، ثُمَّ غَلَبَنِي مَا أَجِدُ فَجِئْتُ، فَذَكَرَ مِثْلَهُ، فَجَلَسْتُ مَعَ الرَّهْطِ الَّذِينَ عِنْدَ الْمِنْبَرِ، ثُمَّ غَلَبَنِي مَا أَجِدُ فَجِئْتُ الْغُلاَمَ‏.‏ فَقُلْتُ اسْتَأْذِنْ لِعُمَرَ‏.‏ فَذَكَرَ مِثْلَهُ، فَلَمَّا وَلَّيْتُ مُنْصَرِفًا، فَإِذَا الْغُلاَمُ يَدْعُونِي قَالَ أَذِنَ لَكَ رَسُولُ اللَّهِ صلى الله عليه وسلم‏.‏ فَدَخَلْتُ عَلَيْهِ، فَإِذَا هُوَ مُضْطَجِعٌ عَلَى رِمَالِ حَصِيرٍ لَيْسَ بَيْنَهُ وَبَيْنَهُ فِرَاشٌ، قَدْ أَثَّرَ الرِّمَالُ بِجَنْبِهِ، مُتَّكِئٌ عَلَى وِسَادَةٍ مِنْ أَدَمٍ حَشْوُهَا لِيفٌ، فَسَلَّمْتُ عَلَيْهِ، ثُمَّ قُلْتُ وَأَنَا قَائِمٌ طَلَّقْتَ نِسَاءَكَ فَرَفَعَ بَصَرَهُ إِلَىَّ، فَقَالَ ‏\"‏ لاَ ‏\"‏‏.‏ ثُمَّ قُلْتُ ـ وَأَنَا قَائِمٌ أَسْتَأْنِسُ يَا رَسُولَ اللَّهِ، لَوْ رَأَيْتَنِي، وَكُنَّا مَعْشَرَ قُرَيْشٍ نَغْلِبُ النِّسَاءَ، فَلَمَّا قَدِمْنَا عَلَى قَوْمٍ تَغْلِبُهُمْ نِسَاؤُهُمْ، فَذَكَرَهُ، فَتَبَسَّمَ النَّبِيُّ صلى الله عليه وسلم، ثُمَّ قُلْتُ لَوْ رَأَيْتَنِي، وَدَخَلْتُ عَلَى حَفْصَةَ، فَقُلْتُ لاَ يَغُرَّنَّكِ أَنْ كَانَتْ جَارَتُكِ هِيَ أَوْضَأَ مِنْكِ وَأَحَبَّ إِلَى النَّبِيِّ صلى الله عليه وسلم ـ يُرِيدُ عَائِشَةَ ـ فَتَبَسَّمَ أُخْرَى، فَجَلَسْتُ حِينَ رَأَيْتُهُ تَبَسَّمَ، ثُمَّ رَفَعْتُ بَصَرِي فِي بَيْتِهِ، فَوَاللَّهِ مَا رَأَيْتُ فِيهِ شَيْئًا يَرُدُّ الْبَصَرَ غَيْرَ أَهَبَةٍ ثَلاَثَةٍ‏.‏ فَقُلْتُ ادْعُ اللَّهَ فَلْيُوَسِّعْ عَلَى أُمَّتِكَ، فَإِنَّ فَارِسَ وَالرُّومَ وُسِّعَ عَلَيْهِمْ وَأُعْطُوا الدُّنْيَا، وَهُمْ لاَ يَعْبُدُونَ اللَّهَ، وَكَانَ مُتَّكِئًا‏.‏ فَقَالَ ‏\"‏ أَوَفِي شَكٍّ أَنْتَ يَا ابْنَ الْخَطَّابِ أُولَئِكَ قَوْمٌ عُجِّلَتْ لَهُمْ طَيِّبَاتُهُمْ فِي الْحَيَاةِ الدُّنْيَا ‏\"‏‏.‏ فَقُلْتُ يَا رَسُولَ اللَّهِ اسْتَغْفِرْ لِي‏.‏ فَاعْتَزَلَ النَّبِيُّ صلى الله عليه وسلم مِنْ أَجْلِ ذَلِكَ الْحَدِيثِ حِينَ أَفْشَتْهُ حَفْصَةُ إِلَى عَائِشَةَ، وَكَانَ قَدْ قَالَ ‏\"‏ مَا أَنَا بِدَاخِلٍ عَلَيْهِنَّ شَهْرًا ‏\"‏‏.‏ مِنْ شِدَّةِ مَوْجَدَتِهِ عَلَيْهِنَّ حِينَ عَاتَبَهُ اللَّهُ‏.‏ فَلَمَّا مَضَتْ تِسْعٌ وَعِشْرُونَ دَخَلَ عَلَى عَائِشَةَ فَبَدَأَ بِهَا، فَقَالَتْ لَهُ عَائِشَةُ إِنَّكَ أَقْسَمْتَ أَنْ لاَ تَدْخُلَ عَلَيْنَا شَهْرًا، وَإِنَّا أَصْبَحْنَا لِتِسْعٍ وَعِشْرِينَ لَيْلَةً، أَعُدُّهَا عَدًّا‏.‏ فَقَالَ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ الشَّهْرُ تِسْعٌ وَعِشْرُونَ ‏\"‏‏.‏ وَكَانَ ذَلِكَ الشَّهْرُ تِسْعٌ وَعِشْرُونَ‏.‏ قَالَتْ عَائِشَةُ فَأُنْزِلَتْ آيَةُ التَّخْيِيرِ فَبَدَأَ بِي أَوَّلَ امْرَأَةٍ، فَقَالَ ‏\"‏ إِنِّي ذَاكِرٌ لَكِ أَمْرًا، وَلاَ عَلَيْكِ أَنْ لاَ تَعْجَلِي حَتَّى تَسْتَأْمِرِي أَبَوَيْكِ ‏\"‏‏.‏ قَالَتْ قَدْ أَعْلَمُ أَنَّ أَبَوَىَّ لَمْ يَكُونَا يَأْمُرَانِي بِفِرَاقِكَ‏.‏ ثُمَّ قَالَ ‏\"‏ إِنَّ اللَّهَ قَالَ ‏{‏يَا أَيُّهَا النَّبِيُّ قُلْ لأَزْوَاجِكَ‏}‏ إِلَى قَوْلِهِ ‏{‏ عَظِيمًا‏}‏ ‏\"‏‏.‏ قُلْتُ أَفِي هَذَا أَسْتَأْمِرُ أَبَوَىَّ فَإِنِّي أُرِيدُ اللَّهَ وَرَسُولَهُ وَالدَّارَ الآخِرَةَ‏.‏ ثُمَّ خَيَّرَ نِسَاءَهُ، فَقُلْنَ مِثْلَ مَا قَالَتْ عَائِشَةُ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4788","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4788","x":"Narrated Aisha:\n\nI used to look down upon those ladies who had given themselves to Allah's Messenger (ﷺ) and I used to say, \"Can a lady give herself (to a man)?\" But when Allah revealed: \"You (O Muhammad) can postpone (the turn of) whom you will of them (your wives), and you may receive any of them whom you will; and there is no blame on you if you invite one whose turn you have set aside (temporarily).' (33.51) I said (to the Prophet), \"I feel that your Lord hastens in fulfilling your wishes and desires.\"","ar":"حَدَّثَنَا زَكَرِيَّاءُ بْنُ يَحْيَى، حَدَّثَنَا أَبُو أُسَامَةَ، قَالَ هِشَامٌ حَدَّثَنَا عَنْ أَبِيهِ، عَنْ عَائِشَةَ ـ رضى الله عنها ـ قَالَتْ كُنْتُ أَغَارُ عَلَى اللاَّتِي وَهَبْنَ أَنْفُسَهُنَّ لِرَسُولِ اللَّهِ صلى الله عليه وسلم وَأَقُولُ أَتَهَبُ الْمَرْأَةُ نَفْسَهَا فَلَمَّا أَنْزَلَ اللَّهُ تَعَالَى ‏{‏تُرْجِئُ مَنْ تَشَاءُ مِنْهُنَّ وَتُؤْوِي إِلَيْكَ مَنْ تَشَاءُ وَمَنِ ابْتَغَيْتَ مِمَّنْ عَزَلْتَ فَلاَ جُنَاحَ عَلَيْكَ‏}‏ قُلْتُ مَا أُرَى رَبَّكَ إِلاَّ يُسَارِعُ فِي هَوَاكَ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4789","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4789","x":"Narrated Mu`adha:\n\n`Aisha said, \"Allah's Messenger (ﷺ) used to take the permission of that wife with whom he was supposed to stay overnight if he wanted to go to one other than her, after this Verse was revealed:-- \"You (O Muhammad) can postpone (the turn of) whom you will of them (your wives) and you may receive any (of them) whom you will; and there is no blame on you if you invite one whose turn you have set aside (temporarily). (33.51) I asked Aisha, \"What did you use to say (in this case)?\" She said, \"I used to say to him, \"If I could deny you the permission (to go to your other wives) I would not allow your favor to be bestowed on any other person.\"","ar":"حَدَّثَنَا حِبَّانُ بْنُ مُوسَى، أَخْبَرَنَا عَبْدُ اللَّهِ، أَخْبَرَنَا عَاصِمٌ الأَحْوَلُ، عَنْ مُعَاذَةَ، عَنْ عَائِشَةَ ـ رضى الله عنها أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم كَانَ يَسْتَأْذِنُ فِي يَوْمِ الْمَرْأَةِ مِنَّا بَعْدَ أَنْ أُنْزِلَتْ هَذِهِ الآيَةُ ‏{‏تُرْجِئُ مَنْ تَشَاءُ مِنْهُنَّ وَتُؤْوِي إِلَيْكَ مَنْ تَشَاءُ وَمَنِ ابْتَغَيْتَ مِمَّنْ عَزَلْتَ فَلاَ جُنَاحَ عَلَيْكَ‏}‏‏.‏ فَقُلْتُ لَهَا مَا كُنْتِ تَقُولِينَ قَالَتْ كُنْتُ أَقُولُ لَهُ إِنْ كَانَ ذَاكَ إِلَىَّ فَإِنِّي لاَ أُرِيدُ يَا رَسُولَ اللَّهِ أَنْ أُوثِرَ عَلَيْكَ أَحَدًا‏.‏ تَابَعَهُ عَبَّادُ بْنُ عَبَّادٍ سَمِعَ عَاصِمًا‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 5113","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-5113","x":"Narrated Hisham's father:\n\nKhaula bint Hakim was one of those ladies who presented themselves to the Prophet (ﷺ) for marriage. `Aisha said, \"Doesn't a lady feel ashamed for presenting herself to a man?\" But when the Verse: \"(O Muhammad) You may postpone (the turn of) any of them (your wives) that you please,' (33.51) was revealed, \" `Aisha said, 'O Allah's Messenger (ﷺ)! I do not see, but, that your Lord hurries in pleasing you.' \"","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ سَلاَمٍ، حَدَّثَنَا ابْنُ فُضَيْلٍ، حَدَّثَنَا هِشَامٌ، عَنْ أَبِيهِ، قَالَ كَانَتْ خَوْلَةُ بِنْتُ حَكِيمٍ مِنَ اللاَّئِي وَهَبْنَ أَنْفُسَهُنَّ لِلنَّبِيِّ صلى الله عليه وسلم فَقَالَتْ عَائِشَةُ أَمَا تَسْتَحِي الْمَرْأَةُ أَنْ تَهَبَ نَفْسَهَا لِلرَّجُلِ فَلَمَّا نَزَلَتْ ‏{‏تُرْجِئُ مَنْ تَشَاءُ مِنْهُنَّ‏}‏ قُلْتُ يَا رَسُولَ اللَّهِ مَا أَرَى رَبَّكَ إِلاَّ يُسَارِعُ فِي هَوَاكَ‏.‏ رَوَاهُ أَبُو سَعِيدٍ الْمُؤَدِّبُ وَمُحَمَّدُ بْنُ بِشْرٍ وَعَبْدَةُ عَنْ هِشَامٍ عَنْ أَبِيهِ عَنْ عَائِشَةَ يَزِيدُ بَعْضُهُمْ عَلَى بَعْضٍ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 1464a","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-1464a","x":"'A'isha (Allah be pleased with her) reported:\n\nI felt jealous of the women who offered themselves to Allah's Messenger (ﷺ) and said: Then when Allah, the Exalted and Glorious, revealed this:\" You may defer any one of them you wish, and take to yourself any you wish; and if you desire any you have set aside (no sin is chargeable to you)\" (xxxiii. 51), I ('A'isha.) said: It seems to me that your Lord hastens to satisfy your desire.","ar":"حَدَّثَنَا أَبُو كُرَيْبٍ، مُحَمَّدُ بْنُ الْعَلاَءِ حَدَّثَنَا أَبُو أُسَامَةَ، عَنْ هِشَامٍ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ، قَالَتْ كُنْتُ أَغَارُ عَلَى اللاَّتِي وَهَبْنَ أَنْفُسَهُنَّ لِرَسُولِ اللَّهِ صلى الله عليه وسلم وَأَقُولُ وَتَهَبُ الْمَرْأَةُ نَفْسَهَا فَلَمَّا أَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏{‏ تُرْجِي مَنْ تَشَاءُ مِنْهُنَّ وَتُؤْوِي إِلَيْكَ مَنْ تَشَاءُ وَمَنِ ابْتَغَيْتَ مِمَّنْ عَزَلْتَ‏}‏ قَالَتْ قُلْتُ وَاللَّهِ مَا أَرَى رَبَّكَ إِلاَّ يُسَارِعُ لَكَ فِي هَوَاكَ.","v":[]}],"52":[{"c":"Sahih Bukhari","r":"Hadith 2235","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2235","x":"Narrated Anas bin Malik:\n\nThe Prophet (ﷺ) came to Khaibar and when Allah made him victorious and he conquered the town by breaking the enemy's defense, the beauty of Safiya bint Huyai bin Akhtab was mentioned to him and her husband had been killed while she was a bride. Allah's Messenger (ﷺ) selected her for himself and he set out in her company till he reached Sadd-ar-Rawha' where her menses were over and he married her. Then Hais (a kind of meal) was prepared and served on a small leather sheet (used for serving meals). Allah's Messenger (ﷺ) then said to me, \"Inform those who are around you (about the wedding banquet).\" So that was the marriage banquet given by Allah's Messenger (ﷺ) for (his marriage with) Safiya. After that we proceeded to Medina and I saw that Allah's Messenger (ﷺ) was covering her with a cloak while she was behind him. Then he would sit beside his camel and let Safiya put her feet on his knees to ride (the camel).","ar":"حَدَّثَنَا عَبْدُ الْغَفَّارِ بْنُ دَاوُدَ، حَدَّثَنَا يَعْقُوبُ بْنُ عَبْدِ الرَّحْمَنِ، عَنْ عَمْرِو بْنِ أَبِي عَمْرٍو، عَنْ أَنَسِ بْنِ مَالِكٍ ـ رضى الله عنه ـ قَالَ قَدِمَ النَّبِيُّ صلى الله عليه وسلم خَيْبَرَ، فَلَمَّا فَتَحَ اللَّهُ عَلَيْهِ الْحِصْنَ ذُكِرَ لَهُ جَمَالُ صَفِيَّةَ بِنْتِ حُيَىِّ بْنِ أَخْطَبَ، وَقَدْ قُتِلَ زَوْجُهَا، وَكَانَتْ عَرُوسًا، فَاصْطَفَاهَا رَسُولُ اللَّهِ صلى الله عليه وسلم لِنَفْسِهِ فَخَرَجَ بِهَا، حَتَّى بَلَغْنَا سَدَّ الرَّوْحَاءِ حَلَّتْ، فَبَنَى بِهَا، ثُمَّ صَنَعَ حَيْسًا فِي نِطَعٍ صَغِيرٍ، ثُمَّ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\n\n\"‏ آذِنْ مَنْ حَوْلَكَ ‏\"\n\n‏‏.‏ فَكَانَتْ تِلْكَ وَلِيمَةَ رَسُولِ اللَّهِ صلى الله عليه وسلم عَلَى صَفِيَّةَ، ثُمَّ خَرَجْنَا إِلَى الْمَدِينَةِ، قَالَ فَرَأَيْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم يُحَوِّي لَهَا وَرَاءَهُ بِعَبَاءَةٍ، ثُمَّ يَجْلِسُ عِنْدَ بَعِيرِهِ فَيَضَعُ رُكْبَتَهُ، فَتَضَعُ صَفِيَّةُ رِجْلَهَا عَلَى رُكْبَتِهِ، حَتَّى تَرْكَبَ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3215","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3215","x":"Narrated Ibn 'Abbas:\n\n\"All types of women were prohibited for the Messenger of ALlah (ﷺ) except for the believing women among those who emigrated. (Allah) said: 'It is not lawful for you (to marry other) women after this, nor to change them for other wives even though their beauty attracts you, except those whom your right hand possesses (33:52). - And Allah made your believing girls lawful 'And a believing woman if she offers herself to the Prophet (33:50)' and He made every woman of a religion other than Islam unlawful.\" Then He said: \"And whoever disbelieves in faith then fruitless is his work; and in the Hereafter he will be among the losers (5:5).\" And he said: \"Verily We have made lawful to you your wives, to whom you have paid their due, and those whom your right hands possess - whom Allah has given you\" up to His saying: \"A privilege to only you, not for the (rest of) the believers (33:50).\" He made the other types of women unlawful.\"","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، حَدَّثَنَا رَوْحٌ، عَنْ عَبْدِ الْحَمِيدِ بْنِ بَهْرَامَ، عَنْ شَهْرِ بْنِ حَوْشَبٍ، قَالَ قَالَ ابْنُ عَبَّاسٍ رضى الله عنهما نُهِيَ رَسُولُ اللَّهِ صلى الله عليه وسلم عَنْ أَصْنَافِ النِّسَاءِ إِلاَّ مَا كَانَ مِنَ الْمُؤْمِنَاتِ الْمُهَاجِرَاتِ قَالَ ‏:‏ ‏(‏ لا يَحِلُّ لَكَ النِّسَاءُ مِنْ بَعْدُ وَلاَ أَنْ تَبَدَّلَ بِهِنَّ مِنْ أَزْوَاجٍ وَلَوْ أَعْجَبَكَ حُسْنُهُنَّ إِلاَّ مَا مَلَكَتْ يَمِينُكَ ‏)‏ فَأَحَلَّ اللَّهُ فَتَيَاتِكُمُ الْمُؤْمِنَاتِ وَامْرَأَةً مُؤْمِنَةً إِنْ وَهَبَتْ نَفْسَهَا لِلنَّبِيِّ وَحَرَّمَ كُلَّ ذَاتِ دِينٍ غَيْرَ الإِسْلاَمِ ثُمَّ قَالَ ‏:‏ ‏(‏ومَنْ يَكْفُرْ بِالإِيمَانِ فَقَدْ حَبِطَ عَمَلُهُ وَهُوَ فِي الآخِرَةِ مِنَ الْخَاسِرِينَ ‏)‏ وَقَالَ ‏:‏ ‏(‏ يا أَيُّهَا النَّبِيُّ إِنَّا أَحْلَلْنَا لَكَ أَزْوَاجَكَ اللاَّتِي آتَيْتَ أُجُورَهُنَّ وَمَا مَلَكَتْ يَمِينُكَ مِمَّا أَفَاءَ اللَّهُ عَلَيْكَ ‏)‏ إِلَى قَوْلِهِ ‏:‏ ‏(‏ خالِصَةً لَكَ مِنْ دُونِ الْمُؤْمِنِينَ ‏)‏ وَحَرَّمَ مَا سِوَى ذَلِكَ مِنْ أَصْنَافِ النِّسَاءِ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ إِنَّمَا نَعْرِفُهُ مِنْ حَدِيثِ عَبْدِ الْحَمِيدِ بْنِ بَهْرَامَ ‏.‏ قَالَ سَمِعْتُ أَحْمَدَ بْنَ الْحَسَنِ يَقُولُ قَالَ أَحْمَدُ بْنُ حَنْبَلِ لاَ بَأْسَ بِحَدِيثِ عَبْدِ الْحَمِيدِ بْنِ بَهْرَامَ عَنْ شَهْرِ بْنِ حَوْشَبٍ ‏.‏","v":[]}],"53":[{"c":"Sahih Bukhari","r":"Hadith 4791","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4791","x":"Narrated Anas bin Malik:\n\nWhen Allah's Messenger (ﷺ) married Zainab bint Jahsh, he invited the people to a meal. They took the meal and remained sitting and talking. Then the Prophet (showed them) as if he is ready to get up, yet they did not get up. When he noticed that (there was no response to his movement), he got up, and the others too, got up except three persons who kept on sitting. The Prophet (ﷺ) came back in order to enter his house, but he went away again. Then they left, whereupon I set out and went to the Prophet (ﷺ) to tell him that they had departed, so he came and entered his house. I wanted to enter along with him, but he put a screen between me and him. Then Allah revealed: 'O you who believe! Do not enter the houses of the Prophet...' (33.53)","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ عَبْدِ اللَّهِ الرَّقَاشِيُّ، حَدَّثَنَا مُعْتَمِرُ بْنُ سُلَيْمَانَ، قَالَ سَمِعْتُ أَبِي يَقُولُ، حَدَّثَنَا أَبُو مِجْلَزٍ، عَنْ أَنَسِ بْنِ مَالِكٍ ـ رضى الله عنه ـ قَالَ لَمَّا تَزَوَّجَ رَسُولُ اللَّهِ صلى الله عليه وسلم زَيْنَبَ ابْنَةَ جَحْشٍ دَعَا الْقَوْمَ، فَطَعِمُوا ثُمَّ جَلَسُوا يَتَحَدَّثُونَ وَإِذَا هُوَ كَأَنَّهُ يَتَهَيَّأُ لِلْقِيَامِ فَلَمْ يَقُومُوا، فَلَمَّا رَأَى ذَلِكَ قَامَ، فَلَمَّا قَامَ قَامَ مَنْ قَامَ، وَقَعَدَ ثَلاَثَةُ نَفَرٍ فَجَاءَ النَّبِيُّ صلى الله عليه وسلم لِيَدْخُلَ فَإِذَا الْقَوْمُ جُلُوسٌ ثُمَّ إِنَّهُمْ قَامُوا، فَانْطَلَقْتُ فَجِئْتُ فَأَخْبَرْتُ النَّبِيَّ صلى الله عليه وسلم أَنَّهُمْ قَدِ انْطَلَقُوا، فَجَاءَ حَتَّى دَخَلَ، فَذَهَبْتُ أَدْخُلُ فَأَلْقَى الْحِجَابَ بَيْنِي وَبَيْنَهُ فَأَنْزَلَ اللَّهُ ‏{‏يَا أَيُّهَا الَّذِينَ آمَنُوا لاَ تَدْخُلُوا بُيُوتَ النَّبِيِّ‏}‏ الآيَةَ","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4792","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4792","x":"Narrated Anas bin Malik:\n\nI of all the people know best this verse of Al-Hijab. When Allah's Messenger (ﷺ) married Zainab bint Jahsh she was with him in the house and he prepared a meal and invited the people (to it). They sat down (after finishing their meal) and started chatting. So the Prophet (ﷺ) went out and then returned several times while they were still sitting and talking. So Allah revealed the Verse: 'O you who believe! Enter not the Prophet's houses until leave is given to you for a meal, (and then) not (so early as) to wait for its preparation.....ask them from behind a screen.' (33.53) So the screen was set up and the people went away.","ar":"حَدَّثَنَا سُلَيْمَانُ بْنُ حَرْبٍ، حَدَّثَنَا حَمَّادُ بْنُ زَيْدٍ، عَنْ أَيُّوبَ، عَنْ أَبِي قِلاَبَةَ، قَالَ أَنَسُ بْنُ مَالِكٍ أَنَا أَعْلَمُ النَّاسِ، بِهَذِهِ الآيَةِ آيَةِ الْحِجَابِ، لَمَّا أُهْدِيَتْ زَيْنَبُ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم كَانَتْ مَعَهُ فِي الْبَيْتِ، صَنَعَ طَعَامًا، وَدَعَا الْقَوْمَ، فَقَعَدُوا يَتَحَدَّثُونَ، فَجَعَلَ النَّبِيُّ صلى الله عليه وسلم يَخْرُجُ، ثُمَّ يَرْجِعُ، وَهُمْ قُعُودٌ يَتَحَدَّثُونَ، فَأَنْزَلَ اللَّهُ تَعَالَى ‏{‏يَا أَيُّهَا الَّذِينَ آمَنُوا لاَ تَدْخُلُوا بُيُوتَ النَّبِيِّ إِلاَّ أَنْ يُؤْذَنَ لَكُمْ إِلَى طَعَامٍ غَيْرَ نَاظِرِينَ إِنَاهُ‏}‏ إِلَى قَوْلِهِ ‏{‏مِنْ وَرَاءِ حِجَابٍ‏}‏ فَضُرِبَ الْحِجَابُ، وَقَامَ الْقَوْمُ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 6239","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-6239","x":"Narrated Anas:\n\nWhen the Prophet (ﷺ) married Zainab, the people came and were offered a meal, and then they sat down (after finishing their meals) and started chatting. The Prophet (ﷺ) showed as if he wanted to get up, but they did not get up. When he noticed that, he got up, and some of the people also got up and went away, while some others kept on sitting. When the Prophet (ﷺ) returned to enter, he found the people still sitting, but then they got up and left. So I told the Prophet (ﷺ) of their departure and he came and went in. I intended to go in but the Prophet (ﷺ) put a screen between me and him, for Allah revealed:-- 'O you who believe! Enter not the Prophet's houses..' (33.53)","ar":"حَدَّثَنَا أَبُو النُّعْمَانِ، حَدَّثَنَا مُعْتَمِرٌ، قَالَ أَبِي حَدَّثَنَا أَبُو مِجْلَزٍ، عَنْ أَنَسٍ ـ رضى الله عنه ـ قَالَ لَمَّا تَزَوَّجَ النَّبِيُّ صلى الله عليه وسلم زَيْنَبَ دَخَلَ الْقَوْمُ فَطَعِمُوا، ثُمَّ جَلَسُوا يَتَحَدَّثُونَ فَأَخَذَ كَأَنَّهُ يَتَهَيَّأُ لِلْقِيَامِ فَلَمْ يَقُومُوا، فَلَمَّا رَأَى ذَلِكَ قَامَ، فَلَمَّا قَامَ قَامَ مَنْ قَامَ مِنَ الْقَوْمِ وَقَعَدَ بَقِيَّةُ الْقَوْمِ، وَإِنَّ النَّبِيَّ صلى الله عليه وسلم جَاءَ لِيَدْخُلَ، فَإِذَا الْقَوْمُ جُلُوسٌ، ثُمَّ إِنَّهُمْ قَامُوا فَانْطَلَقُوا فَأَخْبَرْتُ النَّبِيَّ صلى الله عليه وسلم فَجَاءَ حَتَّى دَخَلَ، فَذَهَبْتُ أَدْخُلُ فَأَلْقَى الْحِجَابَ بَيْنِي وَبَيْنَهُ، وَأَنْزَلَ اللَّهُ تَعَالَى ‏{‏يَا أَيُّهَا الَّذِينَ آمَنُوا لاَ تَدْخُلُوا بُيُوتَ النَّبِيِّ‏}‏ الآيَةَ‏.‏ قَالَ أَبُو عَبْد اللَّهِ فِيهِ مِنْ الْفِقْهِ أَنَّهُ لَمْ يَسْتَأْذِنْهُمْ حِينَ قَامَ وَخَرَجَ وَفِيهِ أَنَّهُ تَهَيَّأَ لِلْقِيَامِ وَهُوَ يُرِيدُ أَنْ يَقُومُوا","v":[]},{"c":"Sahih Bukhari","r":"Hadith 6271","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-6271","x":"Narrated Anas bin Malik:\n\nWhen Allah's Messenger (ﷺ) married Zainab bint Jahsh, he invited the people who took their meals and then remained sitting and talking. The Prophet (ﷺ) pretended to be ready to get up, but the people did not get up. When he noticed that, he got up, and when he had got up, some of those people got up along with him and there remained three (who kept on sitting). Then the Prophet (ﷺ) came back and found those people still sitting. Later on those people got up and went away. So I went to the Prophet (ﷺ) and informed him that they had left. The Prophet (ﷺ) came, and entered (his house). I wanted to enter(along with him) but he dropped a curtain between me and him. Allah then revealed: 'O you who believe! Do not enter the Prophet's Houses until leave is given... (to His statement)... Verily! That shall be an enormity, in Allah's sight.' (33.53)","ar":"حَدَّثَنَا الْحَسَنُ بْنُ عُمَرَ، حَدَّثَنَا مُعْتَمِرٌ، سَمِعْتُ أَبِي يَذْكُرُ، عَنْ أَبِي مِجْلَزٍ، عَنْ أَنَسِ بْنِ مَالِكٍ ـ رضى الله عنه ـ قَالَ لَمَّا تَزَوَّجَ رَسُولُ اللَّهِ صلى الله عليه وسلم زَيْنَبَ ابْنَةَ جَحْشٍ دَعَا النَّاسَ طَعِمُوا ثُمَّ جَلَسُوا يَتَحَدَّثُونَ ـ قَالَ ـ فَأَخَذَ كَأَنَّهُ يَتَهَيَّأُ لِلْقِيَامِ فَلَمْ يَقُومُوا، فَلَمَّا رَأَى ذَلِكَ قَامَ، فَلَمَّا قَامَ قَامَ مَنْ قَامَ مَعَهُ مِنَ النَّاسِ، وَبَقِيَ ثَلاَثَةٌ، وَإِنَّ النَّبِيَّ صلى الله عليه وسلم جَاءَ لِيَدْخُلَ فَإِذَا الْقَوْمُ جُلُوسٌ، ثُمَّ إِنَّهُمْ قَامُوا فَانْطَلَقُوا ـ قَالَ ـ فَجِئْتُ فَأَخْبَرْتُ النَّبِيَّ صلى الله عليه وسلم أَنَّهُمْ قَدِ انْطَلَقُوا، فَجَاءَ حَتَّى دَخَلَ فَذَهَبْتُ أَدْخُلُ، فَأَرْخَى الْحِجَابَ بَيْنِي وَبَيْنَهُ، وَأَنْزَلَ اللَّهُ تَعَالَى ‏{‏يَا أَيُّهَا الَّذِينَ آمَنُوا لاَ تَدْخُلُوا بُيُوتَ النَّبِيِّ إِلاَّ أَنْ يُؤْذَنَ لَكُمْ‏}‏ إِلَى قَوْلِهِ ‏{‏إِنَّ ذَلِكُمْ كَانَ عِنْدَ اللَّهِ عَظِيمًا‏}‏‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 1428a","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-1428a","x":"Anas said:\n\nI also saw the wedding feast of Zainab, and he (the Holy Prophet) served bread and meat to the people, and made them eat to their heart's content, and he (the Holy Prophet) sent me to call people, and as he was free (from the ceremony) he stood up and I followed him. Two persons were left and they were busy in talking and did not get out (of the apartment). He (the Holy Prophet) then proceeded towards (the apartments of) his wives. He greeted with as-Salamu 'alaikum to every one of them and said: Members of the household, how are you? They said: Messenger of Allah, we are in good state 'How do you find your family? He would say: In good state. When he was free from (this work of exchanging greetings) he came back, and I also came back along with him. And as he reached the door, (he found) that the two men were still busy in talking. And when they saw him having returned, they stood up and went out; and by Allah! I do not know whether I had informed him, or there was a revelation to him (to the affect) that they had gone. He (the Holy Prophet) then came back and I also returned along with him, and as he put his step on the threshold of his door he hung a curtain between me and him, and (it was on this occasion) that Allah revealed this verse: (\" O you who believe), do not enter the houses of the Prophet unless permission is given to 'you\" (xxxiii. 53).","ar":"قَالَ أَنَسٌ وَشَهِدْتُ وَلِيمَةَ زَيْنَبَ فَأَشْبَعَ النَّاسَ خُبْزًا وَلَحْمًا وَكَانَ يَبْعَثُنِي فَأَدْعُو النَّاسَ فَلَمَّا فَرَغَ قَامَ وَتَبِعْتُهُ فَتَخَلَّفَ رَجُلاَنِ اسْتَأْنَسَ بِهِمَا الْحَدِيثُ لَمْ يَخْرُجَا فَجَعَلَ يَمُرُّ عَلَى نِسَائِهِ فَيُسَلِّمُ عَلَى كُلِّ وَاحِدَةٍ مِنْهُنَّ ‏\"‏ سَلاَمٌ عَلَيْكُمْ كَيْفَ أَنْتُمْ يَا أَهْلَ الْبَيْتِ ‏\"‏ ‏.‏ فَيَقُولُونَ بِخَيْرٍ يَا رَسُولَ اللَّهِ كَيْفَ وَجَدْتَ أَهْلَكَ فَيَقُولُ ‏\"‏ بِخَيْرٍ ‏\"‏ ‏.‏ فَلَمَّا فَرَغَ رَجَعَ وَرَجَعْتُ مَعَهُ فَلَمَّا بَلَغَ الْبَابَ إِذَا هُوَ بِالرَّجُلَيْنِ قَدِ اسْتَأْنَسَ بِهِمَا الْحَدِيثُ فَلَمَّا رَأَيَاهُ قَدْ رَجَعَ قَامَا فَخَرَجَا فَوَاللَّهِ مَا أَدْرِي أَنَا أَخْبَرْتُهُ أَمْ أُنْزِلَ عَلَيْهِ الْوَحْىُ بِأَنَّهُمَا قَدْ خَرَجَا فَرَجَعَ وَرَجَعْتُ مَعَهُ فَلَمَّا وَضَعَ رِجْلَهُ فِي أُسْكُفَّةِ الْبَابِ أَرْخَى الْحِجَابَ بَيْنِي وَبَيْنَهُ وَأَنْزَلَ اللَّهُ تَعَالَى هَذِهِ الآيَةَ ‏{‏ لاَ تَدْخُلُوا بُيُوتَ النَّبِيِّ إِلاَّ أَنْ يُؤْذَنَ لَكُمْ‏}‏ الآيَةَ ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 1428e","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-1428e","x":"Anas b. Malik (Allah be pleased with him) reported:\n\nWhen Allah's Apostle (ﷺ) married Zainab bint jahsh, he invited people (to the wedding feast) and they ate food. They then sat there and entered into conversation. He (the Holy Prophet) made a stir as if he was preparing to stand up, but (the persons busy in talking) did not stand up. When he (the Holy Prophet) saw it, he stood up and when he did so, some other persons stood up. 'Asim and Abd al-A'la in their narrations made this addition: Three (persons) sat there, and Allah's Apostle (ﷺ) came there to enter (the apartment) but he found the people sitting there. Then they stood up and went away. He said: Then I came and informed Allah's Apostle (ﷺ) that they had gone away. He (the Holy Prophet) then came there until he entered (the apartment). I also went and was about to enter, when he hung a curtain between me and him (and it was on this occasion that) Allah, the Exalted and Majestic, revealed this verse:\" O you who believe, enter not the houses of the Prophet unless permission is given to you for a meal, not waiting for its cooking being finished to the (words)\" Surely this is serious in the sight of Allah\" (xxxiii. 53).","ar":"حَدَّثَنَا يَحْيَى بْنُ حَبِيبٍ الْحَارِثِيُّ، وَعَاصِمُ بْنُ النَّضْرِ التَّيْمِيُّ، وَمُحَمَّدُ بْنُ عَبْدِ الأَعْلَى، كُلُّهُمْ عَنْ مُعْتَمِرٍ، - وَاللَّفْظُ لاِبْنِ حَبِيبٍ - حَدَّثَنَا مُعْتَمِرُ بْنُ سُلَيْمَانَ، قَالَ سَمِعْتُ أَبِي، حَدَّثَنَا أَبُو مِجْلَزٍ، عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ لَمَّا تَزَوَّجَ النَّبِيُّ صلى الله عليه وسلم زَيْنَبَ بِنْتَ جَحْشٍ دَعَا الْقَوْمَ فَطَعِمُوا ثُمَّ جَلَسُوا يَتَحَدَّثُونَ - قَالَ - فَأَخَذَ كَأَنَّهُ يَتَهَيَّأُ لِلْقِيَامِ فَلَمْ يَقُومُوا فَلَمَّا رَأَى ذَلِكَ قَامَ فَلَمَّا قَامَ قَامَ مَنْ قَامَ مِنَ الْقَوْمِ ‏.‏ زَادَ عَاصِمٌ وَابْنُ عَبْدِ الأَعْلَى فِي حَدِيثِهِمَا قَالَ فَقَعَدَ ثَلاَثَةٌ وَإِنَّ النَّبِيَّ صلى الله عليه وسلم جَاءَ لِيَدْخُلَ فَإِذَا الْقَوْمُ جُلُوسٌ ثُمَّ إِنَّهُمْ قَامُوا فَانْطَلَقُوا - قَالَ - فَجِئْتُ فَأَخْبَرْتُ النَّبِيَّ صلى الله عليه وسلم أَنَّهُمْ قَدِ انْطَلَقُوا - قَالَ - فَجَاءَ حَتَّى دَخَلَ فَذَهَبْتُ أَدْخُلُ فَأَلْقَى الْحِجَابَ بَيْنِي وَبَيْنَهُ - قَالَ - وَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏{‏ يَا أَيُّهَا الَّذِينَ آمَنُوا لاَ تَدْخُلُوا بُيُوتَ النَّبِيِّ إِلاَّ أَنْ يُؤْذَنَ لَكُمْ إِلَى طَعَامٍ غَيْرَ نَاظِرِينَ إِنَاهُ‏}‏ إِلَى قَوْلِهِ ‏{‏ إِنَّ ذَلِكُمْ كَانَ عِنْدَ اللَّهِ عَظِيمًا‏}‏ ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 1428g","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-1428g","x":"Anas b. Malik (Allah be pleased with him) reported:\n\nAllah's Messenger (ﷺ) contracted marriage and he went to his wife. My mother Umm Sulaim prepared hais and placed it in an earthen vessel and said: Anas, take it to Allah's Messenger (ﷺ) and say: My mother has sent that to you and she offers greetings to you, and says that it is a humble gift for you on our behalf, Messenger of Allah. So I went along with it to Allah's Messenger (ﷺ) and said: My mother offers you salutations, and says that it is a humble gift for you on our behalf. He said: Place it here, and then said: Go and invite on my behalf so and so and anyone whom you meet, and he even named some persons. He (Anas) said: I invited whom he had named and whom I met. I (one of the narrators) said: I said to Anas: How many (persons) were there? He (Anas) said: They were about three hundred persons. Then Allah's Messenger (ﷺ) (said to me): Anas, bring that earthen vessel. They (the guests) then began to enter until the courtyard and the apartment were fully packed. Allah's Messenger (ﷺ) said: Make a circle of ten (guests), and every person should eat from that nearest to him. They began to eat, until they ate to their fill. A group went out (after eating the food), and another group came in until all of them had eaten. He (the Holy Prophet) said to me: Anas, lift it (the earthen vessel), so I lifted it, but I could not assess whether it had more (food) when I placed it (before Allah's Messenger) or when I lifted it (after the people had been served out of it). A group among them (the guests) began to talk in the house of Allah's Messenger (ﷺ) and the Messenger of Allah (ﷺ) was sitting and his wife had been sitting with her face turned towards the wall. It was troublesome for Allah's Messenger (ﷺ), so Allah's Messenger (ﷺ) went out and greeted his wives. He then returned. When they (the guests) saw that Allah's Messenger (ﷺ) had returned they thought that it (their overstay) was something troublesome for him. He (the narrator) said: They hastened towards the door and all of them went out. And there came Allah's Messenger (ﷺ) and he hung a curtain and went in, and I was sitting in his apartment and he did not stay but for a short while. He then came to me and these verses were revealed. Allah's Messenger (ﷺ) came out and recited them to the people:\" O you who believe, enter not the houses of the Prophet unless permission is given to you for a meal, not waiting for its cooking being finished-but when you are invited, enter, and when you have taken food, disperse not seeking to listen to talk. Surely this gives the Prophet trouble\", to the end of verse (xxxiii. 53). (Al-Ja'd said that Anas [b. Malik] stated: I am the first amongst the people to hear these verses), and henceforth the wives of the Apostle (ﷺ) began to observe seclusion (al-hijab).","ar":"حَدَّثَنَا قُتَيْبَةُ بْنُ سَعِيدٍ، حَدَّثَنَا جَعْفَرٌ، - يَعْنِي ابْنَ سُلَيْمَانَ - عَنِ الْجَعْدِ أَبِي عُثْمَانَ، عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ تَزَوَّجَ رَسُولُ اللَّهِ صلى الله عليه وسلم فَدَخَلَ بِأَهْلِهِ - قَالَ - فَصَنَعَتْ أُمِّي أُمُّ سُلَيْمٍ حَيْسًا فَجَعَلَتْهُ فِي تَوْرٍ فَقَالَتْ يَا أَنَسُ اذْهَبْ بِهَذَا إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَقُلْ بَعَثَتْ بِهَذَا إِلَيْكَ أُمِّي وَهْىَ تُقْرِئُكَ السَّلاَمَ وَتَقُولُ إِنَّ هَذَا لَكَ مِنَّا قَلِيلٌ يَا رَسُولَ اللَّهِ - قَالَ - فَذَهَبْتُ بِهَا إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَقُلْتُ إِنَّ أُمِّي تُقْرِئُكَ السَّلاَمَ وَتَقُولُ إِنَّ هَذَا لَكَ مِنَّا قَلِيلٌ يَا رَسُولَ اللَّهِ ‏.‏ فَقَالَ ‏\"‏ ضَعْهُ - ثُمَّ قَالَ - اذْهَبْ فَادْعُ لِي فُلاَنًا وَفُلاَنًا وَفُلاَنًا وَمَنْ لَقِيتَ ‏\"‏ ‏.‏ وَسَمَّى رِجَالاً - قَالَ - فَدَعَوْتُ مَنْ سَمَّى وَمَنْ لَقِيتُ ‏.‏ قَالَ قُلْتُ لأَنَسٍ عَدَدَ كَمْ كَانُوا قَالَ زُهَاءَ ثَلاَثِمِائَةٍ ‏.‏ وَقَالَ لِي رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ يَا أَنَسُ هَاتِ التَّوْرَ ‏\"‏ ‏.‏ قَالَ فَدَخَلُوا حَتَّى امْتَلأَتِ الصُّفَّةُ وَالْحُجْرَةُ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ لِيَتَحَلَّقْ عَشَرَةٌ عَشَرَةٌ وَلْيَأْكُلْ كُلُّ إِنْسَانٍ مِمَّا يَلِيهِ ‏\"‏ ‏.‏ قَالَ فَأَكَلُوا حَتَّى شَبِعُوا - قَالَ - فَخَرَجَتْ طَائِفَةٌ وَدَخَلَتْ طَائِفَةٌ حَتَّى أَكَلُوا كُلُّهُمْ ‏.‏ فَقَالَ لِي ‏\"‏ يَا أَنَسُ ارْفَعْ ‏\"‏ ‏.‏ قَالَ فَرَفَعْتُ فَمَا أَدْرِي حِينَ وَضَعْتُ كَانَ أَكْثَرَ أَمْ حِينَ رَفَعْتُ - قَالَ - وَجَلَسَ طَوَائِفُ مِنْهُمْ يَتَحَدَّثُونَ فِي بَيْتِ رَسُولِ اللَّهِ صلى الله عليه وسلم وَرَسُولُ اللَّهِ صلى الله عليه وسلم جَالِسٌ وَزَوْجَتُهُ مُوَلِّيَةٌ وَجْهَهَا إِلَى الْحَائِطِ فَثَقُلُوا عَلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَخَرَجَ رَسُولُ اللَّهِ صلى الله عليه وسلم فَسَلَّمَ عَلَى نِسَائِهِ ثُمَّ رَجَعَ فَلَمَّا رَأَوْا رَسُولَ اللَّهِ صلى الله عليه وسلم قَدْ رَجَعَ ظَنُّوا أَنَّهُمْ قَدْ ثَقُلُوا عَلَيْهِ - قَالَ - فَابْتَدَرُوا الْبَابَ فَخَرَجُوا كُلُّهُمْ وَجَاءَ رَسُولُ اللَّهِ صلى الله عليه وسلم َتَّى أَرْخَى السِّتْرَ وَدَخَلَ وَأَنَا جَالِسٌ فِي الْحُجْرَةِ فَلَمْ يَلْبَثْ إِلاَّ يَسِيرًا حَتَّى خَرَجَ عَلَىَّ ‏.‏ وَأُنْزِلَتْ هَذِهِ الآيَةُ فَخَرَجَ رَسُولُ اللَّهِ صلى الله عليه وسلم وَقَرَأَهُنَّ عَلَى النَّاسِ ‏{‏ يَا أَيُّهَا الَّذِينَ آمَنُوا لاَ تَدْخُلُوا بُيُوتَ النَّبِيِّ إِلاَّ أَنْ يُؤْذَنَ لَكُمْ إِلَى طَعَامٍ غَيْرَ نَاظِرِينَ إِنَاهُ وَلَكِنْ إِذَا دُعِيتُمْ فَادْخُلُوا فَإِذَا طَعِمْتُمْ فَانْتَشِرُوا وَلاَ مُسْتَأْنِسِينَ لِحَدِيثٍ إِنَّ ذَلِكُمْ كَانَ يُؤْذِي النَّبِيَّ‏}‏ إِلَى آخِرِ الآيَةِ ‏.‏ قَالَ الْجَعْدُ قَالَ أَنَسُ بْنُ مَالِكٍ أَنَا أَحْدَثُ النَّاسِ عَهْدًا بِهَذِهِ الآيَاتِ وَحُجِبْنَ نِسَاءُ النَّبِيِّ صلى الله عليه وسلم ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3218","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3218","x":"Narrated Al-Ja'd bin Abi 'Uthman:\n\nfrom Anas bin Malik: \"The Messenger of Allah (ﷺ) got married, and he went in with his wife.\" He said: \"So my mother, Umm Sulaim prepared some Hais in a Tawr (a vessel made of brass and stone) and said: 'O Anas! Take this to the Prophet (ﷺ).' I said to him: 'My mother sent this to you, and she conveys her Salam, and says: 'This is a little something from us for you.'\" He said: 'Put it down.' Then he said: 'Go and invite so-and-so, so-and-so, and so-and-so for me, and whomever you meet.'\" He named some people, and said: \"I invited those he named, and whomever I met.\" - He (Al-Ja'd) said: \"I said to Anas: 'How many of you were there?' He said: 'Roughly about three-hundred.'\" - He (Anas) said: \"The Messenger of Allah (ﷺ) said to me: 'O Anas! Bring me the Tawr.'\" He said: \"They entered until the Suffah (a shaded part of the Masjid in Al-Madinah) and the apartment were full. The Messenger of Allah (ﷺ) said: 'Let groups of ten in, and let each person eat what is near him.'\" He said: \"They ate until they were full.\" He said: \"A group exited, and another group entered, until all of them ate.'\" He said: \"He said to me: 'O Anas! Remove it.'\" He said: \"So I took it. I could not tell if there was more when I first put it down, or when I picked it up.\" He said: \"Groups of them sat talking in the house of the Messenger of Allah (ﷺ), while the Messenger of Allah (ﷺ) and his wife sat facing the wall. They began to be burdensome on the Messenger of Allah (ﷺ), so the Messenger of Allah (ﷺ) went out to greet his women folk, then he returned, they realized that they had overburdened him, so they hastened for the gate and all of them exited. The Messenger of Allah (ﷺ) came until he lowered the curtain, and entered while I was sitting in the apartment. He did not remain there long before he left me, and these Ayat were revealed. So the Messenger of Allah (ﷺ) went out to recite them to the people: 'O you who believe! Do not enter the Prophet's house unless permission is given to you for a meal, not to wait for its preparation. But when you are invited, enter, and when you have taken your meals, dispense without sitting for a talk. Verily, such annoys the Prophet...' till the end of the Ayah (33:53)' Al-Ja'd said: \"Anas said: 'I am the earliest of the people to encounter these Ayat, and to be screened from the wives of the Prophet (ﷺ).\"","ar":"حَدَّثَنَا قُتَيْبَةُ بْنُ سَعِيدٍ، حَدَّثَنَا جَعْفَرُ بْنُ سُلَيْمَانَ الضُّبَعِيُّ، عَنِ الْجَعْدِ بْنِ عُثْمَانَ، عَنْ أَنَسِ بْنِ مَالِكٍ، رضى الله عنه قَالَ تَزَوَّجَ رَسُولُ اللَّهِ صلى الله عليه وسلم فَدَخَلَ بِأَهْلِهِ - قَالَ - فَصَنَعَتْ أُمِّي أُمُّ سُلَيْمٍ حَيْسًا فَجَعَلَتْهُ فِي تَوْرٍ فَقَالَتْ يَا أَنَسُ اذْهَبْ بِهَذَا إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَقُلْ لَهُ بَعَثَتْ إِلَيْكَ بِهَا أُمِّي وَهِيَ تُقْرِئُكَ السَّلاَمَ وَتَقُولُ إِنَّ هَذَا لَكَ مِنَّا قَلِيلٌ يَا رَسُولَ اللَّهِ ‏.‏ قَالَ فَذَهَبْتُ بِهِ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَقُلْتُ إِنَّ أُمِّي تُقْرِئُكَ السَّلاَمَ وَتَقُولُ إِنَّ هَذَا مِنَّا لَكَ قَلِيلٌ ‏.‏ فَقَالَ ‏\"‏ ضَعْهُ ‏\"‏ ‏.‏ ثُمَّ قَالَ ‏\"‏ اذْهَبْ فَادْعُ لِي فُلاَنًا وَفُلاَنًا وَفُلاَنًا وَمَنْ لَقِيتَ ‏\"‏ ‏.‏ فَسَمَّى رِجَالاً قَالَ فَدَعَوْتُ مَنْ سَمَّى وَمَنْ لَقِيتُ قَالَ قُلْتُ لأَنَسٍ عَدَدُكُمْ كَمْ كَانُوا قَالَ زُهَاءَ ثَلاَثِمِائَةٍ ‏.‏ قَالَ وَقَالَ لِي رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ يَا أَنَسُ هَاتِ التَّوْرَ ‏\"‏ ‏.‏ قَالَ فَدَخَلُوا حَتَّى امْتَلأَتِ الصُّفَّةُ وَالْحُجْرَةُ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ لِيَتَحَلَّقْ عَشَرَةٌ عَشَرَةٌ وَلْيَأْكُلْ كُلُّ إِنْسَانٍ مِمَّا يَلِيهِ ‏\"‏ ‏.‏ قَالَ فَأَكَلُوا حَتَّى شَبِعُوا قَالَ فَخَرَجَتْ طَائِفَةٌ وَدَخَلَتْ طَائِفَةٌ حَتَّى أَكَلُوا كُلُّهُمْ ‏.‏ قَالَ فَقَالَ لِي ‏\"‏ يَا أَنَسُ ارْفَعْ ‏\"‏ ‏.‏ قَالَ فَرَفَعْتُ فَمَا أَدْرِي حِينَ وَضَعْتُ كَانَ أَكْثَرَ أَمْ حِينَ رَفَعْتُ قَالَ وَجَلَسَ مِنْهُمْ طَوَائِفُ يَتَحَدَّثُونَ فِي بَيْتِ رَسُولِ اللَّهِ صلى الله عليه وسلم وَرَسُولُ اللَّهِ صلى الله عليه وسلم جَالِسٌ وَزَوْجَتُهُ مُوَلِّيَةٌ وَجْهَهَا إِلَى الْحَائِطِ فَثَقُلُوا عَلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَخَرَجَ رَسُولُ اللَّهِ صلى الله عليه وسلم فَسَلَّمَ عَلَى نِسَائِهِ ثُمَّ رَجَعَ فَلَمَّا رَأَوْا رَسُولَ اللَّهِ صلى الله عليه وسلم قَدْ رَجَعَ ظَنُّوا أَنَّهُمْ قَدْ ثَقُلُوا عَلَيْهِ قَالَ فَابْتَدَرُوا الْبَابَ فَخَرَجُوا كُلُّهُمْ وَجَاءَ رَسُولُ اللَّهِ صلى الله عليه وسلم حَتَّى أَرْخَى السِّتْرَ وَدَخَلَ وَأَنَا جَالِسٌ فِي الْحُجْرَةِ فَلَمْ يَلْبَثْ إِلاَّ يَسِيرًا حَتَّى خَرَجَ عَلَىَّ وَأُنْزِلَتْ هَذِهِ الآيَاتُ فَخَرَجَ رَسُولُ اللَّهِ صلى الله عليه وسلم فَقَرَأَهُنَّ عَلَى النَّاسِ ‏:‏ ‏(‏ يا أَيُّهَا الَّذِينَ آمَنُوا لاَ تَدْخُلُوا بُيُوتَ النَّبِيِّ إِلاَّ أَنْ يُؤْذَنَ لَكُمْ إِلَى طَعَامٍ غَيْرَ نَاظِرِينَ إِنَاهُ ‏)‏ إِلَى آخِرِ الآيَةِ ‏.‏ قَالَ الْجَعْدُ قَالَ أَنَسٌ أَنَا أَحْدَثُ النَّاسِ عَهْدًا بِهَذِهِ الآيَاتِ وَحُجِبْنَ نِسَاءُ رَسُولِ اللَّهِ صلى الله عليه وسلم ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏ وَالْجَعْدُ هُوَ ابْنُ عُثْمَانَ وَيُقَالُ هُوَ ابْنُ دِينَارٍ وَيُكْنَى أَبَا عُثْمَانَ بَصْرِيٌّ وَهُوَ ثِقَةٌ عِنْدَ أَهْلِ الْحَدِيثِ رَوَى عَنْهُ يُونُسُ بْنُ عُبَيْدٍ وَشُعْبَةُ وَحَمَّادُ بْنُ زَيْدٍ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3219","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3219","x":"Narrated Anas bin Malik:\n\n\"The Messenger of Allah (ﷺ) was staying with one of his wives, so he sent me to invite people for a meal. When they ate and left, the Messenger of Allah (ﷺ) stood and went off in the direction of 'Aishah's house. He saw two men (still) sitting, so he turned to come back, then the two men stood up to leave. So Allah [the Mighty and Sublime] revealed: 'O you who believe! Do not enter the Prophet's house unless permission is given to you for a meal, not to wait for its preparation (33:53).\" And there is a long story with the narration.","ar":"حَدَّثَنَا عُمَرُ بْنُ إِسْمَاعِيلَ بْنِ مُجَالِدٍ، حَدَّثَنِي أَبِي، عَنْ بَيَانٍ، عَنْ أَنَسِ بْنِ مَالِكٍ، رضى الله عنه قَالَ بَنَى رَسُولُ اللَّهِ صلى الله عليه وسلم بِامْرَأَةٍ مِنْ نِسَائِهِ فَأَرْسَلَنِي فَدَعَوْتُ قَوْمًا إِلَى الطَّعَامِ فَلَمَّا أَكَلُوا وَخَرَجُوا قَامَ رَسُولُ اللَّهِ صلى الله عليه وسلم مُنْطَلِقًا قِبَلَ بَيْتِ عَائِشَةَ فَرَأَى رَجُلَيْنِ جَالِسَيْنِ فَانْصَرَفَ رَاجِعًا فَقَامَ الرَّجُلاَنِ فَخَرَجَا فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏:‏ ‏(‏ يا أَيُّهَا الَّذِينَ آمَنُوا لاَ تَدْخُلُوا بُيُوتَ النَّبِيِّ إِلاَّ أَنْ يُؤْذَنَ لَكُمْ إِلَى طَعَامٍ غَيْرَ نَاظِرِينَ إِنَاهُ ‏)‏ وَفِي الْحَدِيثِ قِصَّةٌ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ غَرِيبٌ مِنْ حَدِيثِ بَيَانٍ ‏.‏ وَرَوَى ثَابِتٌ عَنْ أَنَسٍ هَذَا الْحَدِيثَ بِطُولِهِ ‏.‏","v":[]}],"59":[{"c":"Sunan Abu Dawud","r":"Hadith 4113","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-4113","x":"Narrated 'Amr b. Suh'aib:\n\nOn his father's authority, said that his grandfather reported the Prophet (ﷺ) said: When one of you marries his male-slave to his slave-woman, he should not look at her private parts.","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ الْمَيْمُونِ، حَدَّثَنَا الْوَلِيدُ، عَنِ الأَوْزَاعِيِّ، عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏\n\n\"‏ إِذَا زَوَّجَ أَحَدُكُمْ عَبْدَهُ أَمَتَهُ فَلاَ يَنْظُرْ إِلَى عَوْرَتِهَا ‏\"\n\n‏ ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 146","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-146","x":"Narrated `Aisha:\n\nThe wives of the Prophet (ﷺ) used to go to Al-Manasi, a vast open place (near Baqi` at Medina) to answer the call of nature at night. `Umar used to say to the Prophet (ﷺ) \"Let your wives be veiled,\" but Allah's Apostle did not do so. One night Sauda bint Zam`a the wife of the Prophet (ﷺ) went out at `Isha' time and she was a tall lady. `Umar addressed her and said, \"I have recognized you, O Sauda.\" He said so, as he desired eagerly that the verses of Al-Hijab (the observing of veils by the Muslim women) may be revealed. So Allah revealed the verses of \"Al-Hijab\" (A complete body cover excluding the eyes).","ar":"حَدَّثَنَا يَحْيَى بْنُ بُكَيْرٍ، قَالَ حَدَّثَنَا اللَّيْثُ، قَالَ حَدَّثَنِي عُقَيْلٌ، عَنِ ابْنِ شِهَابٍ، عَنْ عُرْوَةَ، عَنْ عَائِشَةَ، أَنَّ أَزْوَاجَ النَّبِيِّ، صلى الله عليه وسلم كُنَّ يَخْرُجْنَ بِاللَّيْلِ إِذَا تَبَرَّزْنَ إِلَى الْمَنَاصِعِ ـ وَهُوَ صَعِيدٌ أَفْيَحُ ـ فَكَانَ عُمَرُ يَقُولُ لِلنَّبِيِّ صلى الله عليه وسلم احْجُبْ نِسَاءَكَ‏.‏ فَلَمْ يَكُنْ رَسُولُ اللَّهِ صلى الله عليه وسلم يَفْعَلُ، فَخَرَجَتْ سَوْدَةُ بِنْتُ زَمْعَةَ زَوْجُ النَّبِيِّ صلى الله عليه وسلم لَيْلَةً مِنَ اللَّيَالِي عِشَاءً، وَكَانَتِ امْرَأَةً طَوِيلَةً، فَنَادَاهَا عُمَرُ أَلاَ قَدْ عَرَفْنَاكِ يَا سَوْدَةُ‏.‏ حِرْصًا عَلَى أَنْ يَنْزِلَ الْحِجَابُ، فَأَنْزَلَ اللَّهُ آيَةَ الْحِجَابِ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3217","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3217","x":"Narrated Anas bin Malik:\n\n\"I was with the Prophet (ﷺ), and he came to the door of a woman with whom he had consummated marriage, and some people were with her. So, he left to fulfill his need, and was prevented (from her). Then he came back, and some people were still with her. Then he left to fulfill his need and came back and they had gone.\" He said: \"So, I mentioned that to Abu Talhah and he said: 'If it is as you say, something shall surely be revealed concerning this,' and the Verse of Hijab was revealed.","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ الْمُثَنَّى، حَدَّثَنَا أَشْهَلُ بْنُ حَاتِمٍ، قَالَ ابْنُ عَوْنٍ حُدِّثْنَاهُ عَنْ عَمْرِو بْنِ سَعِيدٍ، عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ كُنْتُ عِنْدَ النَّبِيِّ صلى الله عليه وسلم فَأَتَى بَابَ امْرَأَةٍ عَرَّسَ بِهَا فَإِذَا عِنْدَهَا قَوْمٌ فَانْطَلَقَ فَقَضَى حَاجَتَهُ فَاحْتَبَسَ ثُمَّ رَجَعَ وَعِنْدَهَا قَوْمٌ فَانْطَلَقَ فَقَضَى حَاجَتَهُ فَرَجَعَ وَقَدْ خَرَجُوا قَالَ فَدَخَلَ وَأَرْخَى بَيْنِي وَبَيْنَهُ سِتْرًا قَالَ فَذَكَرْتُهُ لأَبِي طَلْحَةَ قَالَ فَقَالَ لَئِنْ كَانَ كَمَا تَقُولُ لَيَنْزِلَنَّ فِي هَذَا شَيْءٌ ‏.‏ فَنَزَلَتْ آيَةُ الْحِجَابِ ‏.‏ هَذَا حَدِيثٌ حَسَنٌ غَرِيبٌ مِنْ هَذَا الْوَجْهِ ‏.‏","v":[]}],"69":[{"c":"Sahih Bukhari","r":"Hadith 3404","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-3404","x":"Narrated Abu Huraira:\n\nAllah's Messenger (ﷺ) said, \"(The Prophet) Moses was a shy person and used to cover his body completely because of his extensive shyness. One of the children of Israel hurt him by saying, 'He covers his body in this way only because of some defect in his skin, either leprosy or scrotal hernia, or he has some other defect.' Allah wished to clear Moses of what they said about him, so one day while Moses was in seclusion, he took off his clothes and put them on a stone and started taking a bath. When he had finished the bath, he moved towards his clothes so as to take them, but the stone took his clothes and fled; Moses picked up his stick and ran after the stone saying, 'O stone! Give me my garment!' Till he reached a group of Bani Israel who saw him naked then, and found him the best of what Allah had created, and Allah cleared him of what they had accused him of. The stone stopped there and Moses took and put his garment on and started hitting the stone with his stick. By Allah, the stone still has some traces of the hitting, three, four or five marks. This was what Allah refers to in His Saying:-- \"O you who believe! Be you not like those Who annoyed Moses, But Allah proved his innocence of that which they alleged, And he was honorable In Allah's Sight.\" (33.69)","ar":"حَدَّثَنِي إِسْحَاقُ بْنُ إِبْرَاهِيمَ، حَدَّثَنَا رَوْحُ بْنُ عُبَادَةَ، حَدَّثَنَا عَوْفٌ، عَنِ الْحَسَنِ، وَمُحَمَّدٍ، وَخِلاَسٍ، عَنْ أَبِي هُرَيْرَةَ ـ رضى الله عنه ـ قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ إِنَّ مُوسَى كَانَ رَجُلاً حَيِيًّا سِتِّيرًا، لاَ يُرَى مِنْ جِلْدِهِ شَىْءٌ، اسْتِحْيَاءً مِنْهُ، فَآذَاهُ مَنْ آذَاهُ مِنْ بَنِي إِسْرَائِيلَ، فَقَالُوا مَا يَسْتَتِرُ هَذَا التَّسَتُّرَ إِلاَّ مِنْ عَيْبٍ بِجِلْدِهِ، إِمَّا بَرَصٌ وَإِمَّا أُدْرَةٌ وَإِمَّا آفَةٌ‏.‏ وَإِنَّ اللَّهَ أَرَادَ أَنْ يُبَرِّئَهُ مِمَّا قَالُوا لِمُوسَى فَخَلاَ يَوْمًا وَحْدَهُ فَوَضَعَ ثِيَابَهُ عَلَى الْحَجَرِ ثُمَّ اغْتَسَلَ، فَلَمَّا فَرَغَ أَقْبَلَ إِلَى ثِيَابِهِ لِيَأْخُذَهَا، وَإِنَّ الْحَجَرَ عَدَا بِثَوْبِهِ، فَأَخَذَ مُوسَى عَصَاهُ وَطَلَبَ الْحَجَرَ، فَجَعَلَ يَقُولُ ثَوْبِي حَجَرُ، ثَوْبِي حَجَرُ، حَتَّى انْتَهَى إِلَى مَلإٍ مِنْ بَنِي إِسْرَائِيلَ، فَرَأَوْهُ عُرْيَانًا أَحْسَنَ مَا خَلَقَ اللَّهُ، وَأَبْرَأَهُ مِمَّا يَقُولُونَ، وَقَامَ الْحَجَرُ فَأَخَذَ ثَوْبَهُ فَلَبِسَهُ، وَطَفِقَ بِالْحَجَرِ ضَرْبًا بِعَصَاهُ، فَوَاللَّهِ إِنَّ بِالْحَجَرِ لَنَدَبًا مِنْ أَثَرِ ضَرْبِهِ ثَلاَثًا أَوْ أَرْبَعًا أَوْ خَمْسًا، فَذَلِكَ قَوْلُهُ ‏{‏يَا أَيُّهَا الَّذِينَ آمَنُوا لاَ تَكُونُوا كَالَّذِينَ آذَوْا مُوسَى فَبَرَّأَهُ اللَّهُ مِمَّا قَالُوا وَكَانَ عِنْدَ اللَّهِ وَجِيهًا‏}‏‏.‏‏\"‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4799","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4799","x":"Narrated Abu Huraira:\n\nAllah's Messenger (ﷺ) said, \"Moses was a shy man, and that is what the Statement of Allah means: 'O you who believe Be not like those who annoyed Moses, but Allah proved his innocence of that which they alleged and he was honorable in Allah's Sight.' (33.69)","ar":"حَدَّثَنَا إِسْحَاقُ بْنُ إِبْرَاهِيمَ، أَخْبَرَنَا رَوْحُ بْنُ عُبَادَةَ، حَدَّثَنَا عَوْفٌ، عَنِ الْحَسَنِ، وَمُحَمَّدٍ، وَخِلاَسٍ، عَنْ أَبِي هُرَيْرَةَ ـ رضى الله عنه ـ قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ إِنَّ مُوسَى كَانَ رَجُلاً حَيِيًّا، وَذَلِكَ قَوْلُهُ تَعَالَى ‏{‏يَا أَيُّهَا الَّذِينَ آمَنُوا لاَ تَكُونُوا كَالَّذِينَ آذَوْا مُوسَى فَبَرَّأَهُ اللَّهُ مِمَّا قَالُوا وَكَانَ عِنْدَ اللَّهِ وَجِيهًا‏}‏‏\"‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 339c","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-339c","x":"Abu Huraira reported that Moses was a modest person. He was never seen naked and Banu Isra'iI said:\n\n(He was afraid to expose his private part) because he had been suffering from scrotal hernia. He (one day) took bath in water and placed his garments upon a stone. The stone began to move on quickly. He followed that and struck it with the help of a stone (saying): O stone, my garment; O stone, my garments, O stone; until it stopped near the big gathering of Isrii'll, and this verse was revealed (pertaining to the incident):\" O you who believe, be not Iike those who maligned Moses, but Allah cleared him of what they said, and he was worthy of regard with Allah\" (xxxiii. 69).","ar":"وَحَدَّثَنَا يَحْيَى بْنُ حَبِيبٍ الْحَارِثِيُّ، حَدَّثَنَا يَزِيدُ بْنُ زُرَيْعٍ، حَدَّثَنَا خَالِدٌ الْحَذَّاءُ، عَنْ عَبْدِ اللَّهِ بْنِ شَقِيقٍ، قَالَ أَنْبَأَنَا أَبُو هُرَيْرَةَ، قَالَ كَانَ مُوسَى عَلَيْهِ السَّلاَمُ رَجُلاً حَيِيًّا - قَالَ - فَكَانَ لاَ يُرَى مُتَجَرِّدًا - قَالَ - فَقَالَ بَنُو إِسْرَائِيلَ إِنَّهُ آدَرُ - قَالَ - فَاغْتَسَلَ عِنْدَ مُوَيْهٍ فَوَضَعَ ثَوْبَهُ عَلَى حَجَرٍ فَانْطَلَقَ الْحَجَرُ يَسْعَى وَاتَّبَعَهُ بِعَصَاهُ يَضْرِبُهُ ثَوْبِي حَجَرُ ثَوْبِي حَجَرُ ‏.‏ حَتَّى وَقَفَ عَلَى مَلإٍ مِنْ بَنِي إِسْرَائِيلَ وَنَزَلَتْ ‏{‏ يَا أَيُّهَا الَّذِينَ آمَنُوا لاَ تَكُونُوا كَالَّذِينَ آذَوْا مُوسَى فَبَرَّأَهُ اللَّهُ مِمَّا قَالُوا وَكَانَ عِنْدَ اللَّهِ وَجِيهًا‏}‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3221","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3221","x":"Narrated Abu Hurairah:\n\nthat the Prophet (ﷺ) said: \"Verily Musa, peace be upon him, was a shy and modest man, who would never show anything of his skin out of modesty. Some of the Children of Isra'il annoyed him by saying: 'He only keeps himself covered because of some defect in his skin, either leprosy, a scrotal hernia or some other defect.' Allah [the Mighty and Sublime] wanted to free Musa from what they were saying about him. One day Musa, [peace be upon him], was alone. He took off his garment, and put it on a rock, then he took a bath. When he had finished, he turned back to pick up his garment, but the rock moved away, taking his garment with it. Musa picked up his staff, and chased the rock saying: 'My garment, O you rock! My garment, O you rock!' Until he reached a group of the Children of Isra'il who saw him naked, and discovered that he was the best of those whom Allah had created.\" He said: \"The rock stood still, he took his garment and put it on. He started striking the rock with his staff, and by Allah, the marks of that beating were left on the rock; three, four, or five. This is what is referred to in the Ayah: ' O you who believe! Be not like those who annoyed Musa, but Allah freed him from what they had alleged, and he was honourable before Allah (33:69).'\"","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، حَدَّثَنَا رَوْحُ بْنُ عُبَادَةَ، عَنْ عَوْفٍ، عَنِ الْحَسَنِ، وَمُحَمَّدٍ، وَخِلاَسٍ، عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صلى الله عليه وسلم ‏\"‏ أَنَّ مُوسَى عَلَيْهِ السَّلاَمُ كَانَ رَجُلاً حَيِيًّا سِتِّيرًا مَا يُرَى مِنْ جِلْدِهِ شَيْءٌ اسْتِحْيَاءً مِنْهُ فَآذَاهُ مَنْ آذَاهُ مِنْ بَنِي إِسْرَائِيلَ فَقَالُوا مَا يَسْتَتِرُ هَذَا السِّتْرَ إِلاَّ مِنْ عَيْبٍ بِجِلْدِهِ إِمَّا بَرَصٌ وَإِمَّا أُدْرَةٌ وَإِمَّا آفَةٌ وَإِنَّ اللَّهَ عَزَّ وَجَلَّ أَرَادَ أَنْ يُبَرِّئَهُ مِمَّا قَالُوا وَإِنَّ مُوسَى عَلَيْهِ السَّلاَمُ خَلاَ يَوْمًا وَحْدَهُ فَوَضَعَ ثِيَابَهُ عَلَى حَجَرٍ ثُمَّ اغْتَسَلَ فَلَمَّا فَرَغَ أَقْبَلَ إِلَى ثِيَابِهِ لِيَأْخُذَهَا وَإِنَّ الْحَجَرَ عَدَا بِثَوْبِهِ فَأَخَذَ مُوسَى عَصَاهُ فَطَلَبَ الْحَجَرَ فَجَعَلَ يَقُولُ ثَوْبِي حَجَرُ ثَوْبِي حَجَرُ حَتَّى انْتَهَى إِلَى مَلإٍ مِنْ بَنِي إِسْرَائِيلَ فَرَأَوْهُ عُرْيَانًا أَحْسَنَ النَّاسِ خَلْقًا وَأَبْرَأَهُ مِمَّا كَانُوا يَقُولُونَ قَالَ وَقَامَ الْحَجَرُ فَأَخَذَ ثَوْبَهُ وَلَبِسَهُ وَطَفِقَ بِالْحَجَرِ ضَرْبًا بِعَصَاهُ فَوَاللَّهِ إِنَّ بِالْحَجَرِ لَنَدَبًا مِنْ أَثَرِ عَصَاهُ ثَلاَثًا أَوْ أَرْبَعًا أَوْ خَمْسًا فَذَلِكَ قَوْلُهُ تَعَالَى ‏:‏ ‏(‏ يا أَيُّهَا الَّذِينَ آمَنُوا لاَ تَكُونُوا كَالَّذِينَ آذَوْا مُوسَى فَبَرَّأَهُ اللَّهُ مِمَّا قَالُوا وَكَانَ عِنْدَ اللَّهِ وَجِيهًا ‏)‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ وَقَدْ رُوِيَ مِنْ غَيْرِ وَجْهٍ عَنْ أَبِي هُرَيْرَةَ عَنِ النَّبِيِّ صلى الله عليه وسلم وَفِيهِ عَنْ أَنَسٍ عَنِ النَّبِيِّ صلى الله عليه وسلم ‏.‏","v":[]}]};